//! Exact decimal handling for JSON numbers (arbitrary precision strings).
use serde_json::Number;
use std::cmp::Ordering;

/// A decimal value: (-1)^neg * digits * 10^exp, digits without leading/trailing zeros.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Dec {
    pub neg: bool,
    pub digits: Vec<u8>, // most significant first, no leading zeros, no trailing zeros; empty = zero
    pub exp: i64,
}

impl Dec {
    pub fn zero() -> Dec {
        Dec { neg: false, digits: vec![], exp: 0 }
    }
    pub fn is_zero(&self) -> bool {
        self.digits.is_empty()
    }
    pub fn parse(s: &str) -> Option<Dec> {
        let b = s.as_bytes();
        let mut i = 0;
        let mut neg = false;
        if i < b.len() && (b[i] == b'-' || b[i] == b'+') {
            neg = b[i] == b'-';
            i += 1;
        }
        let mut digits: Vec<u8> = Vec::new();
        let mut exp: i64 = 0;
        let mut seen_digit = false;
        while i < b.len() && b[i].is_ascii_digit() {
            digits.push(b[i] - b'0');
            seen_digit = true;
            i += 1;
        }
        if i < b.len() && b[i] == b'.' {
            i += 1;
            while i < b.len() && b[i].is_ascii_digit() {
                digits.push(b[i] - b'0');
                exp -= 1;
                seen_digit = true;
                i += 1;
            }
        }
        if !seen_digit {
            return None;
        }
        if i < b.len() && (b[i] == b'e' || b[i] == b'E') {
            i += 1;
            let mut eneg = false;
            if i < b.len() && (b[i] == b'-' || b[i] == b'+') {
                eneg = b[i] == b'-';
                i += 1;
            }
            let mut e: i64 = 0;
            let mut any = false;
            while i < b.len() && b[i].is_ascii_digit() {
                any = true;
                if e < 1_000_000_000_000 {
                    e = e * 10 + (b[i] - b'0') as i64;
                }
                i += 1;
            }
            if !any {
                return None;
            }
            exp += if eneg { -e } else { e };
        }
        if i != b.len() {
            return None;
        }
        // strip leading zeros
        let first = digits.iter().position(|&d| d != 0);
        match first {
            None => return Some(Dec::zero()),
            Some(p) => {
                digits.drain(0..p);
            }
        }
        while let Some(&0) = digits.last() {
            digits.pop();
            exp += 1;
        }
        Some(Dec { neg, digits, exp })
    }

    pub fn from_f64(f: f64) -> Dec {
        if f == 0.0 || !f.is_finite() {
            if f.is_infinite() {
                // represent as huge
                let mut d = Dec::parse("1e400").unwrap();
                d.neg = f < 0.0;
                return d;
            }
            return Dec::zero();
        }
        // exact conversion of binary double to decimal
        let bits = f.to_bits();
        let neg = (bits >> 63) != 0;
        let exp_bits = ((bits >> 52) & 0x7ff) as i64;
        let mant = bits & 0xfffffffffffff;
        let (m, e2) = if exp_bits == 0 { (mant, -1074i64) } else { (mant | (1u64 << 52), exp_bits - 1075) };
        // value = m * 2^e2
        let mut big = BigUint::from_u64(m);
        let mut dec_exp: i64 = 0;
        if e2 >= 0 {
            for _ in 0..e2 {
                big.mul_small(2);
            }
        } else {
            // m * 2^e2 = m * 5^(-e2) * 10^(e2)
            for _ in 0..(-e2) {
                big.mul_small(5);
            }
            dec_exp = e2;
        }
        let s = big.to_dec_string();
        let mut d = Dec::parse(&s).unwrap();
        d.exp += dec_exp;
        d.neg = neg;
        d
    }

    /// Magnitude order: position of the most significant digit (digits.len() + exp)
    fn mag(&self) -> i64 {
        self.digits.len() as i64 + self.exp
    }

    pub fn cmp_abs(&self, other: &Dec) -> Ordering {
        match (self.is_zero(), other.is_zero()) {
            (true, true) => return Ordering::Equal,
            (true, false) => return Ordering::Less,
            (false, true) => return Ordering::Greater,
            _ => {}
        }
        let (ma, mb) = (self.mag(), other.mag());
        if ma != mb {
            return ma.cmp(&mb);
        }
        let n = self.digits.len().max(other.digits.len());
        for i in 0..n {
            let a = *self.digits.get(i).unwrap_or(&0);
            let b = *other.digits.get(i).unwrap_or(&0);
            if a != b {
                return a.cmp(&b);
            }
        }
        Ordering::Equal
    }

    pub fn cmp(&self, other: &Dec) -> Ordering {
        let sa = if self.is_zero() { 0 } else if self.neg { -1 } else { 1 };
        let sb = if other.is_zero() { 0 } else if other.neg { -1 } else { 1 };
        if sa != sb {
            return sa.cmp(&sb);
        }
        if sa == 0 {
            return Ordering::Equal;
        }
        let c = self.cmp_abs(other);
        if sa < 0 {
            c.reverse()
        } else {
            c
        }
    }

    pub fn is_integer(&self) -> bool {
        self.is_zero() || self.exp >= 0
    }

    /// self is a multiple of other (other != 0)
    pub fn is_multiple_of(&self, other: &Dec) -> bool {
        if self.is_zero() {
            return true;
        }
        if other.is_zero() {
            return false;
        }
        // self = A * 10^p, other = B * 10^q ; need A*10^p / (B*10^q) integer
        let r = self.exp.min(other.exp);
        let pa = self.exp - r;
        let pb = other.exp - r;
        // guard against absurd sizes
        if pa > 100_000 || pb > 100_000 {
            // fall back to f64-ish reasoning
            if pb > pa {
                return false;
            }
        }
        let mut a = BigUint::from_digits(&self.digits);
        for _ in 0..pa {
            a.mul_small(10);
        }
        let mut b = BigUint::from_digits(&other.digits);
        for _ in 0..pb {
            b.mul_small(10);
        }
        a.rem(&b).is_zero()
    }
}

/// Minimal big unsigned integer, base 1e9 little endian.
#[derive(Clone, Debug)]
pub struct BigUint {
    limbs: Vec<u32>, // base 1_000_000_000 little-endian
}

const BASE: u64 = 1_000_000_000;

impl BigUint {
    pub fn from_u64(mut v: u64) -> BigUint {
        let mut limbs = vec![];
        while v > 0 {
            limbs.push((v % BASE) as u32);
            v /= BASE;
        }
        BigUint { limbs }
    }
    pub fn from_digits(d: &[u8]) -> BigUint {
        let mut limbs = vec![];
        let mut end = d.len();
        while end > 0 {
            let start = end.saturating_sub(9);
            let mut v: u32 = 0;
            for &x in &d[start..end] {
                v = v * 10 + x as u32;
            }
            limbs.push(v);
            end = start;
        }
        let mut b = BigUint { limbs };
        b.trim();
        b
    }
    fn trim(&mut self) {
        while let Some(&0) = self.limbs.last() {
            self.limbs.pop();
        }
    }
    pub fn is_zero(&self) -> bool {
        self.limbs.is_empty()
    }
    pub fn mul_small(&mut self, m: u32) {
        let mut carry: u64 = 0;
        for l in self.limbs.iter_mut() {
            let v = *l as u64 * m as u64 + carry;
            *l = (v % BASE) as u32;
            carry = v / BASE;
        }
        while carry > 0 {
            self.limbs.push((carry % BASE) as u32);
            carry /= BASE;
        }
    }
    pub fn to_dec_string(&self) -> String {
        if self.limbs.is_empty() {
            return "0".to_string();
        }
        let mut s = format!("{}", self.limbs[self.limbs.len() - 1]);
        for l in self.limbs.iter().rev().skip(1) {
            s.push_str(&format!("{:09}", l));
        }
        s
    }
    fn cmp(&self, o: &BigUint) -> Ordering {
        if self.limbs.len() != o.limbs.len() {
            return self.limbs.len().cmp(&o.limbs.len());
        }
        for i in (0..self.limbs.len()).rev() {
            if self.limbs[i] != o.limbs[i] {
                return self.limbs[i].cmp(&o.limbs[i]);
            }
        }
        Ordering::Equal
    }
    fn sub_assign(&mut self, o: &BigUint) {
        let mut borrow: i64 = 0;
        for i in 0..self.limbs.len() {
            let mut v = self.limbs[i] as i64 - borrow - *o.limbs.get(i).unwrap_or(&0) as i64;
            if v < 0 {
                v += BASE as i64;
                borrow = 1;
            } else {
                borrow = 0;
            }
            self.limbs[i] = v as u32;
        }
        self.trim();
    }
    fn shift_limbs(&self, n: usize) -> BigUint {
        let mut limbs = vec![0u32; n];
        limbs.extend_from_slice(&self.limbs);
        let mut b = BigUint { limbs };
        b.trim();
        b
    }
    /// remainder self % m
    pub fn rem(&self, m: &BigUint) -> BigUint {
        if m.is_zero() {
            return BigUint { limbs: vec![] };
        }
        let mut r = self.clone();
        if r.cmp(m) == Ordering::Less {
            return r;
        }
        // schoolbook: subtract shifted multiples
        let diff = r.limbs.len() - m.limbs.len();
        for shift in (0..=diff).rev() {
            let ms = m.shift_limbs(shift);
            if r.cmp(&ms) == Ordering::Less {
                continue;
            }
            // binary search the quotient digit q in [0, BASE)
            let (mut lo, mut hi) = (0u64, BASE - 1);
            while lo < hi {
                let mid = (lo + hi + 1) / 2;
                let mut t = ms.clone();
                t.mul_small(mid as u32);
                if t.cmp(&r) != Ordering::Greater {
                    lo = mid;
                } else {
                    hi = mid - 1;
                }
            }
            if lo > 0 {
                let mut t = ms.clone();
                t.mul_small(lo as u32);
                r.sub_assign(&t);
            }
        }
        r
    }
}

/// Classification of a JSON number by its textual representation.
pub fn num_str(n: &Number) -> String {
    n.to_string()
}

pub fn dec_of(n: &Number) -> Dec {
    Dec::parse(&n.to_string()).unwrap_or_else(Dec::zero)
}

pub fn f64_of(n: &Number) -> f64 {
    n.to_string().parse::<f64>().unwrap_or(0.0)
}

/// Is the literal an integer literal (no fraction / exponent)?
pub fn is_int_literal(s: &str) -> bool {
    !s.contains('.') && !s.contains('e') && !s.contains('E')
}

pub fn fits_i64_or_u64(s: &str) -> bool {
    s.parse::<u64>().is_ok() || s.parse::<i64>().is_ok()
}

/// Compare instance with limit, following the observed semantics.
pub fn cmp_instance_limit(inst: &Number, limit: &Number) -> Ordering {
    let is = inst.to_string();
    let ls = limit.to_string();
    let id = Dec::parse(&is).unwrap_or_else(Dec::zero);
    let ld = Dec::parse(&ls).unwrap_or_else(Dec::zero);
    if ld.is_integer() {
        if id.is_integer() {
            id.cmp(&ld)
        } else {
            let f = is.parse::<f64>().unwrap_or(0.0);
            Dec::from_f64(f).cmp(&ld)
        }
    } else {
        if is_int_literal(&is) && !fits_i64_or_u64(&is) {
            let f = is.parse::<f64>().unwrap_or(0.0);
            Dec::from_f64(f).cmp(&ld)
        } else {
            id.cmp(&ld)
        }
    }
}

pub fn num_eq(a: &Number, b: &Number) -> bool {
    let da = dec_of(a);
    let db = dec_of(b);
    da.cmp(&db) == Ordering::Equal
}

#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn t() {
        let a = Dec::parse("19.99").unwrap();
        let b = Dec::parse("0.01").unwrap();
        assert!(a.is_multiple_of(&b));
        let a = Dec::parse("1e400").unwrap();
        let b = Dec::parse("3").unwrap();
        assert!(!a.is_multiple_of(&b));
        let b = Dec::parse("2").unwrap();
        assert!(a.is_multiple_of(&b));
        assert_eq!(Dec::from_f64(0.5), Dec::parse("0.5").unwrap());
    }
}
EOF
echo ok"}

