//! RFC 3986 URI reference parsing, resolution and normalization.

#[derive(Clone, Debug, PartialEq, Eq, Default)]
pub struct Uri {
    pub scheme: Option<String>,
    pub authority: Option<String>,
    pub path: String,
    pub query: Option<String>,
    pub fragment: Option<String>,
}

fn is_unreserved(c: u8) -> bool {
    c.is_ascii_alphanumeric() || c == b'-' || c == b'.' || c == b'_' || c == b'~'
}
fn is_sub_delim(c: u8) -> bool {
    matches!(c, b'!' | b'$' | b'&' | b'\'' | b'(' | b')' | b'*' | b'+' | b',' | b';' | b'=')
}
fn is_pchar(c: u8) -> bool {
    is_unreserved(c) || is_sub_delim(c) || c == b':' || c == b'@'
}

#[derive(Debug)]
pub enum UriError {
    Unexpected(usize),
    Percent(usize),
}

impl UriError {
    pub fn message(&self) -> String {
        match self {
            UriError::Unexpected(i) => format!("unexpected character at index {}", i),
            UriError::Percent(i) => format!("invalid percent-encoded octet at index {}", i),
        }
    }
}

struct P<'a> {
    b: &'a [u8],
    i: usize,
}

impl<'a> P<'a> {
    fn peek(&self) -> Option<u8> {
        self.b.get(self.i).copied()
    }
    /// scan characters of a class (with pct-encoding allowed); stops at first char not in class
    fn scan(&mut self, class: &dyn Fn(u8) -> bool) -> Result<(), UriError> {
        while let Some(c) = self.peek() {
            if c == b'%' {
                let h1 = self.b.get(self.i + 1).copied();
                let h2 = self.b.get(self.i + 2).copied();
                match (h1, h2) {
                    (Some(a), Some(b)) if a.is_ascii_hexdigit() && b.is_ascii_hexdigit() => {
                        self.i += 3;
                    }
                    _ => return Err(UriError::Percent(self.i)),
                }
            } else if class(c) {
                self.i += 1;
            } else {
                break;
            }
        }
        Ok(())
    }
}

fn parse_ipv6(b: &[u8], start: usize, end: usize) -> Result<(), usize> {
    // b[start..end] is the content between [ and ]
    let s = &b[start..end];
    // count groups
    let mut i = 0;
    let mut groups = 0;
    let mut double = false;
    if s.len() >= 2 && s[0] == b':' && s[1] == b':' {
        double = true;
        i = 2;
        if i == s.len() {
            return Ok(());
        }
    } else if !s.is_empty() && s[0] == b':' {
        return Err(start + 1);
    }
    loop {
        // parse a group or ipv4
        let gs = i;
        while i < s.len() && s[i].is_ascii_hexdigit() {
            i += 1;
        }
        if i < s.len() && s[i] == b'.' {
            // ipv4 tail
            let mut j = gs;
            let mut parts = 0;
            loop {
                let ps = j;
                while j < s.len() && s[j].is_ascii_digit() {
                    j += 1;
                }
                if j == ps || j - ps > 3 {
                    return Err(start + j);
                }
                let v: u32 = std::str::from_utf8(&s[ps..j]).unwrap().parse().unwrap();
                if v > 255 || (j - ps > 1 && s[ps] == b'0') {
                    return Err(start + ps);
                }
                parts += 1;
                if parts == 4 {
                    break;
                }
                if j < s.len() && s[j] == b'.' {
                    j += 1;
                } else {
                    return Err(start + j);
                }
            }
            if j != s.len() {
                return Err(start + j);
            }
            groups += 2;
            if groups > 8 || (!double && groups != 8) || (double && groups > 7) {
                return Err(start + j);
            }
            return Ok(());
        }
        let glen = i - gs;
        if glen == 0 || glen > 4 {
            return Err(start + i);
        }
        groups += 1;
        if i == s.len() {
            break;
        }
        if s[i] != b':' {
            return Err(start + i);
        }
        if groups == 8 {
            return Err(start + i);
        }
        i += 1;
        if i < s.len() && s[i] == b':' {
            if double {
                return Err(start + i);
            }
            double = true;
            i += 1;
            if i == s.len() {
                break;
            }
        } else if i == s.len() {
            return Err(start + i);
        }
    }
    if double {
        if groups > 7 {
            return Err(start + s.len());
        }
    } else if groups != 8 {
        return Err(start + s.len());
    }
    Ok(())
}

pub fn parse(s: &str) -> Result<Uri, UriError> {
    let b = s.as_bytes();
    let mut p = P { b, i: 0 };
    let mut uri = Uri::default();
    // scheme
    if !b.is_empty() && b[0].is_ascii_alphabetic() {
        let mut j = 1;
        while j < b.len() && (b[j].is_ascii_alphanumeric() || b[j] == b'+' || b[j] == b'-' || b[j] == b'.') {
            j += 1;
        }
        if j < b.len() && b[j] == b':' {
            uri.scheme = Some(s[..j].to_string());
            p.i = j + 1;
        }
    }
    let has_scheme = uri.scheme.is_some();
    // authority
    if p.b[p.i..].starts_with(b"//") {
        p.i += 2;
        let astart = p.i;
        // userinfo?
        let mut j = p.i;
        let mut has_at = false;
        while j < b.len() && !matches!(b[j], b'/' | b'?' | b'#') {
            if b[j] == b'@' {
                has_at = true;
                break;
            }
            j += 1;
        }
        if has_at {
            p.scan(&|c| is_unreserved(c) || is_sub_delim(c) || c == b':')?;
            if p.peek() != Some(b'@') {
                return Err(UriError::Unexpected(p.i));
            }
            p.i += 1;
        }
        // host
        if p.peek() == Some(b'[') {
            let hs = p.i + 1;
            let mut k = hs;
            while k < b.len() && b[k] != b']' {
                k += 1;
            }
            let content_end = k;
            if hs < b.len() && (b[hs] == b'v' || b[hs] == b'V') {
                // IPvFuture
                let mut q = hs + 1;
                let hstart = q;
                while q < content_end && b[q].is_ascii_hexdigit() {
                    q += 1;
                }
                if q == hstart || q >= content_end || b[q] != b'.' {
                    return Err(UriError::Unexpected(q));
                }
                q += 1;
                let rs = q;
                while q < content_end && (is_unreserved(b[q]) || is_sub_delim(b[q]) || b[q] == b':') {
                    q += 1;
                }
                if q == rs || q != content_end {
                    return Err(UriError::Unexpected(q));
                }
            } else {
                // validate chars first
                let mut q = hs;
                while q < content_end && (b[q].is_ascii_hexdigit() || b[q] == b':' || b[q] == b'.') {
                    q += 1;
