                if q != content_end {
                    return Err(UriError::Unexpected(q));
                }
                if let Err(e) = parse_ipv6(b, hs, content_end) {
                    return Err(UriError::Unexpected(e));
                }
            }
            if content_end >= b.len() {
                return Err(UriError::Unexpected(b.len()));
            }
            p.i = content_end + 1;
        } else {
            p.scan(&|c| is_unreserved(c) || is_sub_delim(c))?;
        }
        if p.peek() == Some(b':') {
            p.i += 1;
            while let Some(c) = p.peek() {
                if c.is_ascii_digit() {
                    p.i += 1;
                } else {
                    break;
                }
            }
        }
        match p.peek() {
            None | Some(b'/') | Some(b'?') | Some(b'#') => {}
            Some(_) => return Err(UriError::Unexpected(p.i)),
        }
        uri.authority = Some(s[astart..p.i].to_string());
        // path-abempty
        let ps = p.i;
        p.scan(&|c| is_pchar(c) || c == b'/')?;
        uri.path = s[ps..p.i].to_string();
    } else {
        let ps = p.i;
        p.scan(&|c| is_pchar(c) || c == b'/')?;
        let path = &s[ps..p.i];
        if !has_scheme {
            // first segment must not contain ':'
            let first = path.split('/').next().unwrap_or("");
            if !path.starts_with('/') && first.contains(':') {
                return Err(UriError::Unexpected(0));
            }
        }
        uri.path = path.to_string();
    }
    if p.peek() == Some(b'?') {
        p.i += 1;
        let qs = p.i;
        p.scan(&|c| is_pchar(c) || c == b'/' || c == b'?')?;
        uri.query = Some(s[qs..p.i].to_string());
    }
    if p.peek() == Some(b'#') {
        p.i += 1;
        let fs = p.i;
        p.scan(&|c| is_pchar(c) || c == b'/' || c == b'?')?;
        uri.fragment = Some(s[fs..p.i].to_string());
    }
    if p.i != b.len() {
        return Err(UriError::Unexpected(p.i));
    }
    Ok(uri)
}

pub fn remove_dot_segments(input: &str) -> String {
    let mut input = input.to_string();
    let mut output = String::new();
    while !input.is_empty() {
        if input.starts_with("../") {
            input = input[3..].to_string();
        } else if input.starts_with("./") {
            input = input[2..].to_string();
        } else if input.starts_with("/./") {
            input = input[2..].to_string();
        } else if input == "/." {
            input = "/".to_string();
        } else if input.starts_with("/../") {
            input = input[3..].to_string();
            if let Some(pos) = output.rfind('/') {
                output.truncate(pos);
            } else {
                output.clear();
            }
        } else if input == "/.." {
            input = "/".to_string();
            if let Some(pos) = output.rfind('/') {
                output.truncate(pos);
            } else {
                output.clear();
            }
        } else if input == "." || input == ".." {
            input.clear();
        } else {
            let start = if input.starts_with('/') { 1 } else { 0 };
            let end = input[start..].find('/').map(|p| p + start).unwrap_or(input.len());
            output.push_str(&input[..end]);
            input = input[end..].to_string();
        }
    }
    output
}

fn merge(base: &Uri, rpath: &str) -> String {
    if base.authority.is_some() && base.path.is_empty() {
        format!("/{}", rpath)
    } else {
        match base.path.rfind('/') {
            Some(p) => format!("{}{}", &base.path[..=p], rpath),
            None => rpath.to_string(),
        }
    }
}

pub fn resolve(base: &Uri, r: &Uri) -> Uri {
    let mut t = Uri::default();
    if r.scheme.is_some() {
        t.scheme = r.scheme.clone();
