/// Percent-encode a filesystem path for a file:// URL (like url::Url::from_file_path)
pub fn file_path_to_uri(path: &str) -> String {
    let mut s = String::from("file://");
    for seg in path.split('/').skip(1) {
        s.push('/');
        for &c in seg.as_bytes() {
            let enc = c <= 0x20
                || c >= 0x7f
                || matches!(c, b'"' | b'#' | b'<' | b'>' | b'?' | b'`' | b'{' | b'}' | b'%' | b'/' );
            if enc {
                s.push_str(&format!("%{:02X}", c));
            } else {
                s.push(c as char);
            }
        }
    }
    if path == "/" {
        s = "file:///".to_string();
    }
    s
}
