            s.push(':');
        }
        if let Some(a) = &self.authority {
            s.push_str("//");
            s.push_str(a);
        }
        s.push_str(&self.path);
        if let Some(q) = &self.query {
            s.push('?');
            s.push_str(q);
        }
        s
    }
    pub fn to_string_full(&self) -> String {
        let mut s = self.to_string_no_fragment();
        if let Some(f) = &self.fragment {
            s.push('#');
            s.push_str(f);
        }
        s
    }
    pub fn without_fragment(&self) -> Uri {
        let mut u = self.clone();
        u.fragment = None;
        u
    }
}

/// Percent-encode a filesystem path for a file:// URL (like url::Url::from_file_path)
pub fn file_path_to_uri(path: &str) -> String {
    let mut s = String::from("file://");
    for seg in path.split('/').skip(1) {
        s.push('/');
        for &c in seg.as_bytes() {
            let enc = c <= 0x20
                || c >= 0x7f
                || matches!(c, b'"' | b'#' | b'<' | b'>' | b'?' | b'`' | b'{' | b'}' | b'%' | b'/' );
            if enc {
                s.push_str(&format!("%{:02X}", c));
            } else {
                s.push(c as char);
            }
        }
    }
    if path == "/" {
        s = "file:///".to_string();
    }
    s
}
