//! Resource registry: documents, $id resources, anchors, retrieval.
use crate::uri::{self, Uri};
use serde_json::Value;
use std::collections::HashMap;
use std::rc::Rc;

#[derive(Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Debug, Hash)]
pub enum Draft {
    D4,
    D6,
    D7,
    D2019,
    D2020,
}

#[derive(Clone, Debug)]
pub enum Seg {
    Key(String),
    Idx(usize),
}

#[derive(Clone, Debug)]
pub struct Loc {
    pub doc: usize,
    pub path: Vec<Seg>,
    pub draft: Draft,
}

pub struct Registry {
    pub docs: Vec<Rc<Value>>,
    pub resources: HashMap<String, Loc>,
    pub anchors: HashMap<(String, String), (Loc, bool)>,
}

pub fn draft_from_schema_uri(s: &str) -> Option<Draft> {
    let t = s.trim_end_matches('#');
    match t {
        "http://json-schema.org/draft-04/schema" | "https://json-schema.org/draft-04/schema" => Some(Draft::D4),
        "http://json-schema.org/draft-06/schema" | "https://json-schema.org/draft-06/schema" => Some(Draft::D6),
        "http://json-schema.org/draft-07/schema" | "https://json-schema.org/draft-07/schema" => Some(Draft::D7),
        "https://json-schema.org/draft/2019-09/schema" | "http://json-schema.org/draft/2019-09/schema" => Some(Draft::D2019),
        "https://json-schema.org/draft/2020-12/schema" | "http://json-schema.org/draft/2020-12/schema" => Some(Draft::D2020),
        _ => None,
    }
}

pub fn value_at<'a>(v: &'a Value, path: &[Seg]) -> Option<&'a Value> {
    let mut cur = v;
    for s in path {
        cur = match (s, cur) {
            (Seg::Key(k), Value::Object(m)) => m.get(k)?,
            (Seg::Idx(i), Value::Array(a)) => a.get(*i)?,
            _ => return None,
        };
    }
    Some(cur)
}

pub fn parse_uri_ref(s: &str) -> Result<Uri, String> {
    uri::parse(s).map_err(|e| format!("Invalid URI reference '{}': {}", s, e.message()))
}

pub fn resolve_str(base: &Uri, r: &str) -> Result<Uri, String> {
    let rr = parse_uri_ref(r)?;
    let mut t = uri::resolve(base, &rr);
    let frag = t.fragment.take();
    uri::normalize(&mut t);
    t.fragment = frag;
    Ok(t)
}

pub fn is_metaschema_like(s: &str) -> bool {
    s.starts_with("https://json-schema.org/draft/") || s.starts_with("http://json-schema.org/draft-")
}

/// subschema-bearing keywords for crawling
pub fn subschemas<'a>(obj: &'a serde_json::Map<String, Value>, draft: Draft) -> Vec<(Vec<Seg>, &'a Value)> {
    let mut out: Vec<(Vec<Seg>, &'a Value)> = Vec::new();
    for (k, v) in obj.iter() {
        let k = k.as_str();
        let single = match k {
            "additionalProperties" | "not" => true,
            "additionalItems" => true,
            "contains" | "propertyNames" => draft >= Draft::D6,
            "if" | "then" | "else" => draft >= Draft::D7,
            "unevaluatedItems" | "unevaluatedProperties" | "contentSchema" => draft >= Draft::D2019,
            "items" => v.is_object() || v.is_boolean(),
            _ => false,
        };
        if single {
            out.push((vec![Seg::Key(k.to_string())], v));
            continue;
        }
        let arr = match k {
            "allOf" | "anyOf" | "oneOf" => true,
            "items" => v.is_array() && draft <= Draft::D2019,
            "prefixItems" => draft >= Draft::D2020,
            _ => false,
        };
        if arr {
            if let Value::Array(a) = v {
                for (i, x) in a.iter().enumerate() {
                    out.push((vec![Seg::Key(k.to_string()), Seg::Idx(i)], x));
                }
            }
            continue;
        }
        let map = match k {
            "properties" | "patternProperties" | "definitions" => true,
            "$defs" | "dependentSchemas" => draft >= Draft::D2019,
            "dependencies" => true,
            _ => false,
        };
        if map {
            if let Value::Object(m) = v {
                for (kk, x) in m.iter() {
                    if k == "dependencies" && !(x.is_object() || x.is_boolean()) {
                        continue;
                    }
                    out.push((vec![Seg::Key(k.to_string()), Seg::Key(kk.clone())], x));
                }
            }
        }
    }
    out
}

pub type Retriever = dyn Fn(&str) -> Result<Value, String>;

impl Registry {
    pub fn new() -> Registry {
        Registry { docs: vec![], resources: HashMap::new(), anchors: HashMap::new() }
    }

    pub fn add_document(&mut self, uri: &str, value: Value, draft: Draft, refs: &mut Vec<(String, Uri, bool)>) -> Result<usize, String> {
        let idx = self.docs.len();
        self.docs.push(Rc::new(value));
        let doc = self.docs[idx].clone();
        let base = uri::parse(uri).map_err(|e| format!("Invalid URI reference '{}': {}", uri, e.message()))?;
        let mut base_nf = base.without_fragment();
        uri::normalize(&mut base_nf);
        self.resources.insert(base_nf.to_string_no_fragment(), Loc { doc: idx, path: vec![], draft });
        let mut path = vec![];
        self.crawl(idx, &mut path, &doc, &base_nf, draft, refs, true)?;
        Ok(idx)
    }

    fn crawl(&mut self, doc: usize, path: &mut Vec<Seg>, v: &Value, base: &Uri, draft: Draft, refs: &mut Vec<(String, Uri, bool)>, is_root: bool) -> Result<(), String> {
        let obj = match v {
            Value::Object(o) => o,
            _ => return Ok(()),
        };
        let mut base = base.clone();
        let mut draft = draft;
        let has_ref = obj.contains_key("$ref");
        let id_key = if draft == Draft::D4 { "id" } else { "$id" };
        if let Some(Value::String(id)) = obj.get(id_key) {
            if !(draft <= Draft::D7 && has_ref) {
                if let Some(Value::String(s)) = obj.get("$schema") {
                    if let Some(d) = draft_from_schema_uri(s) {
                        draft = d;
                    }
                }
                let resolved = resolve_str(&base, id)?;
                let frag = resolved.fragment.clone().unwrap_or_default();
                if draft <= Draft::D7 && id.starts_with('#') {
                    if !frag.is_empty() {
                        self.anchors.insert((base.to_string_no_fragment(), frag), (Loc { doc, path: path.clone(), draft }, false));
                    }
                } else {
                    let nb = resolved.without_fragment();
                    if !is_root || true {
                        self.resources.insert(nb.to_string_no_fragment(), Loc { doc, path: path.clone(), draft });
                    }
                    base = nb;
                    if draft <= Draft::D7 && !frag.is_empty() {
                        self.anchors.insert((base.to_string_no_fragment(), frag), (Loc { doc, path: path.clone(), draft }, false));
                    }
                }
            }
        }
        if draft >= Draft::D2019 {
            if let Some(Value::String(a)) = obj.get("$anchor") {
                self.anchors.insert((base.to_string_no_fragment(), a.clone()), (Loc { doc, path: path.clone(), draft }, false));
            }
        }
        if draft == Draft::D2020 {
            if let Some(Value::String(a)) = obj.get("$dynamicAnchor") {
                self.anchors.insert((base.to_string_no_fragment(), a.clone()), (Loc { doc, path: path.clone(), draft }, true));
            }
        }
        let base_str = base.to_string_no_fragment();
        let base_skip = is_metaschema_like(&base_str);
        let mut ref_keys = vec!["$ref"];
        if draft == Draft::D2020 {
            ref_keys.push("$dynamicRef");
        }
        if draft == Draft::D2019 {
            ref_keys.push("$recursiveRef");
        }
        for rk in ref_keys {
            if let Some(Value::String(r)) = obj.get(rk) {
                let skip = base_skip || is_metaschema_like(r);
                refs.push((r.clone(), base.clone(), skip));
            }
        }
        if draft <= Draft::D7 && has_ref {
            return Ok(());
        }
        for (segs, sub) in subschemas(obj, draft) {
            let n = segs.len();
            path.extend(segs);
            self.crawl(doc, path, sub, &base, draft, refs, false)?;
            for _ in 0..n {
                path.pop();
            }
        }
        Ok(())
    }

    /// Process pending references: retrieve missing external documents.
    pub fn process_refs(&mut self, mut refs: Vec<(String, Uri, bool)>, retrieve: &Retriever, default_draft: Draft) -> Result<(), String> {
        let mut i = 0;
        while i < refs.len() {
            let (r, base, skip) = refs[i].clone();
            i += 1;
            let resolved = resolve_str(&base, &r)?;
            if skip {
                continue;
            }
            let key = resolved.to_string_no_fragment();
            if self.resources.contains_key(&key) {
                continue;
            }
            match retrieve(&key) {
                Ok(v) => {
                    let draft = match &v {
                        Value::Object(o) => match o.get("$schema") {
                            Some(Value::String(s)) => draft_from_schema_uri(s).unwrap_or(default_draft),
                            _ => default_draft,
                        },
                        _ => default_draft,
                    };
                    let mut more = vec![];
                    self.add_document(&key, v, draft, &mut more)?;
                    refs.extend(more);
                }
                Err(e) => {
                    return Err(format!("Resource '{}' is not present in a registry and retrieving it failed: {}", key, e));
                }
            }
        }
        Ok(())
    }

    pub fn get(&self, loc: &Loc) -> Option<&Value> {
        value_at(&self.docs[loc.doc], &loc.path)
    }
}
