//! Schema compilation and validation engine.
use crate::ecma;
use crate::formats;
use crate::num;
use crate::registry::{self, value_at, Draft, Loc, Registry, Seg};
use crate::uri::{self, Uri};
use serde_json::{Map, Number, Value};
use std::cell::OnceCell;
use std::cmp::Ordering;
use std::rc::Rc;

// ---------------------------------------------------------------- output unit

#[derive(Debug, Clone)]
pub struct Unit {
    pub eval_path: String,
    pub schema_loc: String,
    pub inst_loc: String,
    pub valid: bool,
    pub annotations: Option<Value>,
    pub errors: Vec<(String, String)>,
    pub children: Vec<Unit>,
}

impl Unit {
    pub fn new(eval_path: String, schema_loc: String, inst_loc: &str) -> Unit {
        Unit { eval_path, schema_loc, inst_loc: inst_loc.to_string(), valid: true, annotations: None, errors: vec![], children: vec![] }
    }
    pub fn err(mut self, kind: &str, msg: String) -> Unit {
        self.valid = false;
        self.errors.push((kind.to_string(), msg));
        self
    }
}

// ---------------------------------------------------------------- helpers

pub fn jstr(v: &Value) -> String {
    serde_json::to_string(v).unwrap_or_default()
}

pub fn ptr_escape(s: &str) -> String {
    s.replace('~', "~0").replace('/', "~1")
}

pub fn child_path(p: &str, seg: &str) -> String {
    let mut s = String::with_capacity(p.len() + seg.len() + 1);
    s.push_str(p);
    s.push('/');
    s.push_str(&ptr_escape(seg));
    s
}

pub fn child_idx(p: &str, i: usize) -> String {
    format!("{}/{}", p, i)
}

pub fn values_equal(a: &Value, b: &Value) -> bool {
    match (a, b) {
        (Value::Number(x), Value::Number(y)) => num::num_eq(x, y),
        (Value::Array(x), Value::Array(y)) => x.len() == y.len() && x.iter().zip(y.iter()).all(|(p, q)| values_equal(p, q)),
        (Value::Object(x), Value::Object(y)) => {
            x.len() == y.len() && x.iter().all(|(k, v)| y.get(k).map(|w| values_equal(v, w)).unwrap_or(false))
        }
        _ => a == b,
    }
}

fn plural(n: u64, one: &str, many: &str) -> String {
    if n == 1 {
        one.to_string()
    } else {
        many.to_string()
    }
}

// ---------------------------------------------------------------- types

pub const T_ARRAY: u8 = 1;
pub const T_BOOLEAN: u8 = 2;
pub const T_INTEGER: u8 = 4;
pub const T_NULL: u8 = 8;
pub const T_NUMBER: u8 = 16;
pub const T_OBJECT: u8 = 32;
pub const T_STRING: u8 = 64;
const TYPE_NAMES: [(u8, &str); 7] = [
    (T_ARRAY, "array"),
    (T_BOOLEAN, "boolean"),
    (T_INTEGER, "integer"),
    (T_NULL, "null"),
    (T_NUMBER, "number"),
    (T_OBJECT, "object"),
    (T_STRING, "string"),
];

fn type_bit(s: &str) -> Option<u8> {
    TYPE_NAMES.iter().find(|(_, n)| *n == s).map(|(b, _)| *b)
}

pub fn is_integer(n: &Number, draft: Draft) -> bool {
    let s = n.to_string();
    if draft == Draft::D4 && s.contains('.') {
        return false;
    }
    num::Dec::parse(&s).map(|d| d.is_integer()).unwrap_or(false)
}

fn matches_type(v: &Value, t: u8, draft: Draft) -> bool {
    match v {
        Value::Array(_) => t & T_ARRAY != 0,
        Value::Bool(_) => t & T_BOOLEAN != 0,
        Value::Null => t & T_NULL != 0,
        Value::Object(_) => t & T_OBJECT != 0,
        Value::String(_) => t & T_STRING != 0,
        Value::Number(n) => t & T_NUMBER != 0 || (t & T_INTEGER != 0 && is_integer(n, draft)),
    }
}

