    pub eager: Option<Rc<Node>>,
    pub lazy: Option<Rc<LazyRef>>,
}

pub struct LazyRef {
    pub key: String,
    pub comp: Rc<Compiler>,
    pub ctx: Ctx,
    pub target: Loc,
    pub cell: OnceCell<Result<Rc<Node>, String>>,
}

impl LazyRef {
    fn get(&self) -> Rc<Node> {
        let r = self.cell.get_or_init(|| {
            let v = self.comp.reg.get(&self.target).cloned().unwrap_or(Value::Bool(true));
            let mut ctx = self.ctx.clone();
            ctx.ref_stack = Rc::new(vec![self.key.clone()]);
            self.comp.compile_node(&v, &ctx)
        });
        match r {
            Ok(n) => n.clone(),
            Err(_) => Rc::new(Node { kind: NodeKind::True, loc: String::new(), annotations: None }),
        }
    }
}

impl RefTarget {
    fn node(&self) -> Rc<Node> {
        if let Some(n) = &self.eager {
            n.clone()
        } else {
            self.lazy.as_ref().unwrap().get()
        }
    }
}

