// ---------------------------------------------------------------- output unit

#[derive(Debug, Clone)]
pub struct Unit {
    pub eval_path: String,
    pub schema_loc: String,
    pub inst_loc: String,
    pub valid: bool,
    pub annotations: Option<Value>,
    pub errors: Vec<(String, String)>,
    pub children: Vec<Unit>,
}

impl Unit {
    pub fn new(eval_path: String, schema_loc: String, inst_loc: &str) -> Unit {
        Unit { eval_path, schema_loc, inst_loc: inst_loc.to_string(), valid: true, annotations: None, errors: vec![], children: vec![] }
    }
    pub fn err(mut self, kind: &str, msg: String) -> Unit {
        self.valid = false;
        self.errors.push((kind.to_string(), msg));
        self
    }
}

// ---------------------------------------------------------------- helpers

pub fn jstr(v: &Value) -> String {
    serde_json::to_string(v).unwrap_or_default()
}

pub fn ptr_escape(s: &str) -> String {
    s.replace('~', "~0").replace('/', "~1")
}

pub fn child_path(p: &str, seg: &str) -> String {
    let mut s = String::with_capacity(p.len() + seg.len() + 1);
    s.push_str(p);
    s.push('/');
    s.push_str(&ptr_escape(seg));
    s
}

pub fn child_idx(p: &str, i: usize) -> String {
    format!("{}/{}", p, i)
}

pub fn values_equal(a: &Value, b: &Value) -> bool {
    match (a, b) {
        (Value::Number(x), Value::Number(y)) => num::num_eq(x, y),
        (Value::Array(x), Value::Array(y)) => x.len() == y.len() && x.iter().zip(y.iter()).all(|(p, q)| values_equal(p, q)),
        (Value::Object(x), Value::Object(y)) => {
            x.len() == y.len() && x.iter().all(|(k, v)| y.get(k).map(|w| values_equal(v, w)).unwrap_or(false))
        }
        _ => a == b,
    }
}

fn plural(n: u64, one: &str, many: &str) -> String {
    if n == 1 {
        one.to_string()
    } else {
        many.to_string()
    }
}

// ---------------------------------------------------------------- types

pub const T_ARRAY: u8 = 1;
pub const T_BOOLEAN: u8 = 2;
pub const T_INTEGER: u8 = 4;
pub const T_NULL: u8 = 8;
pub const T_NUMBER: u8 = 16;
pub const T_OBJECT: u8 = 32;
pub const T_STRING: u8 = 64;
const TYPE_NAMES: [(u8, &str); 7] = [
    (T_ARRAY, "array"),
    (T_BOOLEAN, "boolean"),
    (T_INTEGER, "integer"),
    (T_NULL, "null"),
    (T_NUMBER, "number"),
    (T_OBJECT, "object"),
    (T_STRING, "string"),
];

fn type_bit(s: &str) -> Option<u8> {
    TYPE_NAMES.iter().find(|(_, n)| *n == s).map(|(b, _)| *b)
}

pub fn is_integer(n: &Number, draft: Draft) -> bool {
    let s = n.to_string();
    if draft == Draft::D4 && s.contains('.') {
        return false;
    }
    num::Dec::parse(&s).map(|d| d.is_integer()).unwrap_or(false)
}

fn matches_type(v: &Value, t: u8, draft: Draft) -> bool {
    match v {
        Value::Array(_) => t & T_ARRAY != 0,
        Value::Bool(_) => t & T_BOOLEAN != 0,
        Value::Null => t & T_NULL != 0,
        Value::Object(_) => t & T_OBJECT != 0,
        Value::String(_) => t & T_STRING != 0,
        Value::Number(n) => t & T_NUMBER != 0 || (t & T_INTEGER != 0 && is_integer(n, draft)),
    }
}

// ---------------------------------------------------------------- nodes

pub struct Node {
    pub kind: NodeKind,
    pub loc: String,
    pub annotations: Option<Value>,
}

pub enum NodeKind {
    True,
    False,
    Obj(Vec<Kw>),
}

pub struct Kw {
    pub name: String,
    pub loc: String,
    pub v: V,
}

pub struct Pattern {
    pub re: Rc<fancy_regex::Regex>,
    pub display: String,
}

impl Pattern {
    pub fn is_match(&self, s: &str) -> bool {
        self.re.is_match(s).unwrap_or(false)
    }
}

pub enum V {
    Type { types: u8, raw: Vec<String>, draft: Draft },
    Const(Value),
    Enum(Vec<Value>),
    Bound { limit: Number, kind: BoundKind },
    MultipleOf(Number),
    MinLength(u64),
    MaxLength(u64),
    MinItems(u64),
    MaxItems(u64),
    MinProperties(u64),
    MaxProperties(u64),
    Required(Vec<String>),
    DependentRequired { deps: Vec<(String, Vec<String>)>, loc: String, kwname: String },
    Pattern(Pattern),
    Format { name: String, check: formats::Check },
    ContentMediaType { media: String, encoding: Option<String> },
    ContentEncoding(String),
    UniqueItems,
    Properties { props: Vec<(String, Rc<Node>)>, required: Option<Vec<String>> },
    PatternProperties(Vec<(Pattern, Rc<Node>)>),
    AdditionalProperties { props: Vec<(String, Rc<Node>)>, patterns: Vec<(Pattern, Rc<Node>)>, schema: Rc<Node>, is_false: bool, has_props: bool, has_patterns: bool, props_loc: String, pats_loc: String },
    PropertyNames(Rc<Node>),
    ItemsAll(Rc<Node>, Option<u8>, Draft),
    ItemsArray(Vec<Rc<Node>>),
    ItemsSkip { node: Rc<Node>, skip: usize },
    AdditionalItems { node: Rc<Node>, skip: usize, is_false: bool },
    PrefixItems(Vec<Rc<Node>>),
    Contains { node: Rc<Node>, min: Option<u64>, max: Option<u64> },
    Dependencies { deps: Vec<(String, DepKind)>, loc: String },
    DependentSchemas(Vec<(String, Rc<Node>)>),
    AllOf(Vec<Rc<Node>>),
    AnyOf(Vec<Rc<Node>>),
    OneOf(Vec<Rc<Node>>),
    Not(Rc<Node>, Value),
    If { cond: Rc<Node>, then: Option<Rc<Node>>, els: Option<Rc<Node>> },
    UnevaluatedProperties(Rc<UnevalProps>),
    UnevaluatedItems(Rc<UnevalItems>),
    Ref(RefTarget),
}

pub enum DepKind {
    Required(Vec<String>),
    Schema(Rc<Node>),
}

#[derive(Clone, Copy, PartialEq)]
pub enum BoundKind {
    Min,
    Max,
    ExMin,
    ExMax,
}

pub struct RefTarget {
    pub key: String,
    pub eager: Option<Rc<Node>>,
    pub lazy: Option<Rc<LazyRef>>,
}

pub struct LazyRef {
    pub key: String,
    pub comp: Rc<Compiler>,
    pub ctx: Ctx,
    pub target: Loc,
    pub cell: OnceCell<Result<Rc<Node>, String>>,
}

impl LazyRef {
    fn get(&self) -> Rc<Node> {
        let r = self.cell.get_or_init(|| {
            let v = self.comp.reg.get(&self.target).cloned().unwrap_or(Value::Bool(true));
            let mut ctx = self.ctx.clone();
            ctx.ref_stack = Rc::new(vec![self.key.clone()]);
            self.comp.compile_node(&v, &ctx)
        });
        match r {
            Ok(n) => n.clone(),
            Err(_) => Rc::new(Node { kind: NodeKind::True, loc: String::new(), annotations: None }),
        }
    }
}

impl RefTarget {
    fn node(&self) -> Rc<Node> {
        if let Some(n) = &self.eager {
            n.clone()
        } else {
            self.lazy.as_ref().unwrap().get()
        }
    }
}

// ---------------------------------------------------------------- unevaluated

pub struct UnevalProps {
    pub schema: Rc<Node>,
    pub is_false: bool,
    pub info: Rc<EvalInfo>,
}

pub struct UnevalItems {
    pub schema: Rc<Node>,
    pub is_false: bool,
    pub info: Rc<EvalInfo>,
}

/// Information about which properties / items are evaluated by a schema object.
pub struct EvalInfo {
    pub props: Vec<String>,
    pub patterns: Vec<Pattern>,
    pub additional: bool, // additionalProperties present => all evaluated
    pub uneval_props_present: bool,
    pub prefix_len: usize,
    pub items_all: bool,
    pub contains: Option<Rc<Node>>,
    pub uneval_items_present: bool,
    pub subs_all: Vec<Rc<EvalInfoNode>>,              // allOf / $ref / $dynamicRef etc: always apply if valid
    pub subs_any: Vec<Rc<EvalInfoNode>>,              // anyOf/oneOf: apply those valid
    pub conditional: Option<(Rc<EvalInfoNode>, Option<Rc<EvalInfoNode>>, Option<Rc<EvalInfoNode>>)>,
    pub dependent: Vec<(String, Rc<EvalInfoNode>)>,
