    pub vocab_none: bool,
}

pub struct Compiler {
    pub reg: Rc<Registry>,
    pub opts: Options,
    pub self_rc: OnceCell<std::rc::Weak<Compiler>>,
}

fn loc_str(base: &Uri, ptr: &str) -> String {
    format!("{}#{}", base.to_string_no_fragment(), ptr)
}

fn kw_ptr(ptr: &str, kw: &str) -> String {
    format!("{}/{}", ptr, ptr_escape(kw))
}

const KW_ORDER: &[&str] = &[
    "type",
    "const",
    "enum",
    "minimum",
    "maximum",
    "exclusiveMinimum",
    "exclusiveMaximum",
    "multipleOf",
    "minLength",
    "maxLength",
    "minItems",
    "maxItems",
    "minProperties",
    "maxProperties",
    "required",
    "dependentRequired",
    "pattern",
    "format",
    "contentMediaType",
    "contentEncoding",
    "uniqueItems",
    "properties",
    "additionalProperties",
    "patternProperties",
    "propertyNames",
    "items",
    "additionalItems",
    "prefixItems",
    "contains",
    "dependencies",
    "dependentSchemas",
    "allOf",
    "anyOf",
    "oneOf",
    "not",
    "if",
    "unevaluatedProperties",
    "unevaluatedItems",
    "$ref",
    "$recursiveRef",
    "$dynamicRef",
];

/// Keywords that are recognized for a draft (are not collected as annotations).
pub fn is_known(kw: &str, draft: Draft) -> bool {
    match kw {
        "$schema" | "$ref" | "type" | "enum" | "multipleOf" | "maximum" | "exclusiveMaximum" | "minimum" | "exclusiveMinimum" | "maxLength"
        | "minLength" | "pattern" | "items" | "additionalItems" | "maxItems" | "minItems" | "uniqueItems" | "maxProperties"
        | "minProperties" | "required" | "properties" | "patternProperties" | "additionalProperties" | "dependencies" | "allOf"
        | "anyOf" | "oneOf" | "not" | "format" => true,
        "id" => draft == Draft::D4,
        "$id" | "const" | "contains" | "propertyNames" => draft >= Draft::D6,
        "if" | "then" | "else" => draft >= Draft::D7,
        "contentMediaType" | "contentEncoding" => draft == Draft::D6 || draft == Draft::D7,
        "$anchor" | "$defs" | "dependentRequired" | "dependentSchemas" | "maxContains" | "minContains" | "unevaluatedItems"
        | "unevaluatedProperties" | "prefixItems" | "$recursiveAnchor" | "$recursiveRef" => draft >= Draft::D2019,
        "$dynamicAnchor" | "$dynamicRef" => draft >= Draft::D2020,
        _ => false,
    }
}

fn as_u64(v: &Value) -> Option<u64> {
    match v {
        Value::Number(n) => {
            if let Some(u) = n.as_u64() {
                return Some(u);
            }
            let s = n.to_string();
            let d = num::Dec::parse(&s)?;
            if d.is_integer() && !d.neg {
                s.parse::<f64>().ok().map(|f| f as u64)
            } else {
                None
            }
        }
        _ => None,
    }
}

impl Compiler {
    pub fn rc(&self) -> Rc<Compiler> {
        self.self_rc.get().unwrap().upgrade().unwrap()
    }

    pub fn lookup(&self, base: &Uri, reference: &str) -> Result<(Loc, Uri, String, String), String> {
        // returns (target location, target base, pointer for location, resolved key)
        let resolved = registry::resolve_str(base, reference)?;
        let nf = resolved.to_string_no_fragment();
        let frag = resolved.fragment.clone().unwrap_or_default();
        let key = format!("{}#{}", nf, frag);
        let res = match self.reg.resources.get(&nf) {
            Some(r) => r.clone(),
            None => {
                return Err(format!(
                    "Resource '{}' is not present in a registry and retrieving it failed: Retrieving external resources is not supported once the registry is populated",
                    nf
                ))
            }
        };
        let mut tbase = uri::parse(&nf).unwrap_or_default();
        uri::normalize(&mut tbase);
        if frag.is_empty() {
            return Ok((res, tbase, String::new(), key));
        }
        if frag.starts_with('/') {
            let decoded = uri::percent_decode(&frag);
            let mut loc = res.clone();
            let mut cur = self.reg.get(&res).ok_or_else(|| format!("Pointer '{}' does not exist", frag))?;
            let mut base = tbase.clone();
            let parts: Vec<&str> = decoded[1..].split('/').collect();
            let nparts = parts.len();
            for (i, p) in parts.iter().enumerate() {
                let p = p.replace("~1", "/").replace("~0", "~");
                // apply $id of intermediate schema (not the final target)
                let next = match cur {
                    Value::Object(m) => {
                        let n = m.get(&p).ok_or_else(|| format!("Pointer '{}' does not exist", frag))?;
                        loc.path.push(Seg::Key(p.clone()));
                        n
                    }
                    Value::Array(a) => {
                        let idx: usize = if p.len() > 1 && p.starts_with('0') {
                            return Err(format!("Pointer '{}' does not exist", frag));
                        } else {
                            p.parse().map_err(|_| format!("Pointer '{}' does not exist", frag))?
                        };
                        let n = a.get(idx).ok_or_else(|| format!("Pointer '{}' does not exist", frag))?;
                        loc.path.push(Seg::Idx(idx));
                        n
                    }
                    _ => return Err(format!("Pointer '{}' does not exist", frag)),
                };
                cur = next;
                if i + 1 < nparts {
                    if let Value::Object(m) = cur {
                        let idk = if res.draft == Draft::D4 { "id" } else { "$id" };
                        if let Some(Value::String(id)) = m.get(idk) {
                            if !(res.draft <= Draft::D7 && (m.contains_key("$ref") || id.starts_with('#'))) {
                                if let Ok(nb) = registry::resolve_str(&base, id) {
                                    base = nb.without_fragment();
                                }
                            }
                        }
                    }
                }
            }
            return Ok((loc, base, frag.clone(), key));
        }
        // anchor
        if frag.contains('/') || !anchor_valid(&frag) {
            return Err(format!("Anchor '{}' is invalid", frag));
        }
        match self.reg.anchors.get(&(nf.clone(), frag.clone())) {
            Some((l, _)) => Ok((l.clone(), tbase, String::new(), key)),
            None => Err(format!("Anchor '{}' does not exist", frag)),
        }
    }

    pub fn compile_node(&self, v: &Value, ctx: &Ctx) -> Result<Rc<Node>, String> {
        let loc = loc_str(&ctx.base, &ctx.ptr);
        match v {
            Value::Bool(true) => Ok(Rc::new(Node { kind: NodeKind::True, loc, annotations: None })),
            Value::Bool(false) => Ok(Rc::new(Node { kind: NodeKind::False, loc, annotations: None })),
            Value::Object(obj) => self.compile_object(obj, ctx),
            _ => Ok(Rc::new(Node { kind: NodeKind::True, loc, annotations: None })),
        }
    }

    fn sub(&self, v: &Value, ctx: &Ctx, segs: &[&str]) -> Result<Rc<Node>, String> {
        let mut c = ctx.clone();
        for s in segs {
            c.ptr = kw_ptr(&c.ptr, s);
        }
        self.compile_node(v, &c)
    }

    fn compile_object(&self, obj: &Map<String, Value>, ctx0: &Ctx) -> Result<Rc<Node>, String> {
        let mut ctx = ctx0.clone();
        let draft = ctx.draft;
        let has_ref = obj.contains_key("$ref");
        let legacy_ref = draft <= Draft::D7 && has_ref;
        // base URI change
        let id_key = if draft == Draft::D4 { "id" } else { "$id" };
        if !legacy_ref {
            if let Some(Value::String(id)) = obj.get(id_key) {
                if !(draft <= Draft::D7 && id.starts_with('#')) {
                    if let Ok(nb) = registry::resolve_str(&ctx.base, id) {
                        let nb = nb.without_fragment();
                        if nb != ctx.base {
                            let mut sc = (*ctx.scope).clone();
                            sc.push(nb.to_string_no_fragment());
                            ctx.scope = Rc::new(sc);
                        }
                        ctx.base = nb;
                    }
                }
            }
        }
        let loc = loc_str(&ctx.base, &ctx.ptr);
        if self.opts.vocab_none {
            return Ok(Rc::new(Node { kind: NodeKind::Obj(vec![]), loc, annotations: None }));
        }
        let mut kws: Vec<Kw> = Vec::new();
        let mut annotations = Map::new();
        if legacy_ref {
            for (k, v) in obj.iter() {
                if k != "$ref" {
                    annotations.insert(k.clone(), v.clone());
                }
            }
            if let Some(kw) = self.compile_ref(obj.get("$ref").unwrap(), "$ref", &ctx)? {
                kws.push(kw);
            }
            let ann = if annotations.is_empty() { None } else { Some(Value::Object(annotations)) };
            return Ok(Rc::new(Node { kind: NodeKind::Obj(kws), loc, annotations: ann }));
        }
        for (k, v) in obj.iter() {
            if !is_known(k, draft) {
                annotations.insert(k.clone(), v.clone());
            }
        }
        for &kw in KW_ORDER {
            if !obj.contains_key(kw) || !is_known(kw, draft) {
                continue;
            }
            if let Some(k) = self.compile_keyword(kw, obj, &ctx)? {
                kws.push(k);
            }
        }
        let ann = if annotations.is_empty() { None } else { Some(Value::Object(annotations)) };
        Ok(Rc::new(Node { kind: NodeKind::Obj(kws), loc, annotations: ann }))
    }

    fn mk(&self, ctx: &Ctx, name: &str, v: V) -> Option<Kw> {
        Some(Kw { name: name.to_string(), loc: loc_str(&ctx.base, &kw_ptr(&ctx.ptr, name)), v })
    }

    fn compile_pattern(&self, p: &str) -> Option<Pattern> {
        let t = ecma::translate(p)?;
        let re = fancy_regex::RegexBuilder::new(&t).backtrack_limit(1_000_000).build().ok()?;
        Some(Pattern { re: Rc::new(re), display: t })
    }

    fn compile_keyword(&self, kw: &str, obj: &Map<String, Value>, ctx: &Ctx) -> Result<Option<Kw>, String> {
        let draft = ctx.draft;
        let v = &obj[kw];
        Ok(match kw {
            "type" => {
                let mut types = 0u8;
                let mut raw = vec![];
                match v {
                    Value::String(s) => {
                        types |= type_bit(s).unwrap_or(0);
                        raw.push(s.clone());
                    }
                    Value::Array(a) => {
                        for x in a {
                            if let Value::String(s) = x {
                                types |= type_bit(s).unwrap_or(0);
                                raw.push(s.clone());
                            }
                        }
                    }
                    _ => {}
                }
                self.mk(ctx, kw, V::Type { types, raw, draft })
            }
            "const" => self.mk(ctx, kw, V::Const(v.clone())),
            "enum" => match v {
                Value::Array(a) => self.mk(ctx, kw, V::Enum(a.clone())),
                _ => None,
            },
            "minimum" | "maximum" => {
                let n = match v {
                    Value::Number(n) => n.clone(),
                    _ => return Ok(None),
                };
                let excl = draft == Draft::D4 && obj.get(if kw == "minimum" { "exclusiveMinimum" } else { "exclusiveMaximum" }) == Some(&Value::Bool(true));
                let kind = match (kw, excl) {
                    ("minimum", false) => BoundKind::Min,
                    ("minimum", true) => BoundKind::ExMin,
                    ("maximum", false) => BoundKind::Max,
                    _ => BoundKind::ExMax,
                };
                self.mk(ctx, kw, V::Bound { limit: n, kind })
            }
            "exclusiveMinimum" | "exclusiveMaximum" => {
                if draft == Draft::D4 {
                    return Ok(None);
                }
                let n = match v {
                    Value::Number(n) => n.clone(),
                    _ => return Ok(None),
                };
                let kind = if kw == "exclusiveMinimum" { BoundKind::ExMin } else { BoundKind::ExMax };
                self.mk(ctx, kw, V::Bound { limit: n, kind })
            }
            "multipleOf" => match v {
                Value::Number(n) => self.mk(ctx, kw, V::MultipleOf(n.clone())),
                _ => None,
            },
            "minLength" => as_u64(v).and_then(|n| self.mk(ctx, kw, V::MinLength(n))),
            "maxLength" => as_u64(v).and_then(|n| self.mk(ctx, kw, V::MaxLength(n))),
            "minItems" => as_u64(v).and_then(|n| self.mk(ctx, kw, V::MinItems(n))),
            "maxItems" => as_u64(v).and_then(|n| self.mk(ctx, kw, V::MaxItems(n))),
            "minProperties" => as_u64(v).and_then(|n| self.mk(ctx, kw, V::MinProperties(n))),
            "maxProperties" => as_u64(v).and_then(|n| self.mk(ctx, kw, V::MaxProperties(n))),
            "required" => {
                let names: Vec<String> = match v {
                    Value::Array(a) => a.iter().filter_map(|x| x.as_str().map(|s| s.to_string())).collect(),
                    _ => return Ok(None),
                };
                if names.is_empty() {
                    return Ok(None);
                }
                if names.len() >= 2 && obj.get("properties").map(|p| p.is_object()).unwrap_or(false) && !self.additional_absorbs(obj) {
                    // merged into properties
                    return Ok(None);
                }
                self.mk(ctx, kw, V::Required(names))
            }
            "dependentRequired" => {
                let m = match v {
                    Value::Object(m) => m,
                    _ => return Ok(None),
                };
                let mut deps = vec![];
                for (k, x) in m {
                    if let Value::Array(a) = x {
                        deps.push((k.clone(), a.iter().filter_map(|s| s.as_str().map(|s| s.to_string())).collect()));
                    }
                }
                let loc = loc_str(&ctx.base, &kw_ptr(&ctx.ptr, kw));
                self.mk(ctx, kw, V::DependentRequired { deps, loc, kwname: kw.to_string() })
            }
            "pattern" => {
                let s = match v {
                    Value::String(s) => s,
                    _ => return Ok(None),
                };
                match self.compile_pattern(s) {
                    Some(p) => self.mk(ctx, kw, V::Pattern(p)),
                    None => return Err(format!("{} is not a \"regex\"", jstr(v))),
                }
            }
            "format" => {
                if !self.opts.validate_formats {
                    return Ok(None);
                }
                let s = match v {
                    Value::String(s) => s,
                    _ => return Ok(None),
                };
                match formats::lookup(s, draft) {
                    Some(check) => self.mk(ctx, kw, V::Format { name: s.clone(), check }),
                    None => None,
                }
            }
            "contentMediaType" => {
                let s = match v {
                    Value::String(s) => s,
                    _ => return Ok(None),
                };
                if s != "application/json" {
                    return Ok(None);
                }
                let enc = match obj.get("contentEncoding") {
                    Some(Value::String(e)) if e == "base64" => Some(e.clone()),
                    _ => None,
                };
                self.mk(ctx, kw, V::ContentMediaType { media: s.clone(), encoding: enc })
            }
            "contentEncoding" => {
                let s = match v {
                    Value::String(s) => s,
                    _ => return Ok(None),
                };
                if s != "base64" {
                    return Ok(None);
                }
                if obj.get("contentMediaType") == Some(&Value::String("application/json".into())) {
                    return Ok(None);
                }
                self.mk(ctx, kw, V::ContentEncoding(s.clone()))
            }
            "uniqueItems" => {
                if v == &Value::Bool(true) {
                    self.mk(ctx, kw, V::UniqueItems)
                } else {
                    None
                }
            }
            "properties" => {
                if self.additional_absorbs(obj) {
                    return Ok(None);
                }
                let m = match v {
                    Value::Object(m) => m,
                    _ => return Ok(None),
                };
                let mut props = vec![];
                for (k, x) in m {
                    props.push((k.clone(), self.sub(x, ctx, &["properties", k])?));
                }
                let required = match obj.get("required") {
                    Some(Value::Array(a)) if a.len() >= 2 => Some(a.iter().filter_map(|s| s.as_str().map(|s| s.to_string())).collect()),
                    _ => None,
                };
                self.mk(ctx, kw, V::Properties { props, required })
            }
            "patternProperties" => {
                if self.additional_absorbs(obj) {
                    return Ok(None);
                }
                let m = match v {
                    Value::Object(m) => m,
                    _ => return Ok(None),
                };
                let mut pats = vec![];
                for (k, x) in m {
                    let node = self.sub(x, ctx, &["patternProperties", k])?;
                    match self.compile_pattern(k) {
                        Some(p) => pats.push((p, node)),
                        None => return Err(format!("{} is not a \"regex\"", jstr(x))),
                    }
                }
                self.mk(ctx, kw, V::PatternProperties(pats))
            }
            "additionalProperties" => {
                if !self.additional_absorbs(obj) {
                    return Ok(None);
                }
                let schema = self.sub(v, ctx, &["additionalProperties"])?;
                let is_false = v == &Value::Bool(false);
                let mut props = vec![];
                let mut has_props = false;
                if let Some(Value::Object(m)) = obj.get("properties") {
                    has_props = true;
                    for (k, x) in m {
                        props.push((k.clone(), self.sub(x, ctx, &["properties", k])?));
                    }
                }
                let mut patterns = vec![];
                let mut has_patterns = false;
                if let Some(Value::Object(m)) = obj.get("patternProperties") {
                    has_patterns = true;
                    for (k, x) in m {
                        let node = self.sub(x, ctx, &["patternProperties", k])?;
                        match self.compile_pattern(k) {
                            Some(p) => patterns.push((p, node)),
                            None => return Err(format!("{} is not a \"regex\"", jstr(x))),
                        }
                    }
                }
                let props_loc = loc_str(&ctx.base, &kw_ptr(&ctx.ptr, "properties"));
                let pats_loc = loc_str(&ctx.base, &kw_ptr(&ctx.ptr, "patternProperties"));
                self.mk(ctx, kw, V::AdditionalProperties { props, patterns, schema, is_false, has_props, has_patterns, props_loc, pats_loc })
            }
            "propertyNames" => {
                if v == &Value::Bool(true) {
                    return Ok(None);
                }
                let node = self.sub(v, ctx, &["propertyNames"])?;
                self.mk(ctx, kw, V::PropertyNames(node))
            }
            "items" => {
                match v {
                    Value::Array(a) => {
                        if draft >= Draft::D2020 {
                            return Ok(None);
                        }
                        let mut nodes = vec![];
                        for (i, x) in a.iter().enumerate() {
                            nodes.push(self.sub(x, ctx, &["items", &i.to_string()])?);
                        }
                        self.mk(ctx, kw, V::ItemsArray(nodes))
                    }
                    Value::Bool(true) => None,
                    Value::Object(_) | Value::Bool(false) => {
                        let node = self.sub(v, ctx, &["items"])?;
                        let skip = if draft >= Draft::D2020 {
                            match obj.get("prefixItems") {
                                Some(Value::Array(a)) => a.len(),
                                _ => 0,
                            }
                        } else {
                            0
                        };
                        if skip > 0 {
                            self.mk(ctx, kw, V::ItemsSkip { node, skip })
                        } else {
                            // specialization: {"type": X} only
                            let mut single_type = None;
                            if let Value::Object(m) = v {
                                if m.len() == 1 {
                                    if let Some(Value::String(t)) = m.get("type") {
                                        single_type = type_bit(t);
                                    }
                                }
                            }
                            self.mk(ctx, kw, V::ItemsAll(node, single_type, draft))
                        }
                    }
                    _ => None,
                }
            }
            "additionalItems" => {
                if draft >= Draft::D2020 {
                    return Ok(None);
                }
                let skip = match obj.get("items") {
                    Some(Value::Array(a)) => a.len(),
                    _ => return Ok(None),
                };
                if v == &Value::Bool(true) {
                    return Ok(None);
                }
                let node = self.sub(v, ctx, &["additionalItems"])?;
                self.mk(ctx, kw, V::AdditionalItems { node, skip, is_false: v == &Value::Bool(false) })
            }
            "prefixItems" => {
                if draft < Draft::D2020 {
                    return Ok(None);
                }
                let a = match v {
                    Value::Array(a) => a,
                    _ => return Ok(None),
                };
                let mut nodes = vec![];
                for (i, x) in a.iter().enumerate() {
                    nodes.push(self.sub(x, ctx, &["prefixItems", &i.to_string()])?);
                }
                self.mk(ctx, kw, V::PrefixItems(nodes))
            }
            "contains" => {
                let node = self.sub(v, ctx, &["contains"])?;
                let (min, max) = if draft >= Draft::D2019 {
                    (obj.get("minContains").and_then(as_u64), obj.get("maxContains").and_then(as_u64))
                } else {
                    (None, None)
                };
                self.mk(ctx, kw, V::Contains { node, min, max })
            }
            "dependencies" => {
                let m = match v {
                    Value::Object(m) => m,
                    _ => return Ok(None),
                };
                let mut deps = vec![];
                for (k, x) in m {
                    match x {
                        Value::Array(a) => deps.push((k.clone(), DepKind::Required(a.iter().filter_map(|s| s.as_str().map(|s| s.to_string())).collect()))),
                        _ => deps.push((k.clone(), DepKind::Schema(self.sub(x, ctx, &["dependencies", k])?))),
                    }
                }
                let loc = loc_str(&ctx.base, &kw_ptr(&ctx.ptr, kw));
                self.mk(ctx, kw, V::Dependencies { deps, loc })
            }
            "dependentSchemas" => {
                let m = match v {
                    Value::Object(m) => m,
                    _ => return Ok(None),
                };
                let mut deps = vec![];
                for (k, x) in m {
                    deps.push((k.clone(), self.sub(x, ctx, &["dependentSchemas", k])?));
                }
                self.mk(ctx, kw, V::DependentSchemas(deps))
            }
            "allOf" | "anyOf" | "oneOf" => {
                let a = match v {
                    Value::Array(a) => a,
                    _ => return Ok(None),
                };
                let mut nodes = vec![];
                for (i, x) in a.iter().enumerate() {
                    nodes.push(self.sub(x, ctx, &[kw, &i.to_string()])?);
                }
                let vv = match kw {
                    "allOf" => V::AllOf(nodes),
                    "anyOf" => V::AnyOf(nodes),
                    _ => V::OneOf(nodes),
                };
                self.mk(ctx, kw, vv)
            }
            "not" => {
                let node = self.sub(v, ctx, &["not"])?;
                self.mk(ctx, kw, V::Not(node, v.clone()))
            }
            "if" => {
                let then = obj.get("then");
                let els = obj.get("else");
                if then.is_none() && els.is_none() {
                    return Ok(None);
                }
                let cond = self.sub(v, ctx, &["if"])?;
                let then = match then {
                    Some(t) => Some(self.sub(t, ctx, &["then"])?),
                    None => None,
                };
                let els = match els {
                    Some(t) => Some(self.sub(t, ctx, &["else"])?),
                    None => None,
                };
                self.mk(ctx, kw, V::If { cond, then, els })
            }
            "unevaluatedProperties" => {
                if v == &Value::Bool(true) {
                    return Ok(None);
                }
                let schema = self.sub(v, ctx, &["unevaluatedProperties"])?;
                let info = self.eval_info(obj, ctx)?;
                self.mk(ctx, kw, V::UnevaluatedProperties(Rc::new(UnevalProps { schema, is_false: v == &Value::Bool(false), info })))
            }
            "unevaluatedItems" => {
                if v == &Value::Bool(true) {
                    return Ok(None);
                }
                let schema = self.sub(v, ctx, &["unevaluatedItems"])?;
                let info = self.eval_info(obj, ctx)?;
                self.mk(ctx, kw, V::UnevaluatedItems(Rc::new(UnevalItems { schema, is_false: v == &Value::Bool(false), info })))
            }
            "$ref" | "$dynamicRef" | "$recursiveRef" => return self.compile_ref(v, kw, ctx),
            _ => None,
        })
    }

    fn additional_absorbs(&self, obj: &Map<String, Value>) -> bool {
        match obj.get("additionalProperties") {
            Some(Value::Bool(true)) | None => false,
            Some(_) => true,
        }
    }

    pub fn compile_ref(&self, v: &Value, kw: &str, ctx: &Ctx) -> Result<Option<Kw>, String> {
        let r = match v {
            Value::String(s) => s,
            _ => return Ok(None),
        };
        let cur_loc = loc_str(&ctx.base, &ctx.ptr);
        let (target, tbase, tptr, key) = if kw == "$recursiveRef" {
            self.resolve_recursive(r, ctx)?
        } else if kw == "$dynamicRef" {
            let res = self.resolve_dynamic(r, ctx)?;
            res
        } else {
            self.lookup(&ctx.base, r)?
        };
        if kw != "$recursiveRef" {
            // self reference => no validator
            let resolved = registry::resolve_str(&ctx.base, r)?;
            let rk = format!("{}#{}", resolved.to_string_no_fragment(), resolved.fragment.clone().unwrap_or_default());
            if rk == cur_loc {
                return Ok(None);
            }
        }
        let loc = loc_str(&ctx.base, &tptr);
        let tdraft = target.draft;
        let mut nctx = Ctx { base: tbase.clone(), ptr: tptr.clone(), draft: tdraft, ref_stack: ctx.ref_stack.clone(), scope: ctx.scope.clone() };
        let tb = tbase.to_string_no_fragment();
        if nctx.scope.last() != Some(&tb) {
            let mut sc = (*nctx.scope).clone();
            sc.push(tb);
            nctx.scope = Rc::new(sc);
        }
        let rt = if ctx.ref_stack.contains(&key) {
            RefTarget {
                key: key.clone(),
                eager: None,
                lazy: Some(Rc::new(LazyRef { key: key.clone(), comp: self.rc(), ctx: nctx, target, cell: OnceCell::new() })),
            }
        } else {
            let mut st = (*ctx.ref_stack).clone();
            st.push(key.clone());
            nctx.ref_stack = Rc::new(st);
            let tv = self.reg.get(&target).cloned().unwrap_or(Value::Bool(true));
            let node = self.compile_node(&tv, &nctx)?;
            RefTarget { key: key.clone(), eager: Some(node), lazy: None }
        };
        Ok(Some(Kw { name: kw.to_string(), loc, v: V::Ref(rt) }))
    }

    fn resolve_recursive(&self, r: &str, ctx: &Ctx) -> Result<(Loc, Uri, String, String), String> {
        let res = self.lookup(&ctx.base, r)?;
        let tv = self.reg.get(&res.0);
        let anchored = matches!(tv, Some(Value::Object(m)) if m.get("$recursiveAnchor") == Some(&Value::Bool(true)));
        if !anchored {
            return Ok(res);
        }
        for s in ctx.scope.iter() {
            if let Some(l) = self.reg.resources.get(s) {
                if let Some(Value::Object(m)) = self.reg.get(l) {
                    if m.get("$recursiveAnchor") == Some(&Value::Bool(true)) {
                        let mut b = uri::parse(s).unwrap_or_default();
                        uri::normalize(&mut b);
                        let key = format!("{}#", s);
                        return Ok((l.clone(), b, String::new(), key));
                    }
                }
            }
        }
        Ok(res)
    }

    fn resolve_dynamic(&self, r: &str, ctx: &Ctx) -> Result<(Loc, Uri, String, String), String> {
        let res = self.lookup(&ctx.base, r)?;
        let resolved = registry::resolve_str(&ctx.base, r)?;
        let frag = resolved.fragment.clone().unwrap_or_default();
        if frag.is_empty() || frag.starts_with('/') {
            return Ok(res);
        }
        // is the static target a dynamic anchor?
        let nf = resolved.to_string_no_fragment();
        let is_dyn = matches!(self.reg.anchors.get(&(nf, frag.clone())), Some((_, true)));
        if !is_dyn {
            return Ok(res);
        }
        for s in ctx.scope.iter() {
            if let Some((l, true)) = self.reg.anchors.get(&(s.clone(), frag.clone())) {
                let mut b = uri::parse(s).unwrap_or_default();
                uri::normalize(&mut b);
                let key = format!("{}#{}", s, frag);
                return Ok((l.clone(), b, String::new(), key));
            }
        }
        Ok(res)
    }

    fn eval_info(&self, obj: &Map<String, Value>, ctx: &Ctx) -> Result<Rc<EvalInfo>, String> {
        let draft = ctx.draft;
        let mut info = EvalInfo {
            props: vec![],
            patterns: vec![],
            additional: false,
            uneval_props_present: false,
            prefix_len: 0,
            items_all: false,
            contains: None,
            uneval_items_present: false,
            subs_all: vec![],
            subs_any: vec![],
            conditional: None,
            dependent: vec![],
            refs: vec![],
        };
        if let Some(Value::Object(m)) = obj.get("properties") {
            info.props = m.keys().cloned().collect();
        }
        if let Some(Value::Object(m)) = obj.get("patternProperties") {
            for k in m.keys() {
                if let Some(p) = self.compile_pattern(k) {
                    info.patterns.push(p);
                }
            }
        }
        if obj.contains_key("additionalProperties") {
            info.additional = true;
        }
        if obj.contains_key("unevaluatedProperties") {
            info.uneval_props_present = true;
        }
        if obj.contains_key("unevaluatedItems") {
            info.uneval_items_present = true;
        }
        if draft >= Draft::D2020 {
            if let Some(Value::Array(a)) = obj.get("prefixItems") {
                info.prefix_len = a.len();
            }
            if obj.contains_key("items") {
                info.items_all = true;
            }
        } else {
            match obj.get("items") {
                Some(Value::Array(a)) => {
                    info.prefix_len = a.len();
                    if obj.contains_key("additionalItems") {
                        info.items_all = true;
                    }
                }
                Some(_) => info.items_all = true,
                None => {}
            }
        }
        if let Some(c) = obj.get("contains") {
            info.contains = Some(self.sub(c, ctx, &["contains"])?);
        }
        let mk_sub = |v: &Value, segs: &[&str]| -> Result<Option<Rc<EvalInfoNode>>, String> {
            let mut c = ctx.clone();
            for s in segs {
                c.ptr = kw_ptr(&c.ptr, s);
            }
            match v {
                Value::Object(m) => {
                    let node = self.compile_node(v, &c)?;
                    let inf = self.eval_info(m, &c)?;
                    Ok(Some(Rc::new(EvalInfoNode { node, info: inf })))
                }
                Value::Bool(_) => {
                    let node = self.compile_node(v, &c)?;
                    let inf = self.eval_info(&Map::new(), &c)?;
                    Ok(Some(Rc::new(EvalInfoNode { node, info: inf })))
                }
                _ => Ok(None),
            }
        };
        if let Some(Value::Array(a)) = obj.get("allOf") {
            for (i, x) in a.iter().enumerate() {
                if let Some(n) = mk_sub(x, &["allOf", &i.to_string()])? {
                    info.subs_all.push(n);
                }
            }
        }
        for k in ["anyOf", "oneOf"] {
            if let Some(Value::Array(a)) = obj.get(k) {
                for (i, x) in a.iter().enumerate() {
                    if let Some(n) = mk_sub(x, &[k, &i.to_string()])? {
                        info.subs_any.push(n);
                    }
                }
            }
        }
        if let Some(c) = obj.get("if") {
            if let Some(ci) = mk_sub(c, &["if"])? {
                let t = match obj.get("then") {
                    Some(t) => mk_sub(t, &["then"])?,
                    None => None,
                };
                let e = match obj.get("else") {
                    Some(t) => mk_sub(t, &["else"])?,
                    None => None,
                };
                info.conditional = Some((ci, t, e));
            }
        }
        if let Some(Value::Object(m)) = obj.get("dependentSchemas") {
            for (k, x) in m {
                if let Some(n) = mk_sub(x, &["dependentSchemas", k])? {
                    info.dependent.push((k.clone(), n));
                }
            }
        }
        for rk in ["$ref", "$dynamicRef", "$recursiveRef"] {
            if !obj.contains_key(rk) || !is_known(rk, draft) {
                continue;
            }
            if let Some(kw) = self.compile_ref(&obj[rk], rk, ctx)? {
                if let V::Ref(rt) = kw.v {
                    info.refs.push(RefInfo { target: Rc::new(RefTargetInfo { rt: Rc::new(rt) }) });
                }
            }
        }
        Ok(Rc::new(info))
    }
}

pub fn anchor_valid(s: &str) -> bool {
    let b = s.as_bytes();
    if b.is_empty() {
        return false;
    }
    if !(b[0].is_ascii_alphabetic() || b[0] == b'_') {
        return false;
    }
    b.iter().all(|&c| c.is_ascii_alphanumeric() || c == b'-' || c == b'_' || c == b'.' || c == b':')
}

// ---------------------------------------------------------------- runtime state

pub struct St {
    pub active: Vec<(String, String)>,
}

impl St {
    pub fn new() -> St {
        St { active: vec![] }
    }
}

// ---------------------------------------------------------------- validation (bool)

pub fn node_valid(n: &Node, inst: &Value, ip: &str, st: &mut St) -> bool {
    match &n.kind {
        NodeKind::True => true,
        NodeKind::False => false,
        NodeKind::Obj(kws) => kws.iter().all(|k| kw_valid(k, inst, ip, st)),
    }
}

fn str_len(s: &str) -> u64 {
    s.chars().count() as u64
}

fn bound_ok(kind: BoundKind, inst: &Number, limit: &Number) -> bool {
    let c = num::cmp_instance_limit(inst, limit);
    match kind {
        BoundKind::Min => c != Ordering::Less,
        BoundKind::Max => c != Ordering::Greater,
        BoundKind::ExMin => c == Ordering::Greater,
        BoundKind::ExMax => c == Ordering::Less,
    }
}

fn multiple_ok(inst: &Number, m: &Number) -> bool {
    let a = num::dec_of(inst);
    let b = num::dec_of(m);
    a.is_multiple_of(&b)
}

fn is_unique(a: &[Value]) -> bool {
    for i in 0..a.len() {
        for j in (i + 1)..a.len() {
            if values_equal(&a[i], &a[j]) {
                return false;
            }
        }
    }
    true
}

fn with_lazy<T>(rt: &RefTarget, ip: &str, st: &mut St, f: impl FnOnce(&Node, &mut St) -> T, cut: T) -> T {
    if rt.eager.is_some() {
        let n = rt.node();
        return f(&n, st);
    }
    let key = (rt.key.clone(), ip.to_string());
    if st.active.contains(&key) {
        return cut;
    }
    st.active.push(key);
    let n = rt.node();
    let r = f(&n, st);
    st.active.pop();
    r
}

pub fn kw_valid(k: &Kw, inst: &Value, ip: &str, st: &mut St) -> bool {
    match &k.v {
        V::Type { types, draft, .. } => matches_type(inst, *types, *draft),
        V::Const(c) => values_equal(c, inst),
        V::Enum(opts) => opts.iter().any(|o| values_equal(o, inst)),
        V::Bound { limit, kind } => match inst {
            Value::Number(n) => bound_ok(*kind, n, limit),
            _ => true,
        },
        V::MultipleOf(m) => match inst {
            Value::Number(n) => multiple_ok(n, m),
            _ => true,
        },
        V::MinLength(n) => match inst {
            Value::String(s) => str_len(s) >= *n,
            _ => true,
        },
        V::MaxLength(n) => match inst {
            Value::String(s) => str_len(s) <= *n,
            _ => true,
        },
        V::MinItems(n) => match inst {
            Value::Array(a) => a.len() as u64 >= *n,
            _ => true,
        },
        V::MaxItems(n) => match inst {
            Value::Array(a) => a.len() as u64 <= *n,
            _ => true,
        },
        V::MinProperties(n) => match inst {
            Value::Object(o) => o.len() as u64 >= *n,
            _ => true,
        },
        V::MaxProperties(n) => match inst {
            Value::Object(o) => o.len() as u64 <= *n,
            _ => true,
        },
        V::Required(names) => match inst {
            Value::Object(o) => names.iter().all(|n| o.contains_key(n)),
            _ => true,
        },
        V::DependentRequired { deps, .. } => match inst {
            Value::Object(o) => deps.iter().all(|(k, req)| !o.contains_key(k) || req.iter().all(|r| o.contains_key(r))),
            _ => true,
        },
        V::Pattern(p) => match inst {
            Value::String(s) => p.is_match(s),
            _ => true,
        },
        V::Format { check, .. } => match inst {
            Value::String(s) => formats::check(check, s),
            _ => true,
        },
        V::ContentMediaType { encoding, .. } => match inst {
            Value::String(s) => content_ok(s, encoding.is_some(), true),
            _ => true,
        },
        V::ContentEncoding(_) => match inst {
            Value::String(s) => formats::base64_decode(s).is_some(),
            _ => true,
        },
        V::UniqueItems => match inst {
            Value::Array(a) => is_unique(a),
            _ => true,
        },
        V::Properties { props, required } => match inst {
            Value::Object(o) => {
                if let Some(req) = required {
                    if !req.iter().all(|r| o.contains_key(r)) {
                        return false;
                    }
                }
                props.iter().all(|(name, node)| match o.get(name) {
                    Some(v) => node_valid(node, v, &child_path(ip, name), st),
                    None => true,
                })
            }
            _ => true,
        },
        V::PatternProperties(pats) => match inst {
            Value::Object(o) => pats.iter().all(|(p, node)| o.iter().all(|(k, v)| !p.is_match(k) || node_valid(node, v, &child_path(ip, k), st))),
            _ => true,
        },
        V::AdditionalProperties { props, patterns, schema, .. } => match inst {
            Value::Object(o) => o.iter().all(|(k, v)| {
                let cp = child_path(ip, k);
                let mut matched = false;
                if let Some((_, n)) = props.iter().find(|(n, _)| n == k) {
                    matched = true;
                    if !node_valid(n, v, &cp, st) {
                        return false;
                    }
                }
                for (p, n) in patterns {
                    if p.is_match(k) {
                        matched = true;
                        if !node_valid(n, v, &cp, st) {
                            return false;
                        }
                    }
                }
                matched || node_valid(schema, v, &cp, st)
            }),
            _ => true,
        },
        V::PropertyNames(node) => match inst {
            Value::Object(o) => o.keys().all(|k| node_valid(node, &Value::String(k.clone()), ip, st)),
            _ => true,
        },
        V::ItemsAll(node, _, _) => match inst {
            Value::Array(a) => a.iter().enumerate().all(|(i, v)| node_valid(node, v, &child_idx(ip, i), st)),
            _ => true,
        },
        V::ItemsArray(nodes) => match inst {
            Value::Array(a) => a.iter().zip(nodes.iter()).enumerate().all(|(i, (v, n))| node_valid(n, v, &child_idx(ip, i), st)),
            _ => true,
        },
        V::ItemsSkip { node, skip } => match inst {
            Value::Array(a) => a.iter().enumerate().skip(*skip).all(|(i, v)| node_valid(node, v, &child_idx(ip, i), st)),
            _ => true,
        },
        V::AdditionalItems { node, skip, .. } => match inst {
            Value::Array(a) => a.iter().enumerate().skip(*skip).all(|(i, v)| node_valid(node, v, &child_idx(ip, i), st)),
            _ => true,
        },
        V::PrefixItems(nodes) => match inst {
            Value::Array(a) => a.iter().zip(nodes.iter()).enumerate().all(|(i, (v, n))| node_valid(n, v, &child_idx(ip, i), st)),
            _ => true,
        },
        V::Contains { node, min, max } => match inst {
            Value::Array(a) => {
                let cnt = a.iter().enumerate().filter(|(i, v)| node_valid(node, v, &child_idx(ip, *i), st)).count() as u64;
                contains_ok(cnt, *min, *max)
            }
            _ => true,
        },
        V::Dependencies { deps, .. } => match inst {
            Value::Object(o) => deps.iter().all(|(k, d)| {
                if !o.contains_key(k) {
                    return true;
                }
                match d {
                    DepKind::Required(r) => r.iter().all(|x| o.contains_key(x)),
                    DepKind::Schema(n) => node_valid(n, inst, ip, st),
                }
            }),
            _ => true,
        },
        V::DependentSchemas(deps) => match inst {
            Value::Object(o) => deps.iter().all(|(k, n)| !o.contains_key(k) || node_valid(n, inst, ip, st)),
            _ => true,
        },
        V::AllOf(nodes) => nodes.iter().all(|n| node_valid(n, inst, ip, st)),
        V::AnyOf(nodes) => nodes.iter().any(|n| node_valid(n, inst, ip, st)),
        V::OneOf(nodes) => {
            let mut c = 0;
            for n in nodes {
                if node_valid(n, inst, ip, st) {
                    c += 1;
                    if c > 1 {
                        return false;
                    }
                }
            }
            c == 1
        }
        V::Not(n, _) => !node_valid(n, inst, ip, st),
        V::If { cond, then, els } => {
            if node_valid(cond, inst, ip, st) {
                then.as_ref().map(|t| node_valid(t, inst, ip, st)).unwrap_or(true)
            } else {
                els.as_ref().map(|t| node_valid(t, inst, ip, st)).unwrap_or(true)
            }
        }
        V::UnevaluatedProperties(u) => match inst {
            Value::Object(o) => {
                let ev = evaluated_props(&u.info, inst, ip, st);
                o.iter().all(|(k, v)| ev.contains(k) || node_valid(&u.schema, v, &child_path(ip, k), st))
            }
            _ => true,
        },
        V::UnevaluatedItems(u) => match inst {
            Value::Array(a) => {
                let ev = evaluated_items(&u.info, inst, ip, st);
                a.iter().enumerate().all(|(i, v)| ev[i] || node_valid(&u.schema, v, &child_idx(ip, i), st))
            }
            _ => true,
        },
        V::Ref(rt) => with_lazy(rt, ip, st, |n, st| node_valid(n, inst, ip, st), true),
    }
}

fn contains_ok(cnt: u64, min: Option<u64>, max: Option<u64>) -> bool {
    let min = min.unwrap_or(1);
    if cnt < min {
        return false;
    }
    if let Some(m) = max {
        if cnt > m {
            return false;
        }
    }
    true
}

fn content_ok(s: &str, base64: bool, _json: bool) -> bool {
    if base64 {
        match formats::base64_decode(s) {
            Some(bytes) => serde_json::from_slice::<Value>(&bytes).is_ok(),
            None => false,
        }
    } else {
        serde_json::from_str::<Value>(s).is_ok()
    }
}

// ---------------------------------------------------------------- unevaluated computation

pub fn evaluated_props(info: &EvalInfo, inst: &Value, ip: &str, st: &mut St) -> std::collections::HashSet<String> {
    let mut set = std::collections::HashSet::new();
    collect_props(info, inst, ip, st, &mut set, true);
    set
}

fn collect_props(info: &EvalInfo, inst: &Value, ip: &str, st: &mut St, set: &mut std::collections::HashSet<String>, top: bool) {
    let o = match inst {
        Value::Object(o) => o,
        _ => return,
    };
    if info.additional {
        for k in o.keys() {
            set.insert(k.clone());
        }
        return;
    }
    if !top && info.uneval_props_present {
        for k in o.keys() {
            set.insert(k.clone());
        }
        return;
    }
    for p in &info.props {
        if o.contains_key(p) {
            set.insert(p.clone());
        }
    }
    for pat in &info.patterns {
        for k in o.keys() {
            if pat.is_match(k) {
                set.insert(k.clone());
            }
        }
    }
    for s in &info.subs_all {
        if node_valid(&s.node, inst, ip, st) {
            collect_props(&s.info, inst, ip, st, set, false);
        }
    }
    for s in &info.subs_any {
        if node_valid(&s.node, inst, ip, st) {
            collect_props(&s.info, inst, ip, st, set, false);
        }
    }
    if let Some((c, t, e)) = &info.conditional {
        if node_valid(&c.node, inst, ip, st) {
            collect_props(&c.info, inst, ip, st, set, false);
            if let Some(t) = t {
                if node_valid(&t.node, inst, ip, st) {
                    collect_props(&t.info, inst, ip, st, set, false);
                }
            }
        } else if let Some(e) = e {
            if node_valid(&e.node, inst, ip, st) {
                collect_props(&e.info, inst, ip, st, set, false);
            }
        }
    }
    for (k, d) in &info.dependent {
        if o.contains_key(k) && node_valid(&d.node, inst, ip, st) {
            collect_props(&d.info, inst, ip, st, set, false);
        }
    }
    for r in &info.refs {
        let rt = &r.target.rt;
        let node = rt.node();
        if node_valid(&node, inst, ip, st) {
            if let Some(i) = node_info(&node) {
                collect_props_node(&i, inst, ip, st, set);
            }
        }
    }
}

fn node_info(_n: &Node) -> Option<()> {
    Some(())
}

fn collect_props_node(_i: &(), inst: &Value, ip: &str, st: &mut St, set: &mut std::collections::HashSet<String>) {
    let _ = (inst, ip, st, set);
}

pub fn evaluated_items(info: &EvalInfo, inst: &Value, ip: &str, st: &mut St) -> Vec<bool> {
    let n = match inst {
        Value::Array(a) => a.len(),
        _ => 0,
    };
    let mut ev = vec![false; n];
    collect_items(info, inst, ip, st, &mut ev, true);
    ev
}

fn collect_items(info: &EvalInfo, inst: &Value, ip: &str, st: &mut St, ev: &mut Vec<bool>, top: bool) {
    let a = match inst {
        Value::Array(a) => a,
        _ => return,
    };
    if info.items_all || (!top && info.uneval_items_present) {
        for e in ev.iter_mut() {
            *e = true;
        }
        return;
    }
    for i in 0..info.prefix_len.min(a.len()) {
        ev[i] = true;
    }
    if let Some(c) = &info.contains {
        for (i, v) in a.iter().enumerate() {
            if node_valid(c, v, &child_idx(ip, i), st) {
                ev[i] = true;
            }
        }
    }
    for s in &info.subs_all {
        if node_valid(&s.node, inst, ip, st) {
            collect_items(&s.info, inst, ip, st, ev, false);
        }
    }
    for s in &info.subs_any {
        if node_valid(&s.node, inst, ip, st) {
            collect_items(&s.info, inst, ip, st, ev, false);
        }
    }
    if let Some((c, t, e)) = &info.conditional {
        if node_valid(&c.node, inst, ip, st) {
            collect_items(&c.info, inst, ip, st, ev, false);
            if let Some(t) = t {
                if node_valid(&t.node, inst, ip, st) {
                    collect_items(&t.info, inst, ip, st, ev, false);
                }
            }
        } else if let Some(e) = e {
            if node_valid(&e.node, inst, ip, st) {
                collect_items(&e.info, inst, ip, st, ev, false);
            }
        }
    }
}
