pub fn jstr(v: &Value) -> String {
    serde_json::to_string(v).unwrap_or_default()
}

pub fn ptr_escape(s: &str) -> String {
    s.replace('~', "~0").replace('/', "~1")
}

pub fn values_equal(a: &Value, b: &Value) -> bool {
    match (a, b) {
        (Value::Number(x), Value::Number(y)) => num::num_eq(x, y),
        (Value::Array(x), Value::Array(y)) => x.len() == y.len() && x.iter().zip(y.iter()).all(|(p, q)| values_equal(p, q)),
        (Value::Object(x), Value::Object(y)) => {
            x.len() == y.len() && x.iter().all(|(k, v)| y.get(k).map(|w| values_equal(v, w)).unwrap_or(false))
        }
        _ => a == b,
    }
}

// ---------------------------------------------------------------- types

pub const T_ARRAY: u8 = 1;
pub const T_BOOLEAN: u8 = 2;
pub const T_INTEGER: u8 = 4;
pub const T_NULL: u8 = 8;
pub const T_NUMBER: u8 = 16;
pub const T_OBJECT: u8 = 32;
pub const T_STRING: u8 = 64;
pub const TYPE_NAMES: [(u8, &str); 7] = [
    (T_ARRAY, "array"),
    (T_BOOLEAN, "boolean"),
    (T_INTEGER, "integer"),
    (T_NULL, "null"),
    (T_NUMBER, "number"),
    (T_OBJECT, "object"),
    (T_STRING, "string"),
];

pub fn type_bit(s: &str) -> Option<u8> {
    TYPE_NAMES.iter().find(|(_, n)| *n == s).map(|(b, _)| *b)
}

pub fn is_integer(n: &Number, draft: Draft) -> bool {
    let s = n.to_string();
    if draft == Draft::D4 && s.contains('.') {
        return false;
    }
    num::Dec::parse(&s).map(|d| d.is_integer()).unwrap_or(false)
}

pub fn matches_type(v: &Value, t: u8, draft: Draft) -> bool {
    match v {
        Value::Array(_) => t & T_ARRAY != 0,
        Value::Bool(_) => t & T_BOOLEAN != 0,
        Value::Null => t & T_NULL != 0,
        Value::Object(_) => t & T_OBJECT != 0,
        Value::String(_) => t & T_STRING != 0,
        Value::Number(n) => t & T_NUMBER != 0 || (t & T_INTEGER != 0 && is_integer(n, draft)),
    }
}

