cd /workspace && cat > src/engine.rs <<'EOF'
//! Schema compilation (nodes and keywords).
use crate::ecma;
use crate::formats;
use crate::num;
use crate::registry::{self, Draft, Loc, Registry, Seg};
use crate::uri::{self, Uri};
use serde_json::{Map, Number, Value};
use std::cell::OnceCell;
use std::rc::Rc;

// ---------------------------------------------------------------- helpers

pub fn jstr(v: &Value) -> String {
    serde_json::to_string(v).unwrap_or_default()
}

pub fn ptr_escape(s: &str) -> String {
    s.replace('~', "~0").replace('/', "~1")
}

pub fn values_equal(a: &Value, b: &Value) -> bool {
    match (a, b) {
        (Value::Number(x), Value::Number(y)) => num::num_eq(x, y),
        (Value::Array(x), Value::Array(y)) => x.len() == y.len() && x.iter().zip(y.iter()).all(|(p, q)| values_equal(p, q)),
        (Value::Object(x), Value::Object(y)) => {
            x.len() == y.len() && x.iter().all(|(k, v)| y.get(k).map(|w| values_equal(v, w)).unwrap_or(false))
        }
        _ => a == b,
    }
}

// ---------------------------------------------------------------- types

pub const T_ARRAY: u8 = 1;
pub const T_BOOLEAN: u8 = 2;
pub const T_INTEGER: u8 = 4;
pub const T_NULL: u8 = 8;
pub const T_NUMBER: u8 = 16;
pub const T_OBJECT: u8 = 32;
pub const T_STRING: u8 = 64;
pub const TYPE_NAMES: [(u8, &str); 7] = [
    (T_ARRAY, "array"),
    (T_BOOLEAN, "boolean"),
    (T_INTEGER, "integer"),
    (T_NULL, "null"),
    (T_NUMBER, "number"),
    (T_OBJECT, "object"),
    (T_STRING, "string"),
];

pub fn type_bit(s: &str) -> Option<u8> {
    TYPE_NAMES.iter().find(|(_, n)| *n == s).map(|(b, _)| *b)
}

pub fn is_integer(n: &Number, draft: Draft) -> bool {
    let s = n.to_string();
    if draft == Draft::D4 && s.contains('.') {
        return false;
    }
    num::Dec::parse(&s).map(|d| d.is_integer()).unwrap_or(false)
}

pub fn matches_type(v: &Value, t: u8, draft: Draft) -> bool {
    match v {
        Value::Array(_) => t & T_ARRAY != 0,
        Value::Bool(_) => t & T_BOOLEAN != 0,
        Value::Null => t & T_NULL != 0,
        Value::Object(_) => t & T_OBJECT != 0,
        Value::String(_) => t & T_STRING != 0,
        Value::Number(n) => t & T_NUMBER != 0 || (t & T_INTEGER != 0 && is_integer(n, draft)),
    }
}

// ---------------------------------------------------------------- nodes

pub struct Node {
    pub kind: NodeKind,
    pub loc: String,
    pub annotations: Option<Value>,
    /// hidden information for unevaluated* computations
    pub all_props: bool,
    pub all_items: bool,
    pub hidden_if: Option<Rc<Node>>,
    pub draft: Draft,
}

pub enum NodeKind {
    True,
    False,
    Obj(Vec<Kw>),
}

pub struct Kw {
    pub name: String,
    pub loc: String,
    pub v: V,
}

pub struct Pattern {
    pub re: Rc<fancy_regex::Regex>,
    pub display: String,
    pub raw: String,
}

impl Pattern {
    pub fn is_match(&self, s: &str) -> bool {
        self.re.is_match(s).unwrap_or(false)
    }
}

pub enum V {
    Type { types: u8, multi: bool, draft: Draft },
    Const(Value),
    Enum(Vec<Value>),
    Bound { limit: Number, kind: BoundKind },
    MultipleOf(Number),
    MinLength(u64),
    MaxLength(u64),
    MinItems(u64),
    MaxItems(u64),
    MinProperties(u64),
    MaxProperties(u64),
    Required(Vec<String>),
    DependentRequired(Vec<(String, Vec<String>)>),
    Pattern(Pattern),
    Format { name: String, check: formats::Check },
    ContentMediaType { media: String, encoding: Option<String> },
    ContentEncoding(String),
    UniqueItems,
    Properties { props: Vec<(String, Rc<Node>)>, required: Option<Vec<String>> },
    PatternProperties(Vec<(Pattern, Rc<Node>)>),
    AdditionalProperties(Box<AddProps>),
    PropertyNames(Rc<Node>),
    ItemsAll { node: Rc<Node>, single_type: Option<u8> },
    ItemsArray(Vec<Rc<Node>>),
    ItemsSkip { node: Rc<Node>, skip: usize },
    AdditionalItems { node: Rc<Node>, skip: usize, is_false: bool },
    PrefixItems(Vec<Rc<Node>>),
    Contains { node: Rc<Node>, min: Option<u64>, max: Option<u64>, minmax: bool },
    Dependencies(Vec<(String, DepKind)>),
    DependentSchemas(Vec<(String, Rc<Node>)>),
    AllOf(Vec<Rc<Node>>),
    AnyOf(Vec<Rc<Node>>),
    OneOf(Vec<Rc<Node>>),
    Not(Rc<Node>, Value),
    If { cond: Rc<Node>, then: Option<Rc<Node>>, els: Option<Rc<Node>> },
    UnevaluatedProperties { schema: Rc<Node>, is_false: bool },
    UnevaluatedItems { schema: Rc<Node>, is_false: bool },
    Ref(RefTarget),
}

pub struct AddProps {
    pub props: Vec<(String, Rc<Node>)>,
    pub patterns: Vec<(Pattern, Rc<Node>)>,
    pub schema: Rc<Node>,
    pub is_false: bool,
    pub has_props: bool,
    pub has_patterns: bool,
    pub props_loc: String,
    pub pats_loc: String,
}

pub enum DepKind {
    Required(Vec<String>),
    Schema(Rc<Node>),
}

#[derive(Clone, Copy, PartialEq)]
pub enum BoundKind {
    Min,
    Max,
    ExMin,
    ExMax,
}

pub struct RefTarget {
    pub key: String,
    pub eager: Option<Rc<Node>>,
    pub lazy: Option<Rc<LazyRef>>,
}

pub struct LazyRef {
    pub key: String,
    pub comp: Rc<Compiler>,
    pub ctx: Ctx,
    pub target: Loc,
    pub cell: OnceCell<Rc<Node>>,
}

impl LazyRef {
    fn get(&self) -> Rc<Node> {
        self.cell
            .get_or_init(|| {
                let v = self.comp.reg.get(&self.target).cloned().unwrap_or(Value::Bool(true));
                let mut ctx = self.ctx.clone();
                ctx.ref_stack = Rc::new(vec![self.key.clone()]);
                match self.comp.compile_node(&v, &ctx) {
                    Ok(n) => n,
                    Err(_) => Rc::new(Node::simple(NodeKind::True, String::new(), ctx.draft)),
                }
            })
            .clone()
    }
}

impl RefTarget {
    pub fn node(&self) -> Rc<Node> {
        if let Some(n) = &self.eager {
            n.clone()
        } else {
            self.lazy.as_ref().unwrap().get()
        }
    }
    pub fn is_lazy(&self) -> bool {
        self.eager.is_none()
    }
}

impl Node {
    pub fn simple(kind: NodeKind, loc: String, draft: Draft) -> Node {
        Node { kind, loc, annotations: None, all_props: false, all_items: false, hidden_if: None, draft }
    }
}

// ---------------------------------------------------------------- compiler

#[derive(Clone)]
pub struct Ctx {
    pub base: Uri,
    pub ptr: String,
    pub draft: Draft,
    pub ref_stack: Rc<Vec<String>>,
    pub scope: Rc<Vec<String>>,
}

pub struct Options {
    pub validate_formats: bool,
    pub vocab_none: bool,
    pub vocab: Option<Vec<String>>,
}

pub struct Compiler {
    pub reg: Rc<Registry>,
    pub opts: Options,
    pub self_rc: OnceCell<std::rc::Weak<Compiler>>,
}

pub fn loc_str(base: &Uri, ptr: &str) -> String {
    format!("{}#{}", base.to_string_no_fragment(), ptr)
}

pub fn kw_ptr(ptr: &str, kw: &str) -> String {
    format!("{}/{}", ptr, ptr_escape(kw))
}

const KW_ORDER: &[&str] = &[
    "type",
    "const",
    "enum",
    "minimum",
    "maximum",
    "exclusiveMinimum",
    "exclusiveMaximum",
    "multipleOf",
    "minLength",
    "maxLength",
    "minItems",
    "maxItems",
    "minProperties",
    "maxProperties",
    "required",
    "dependentRequired",
    "pattern",
    "format",
    "contentMediaType",
    "contentEncoding",
    "uniqueItems",
    "properties",
    "additionalProperties",
    "patternProperties",
    "propertyNames",
    "items",
    "additionalItems",
    "prefixItems",
    "contains",
    "dependencies",
    "dependentSchemas",
    "allOf",
    "anyOf",
    "oneOf",
    "not",
    "if",
    "unevaluatedProperties",
    "unevaluatedItems",
    "$ref",
    "$recursiveRef",
    "$dynamicRef",
];

/// Keywords that are recognized for a draft (are not collected as annotations).
pub fn is_known(kw: &str, draft: Draft) -> bool {
    match kw {
        "$schema" | "$ref" | "type" | "enum" | "multipleOf" | "maximum" | "exclusiveMaximum" | "minimum" | "exclusiveMinimum" | "maxLength"
        | "minLength" | "pattern" | "items" | "additionalItems" | "maxItems" | "minItems" | "uniqueItems" | "maxProperties"
        | "minProperties" | "required" | "properties" | "patternProperties" | "additionalProperties" | "dependencies" | "allOf"
        | "anyOf" | "oneOf" | "not" | "format" => true,
        "id" => draft == Draft::D4,
        "$id" | "const" | "contains" | "propertyNames" => draft >= Draft::D6,
        "if" | "then" | "else" => draft >= Draft::D7,
        "contentMediaType" | "contentEncoding" => draft == Draft::D6 || draft == Draft::D7,
        "$anchor" | "$defs" | "dependentRequired" | "dependentSchemas" | "maxContains" | "minContains" | "unevaluatedItems"
        | "unevaluatedProperties" | "prefixItems" | "$recursiveAnchor" | "$recursiveRef" => draft >= Draft::D2019,
        "$dynamicAnchor" | "$dynamicRef" => draft >= Draft::D2020,
        _ => false,
    }
}

pub fn as_u64(v: &Value) -> Option<u64> {
    match v {
        Value::Number(n) => {
            if let Some(u) = n.as_u64() {
                return Some(u);
            }
            let s = n.to_string();
            let d = num::Dec::parse(&s)?;
            if d.is_integer() && !d.neg {
                s.parse::<f64>().ok().map(|f| f as u64)
            } else {
                None
            }
        }
        _ => None,
    }
}

pub fn anchor_valid(s: &str) -> bool {
    let b = s.as_bytes();
    if b.is_empty() {
        return false;
    }
    if !(b[0].is_ascii_alphabetic() || b[0] == b'_') {
        return false;
    }
    b.iter().all(|&c| c.is_ascii_alphanumeric() || c == b'-' || c == b'_' || c == b'.' || c == b':')
}

fn str_list(v: &Value) -> Vec<String> {
    match v {
        Value::Array(a) => a.iter().filter_map(|x| x.as_str().map(|s| s.to_string())).collect(),
        _ => vec![],
    }
}

impl Compiler {
    pub fn rc(&self) -> Rc<Compiler> {
        self.self_rc.get().unwrap().upgrade().unwrap()
    }

    /// Returns (target location, target base, location pointer, key)
    pub fn lookup(&self, base: &Uri, reference: &str) -> Result<(Loc, Uri, String, String), String> {
        let resolved = registry::resolve_str(base, reference)?;
        let nf = resolved.to_string_no_fragment();
        let frag = resolved.fragment.clone().unwrap_or_default();
        let key = format!("{}#{}", nf, frag);
        let res = match self.reg.resources.get(&nf) {
            Some(r) => r.clone(),
            None => {
                return Err(format!(
                    "Resource '{}' is not present in a registry and retrieving it failed: Retrieving external resources is not supported once the registry is populated",
                    nf
                ))
            }
        };
        let mut tbase = uri::parse(&nf).unwrap_or_default();
        uri::normalize(&mut tbase);
        if frag.is_empty() {
            return Ok((res, tbase, String::new(), key));
        }
        if frag.starts_with('/') {
            let decoded = uri::percent_decode(&frag);
            let mut loc = res.clone();
            let notfound = || format!("Pointer '{}' does not exist", frag);
            let mut cur = self.reg.get(&res).ok_or_else(notfound)?;
            let mut base = tbase.clone();
            let parts: Vec<&str> = decoded[1..].split('/').collect();
            let nparts = parts.len();
            for (i, p) in parts.iter().enumerate() {
                let p = p.replace("~1", "/").replace("~0", "~");
                let next = match cur {
                    Value::Object(m) => {
                        let n = m.get(&p).ok_or_else(notfound)?;
                        loc.path.push(Seg::Key(p.clone()));
                        n
                    }
                    Value::Array(a) => {
                        if p.len() > 1 && p.starts_with('0') {
                            return Err(notfound());
                        }
                        let idx: usize = p.parse().map_err(|_| notfound())?;
                        let n = a.get(idx).ok_or_else(notfound)?;
                        loc.path.push(Seg::Idx(idx));
                        n
                    }
                    _ => return Err(notfound()),
                };
                cur = next;
                if i + 1 < nparts {
                    if let Value::Object(m) = cur {
                        let idk = if res.draft == Draft::D4 { "id" } else { "$id" };
                        if let Some(Value::String(id)) = m.get(idk) {
                            if !(res.draft <= Draft::D7 && (m.contains_key("$ref") || id.starts_with('#'))) {
                                if let Ok(nb) = registry::resolve_str(&base, id) {
                                    base = nb.without_fragment();
                                }
                            }
                        }
                    }
                }
            }
            return Ok((loc, base, frag.clone(), key));
        }
        if !anchor_valid(&frag) {
            return Err(format!("Anchor '{}' is invalid", frag));
        }
        match self.reg.anchors.get(&(nf.clone(), frag.clone())) {
            Some((l, _)) => Ok((l.clone(), tbase, String::new(), key)),
            None => Err(format!("Anchor '{}' does not exist", frag)),
        }
    }

    pub fn compile_node(&self, v: &Value, ctx: &Ctx) -> Result<Rc<Node>, String> {
        let loc = loc_str(&ctx.base, &ctx.ptr);
        match v {
            Value::Bool(true) => Ok(Rc::new(Node::simple(NodeKind::True, loc, ctx.draft))),
            Value::Bool(false) => Ok(Rc::new(Node::simple(NodeKind::False, loc, ctx.draft))),
            Value::Object(obj) => self.compile_object(obj, ctx),
            _ => Ok(Rc::new(Node::simple(NodeKind::True, loc, ctx.draft))),
        }
    }

    fn sub(&self, v: &Value, ctx: &Ctx, segs: &[&str]) -> Result<Rc<Node>, String> {
        let mut c = ctx.clone();
        for s in segs {
            c.ptr = kw_ptr(&c.ptr, s);
        }
        self.compile_node(v, &c)
    }

    fn compile_object(&self, obj: &Map<String, Value>, ctx0: &Ctx) -> Result<Rc<Node>, String> {
        let mut ctx = ctx0.clone();
        let draft = ctx.draft;
        let has_ref = obj.contains_key("$ref");
        let legacy_ref = draft <= Draft::D7 && has_ref;
        let id_key = if draft == Draft::D4 { "id" } else { "$id" };
        if !legacy_ref {
            if let Some(Value::String(id)) = obj.get(id_key) {
                if !(draft <= Draft::D7 && id.starts_with('#')) {
                    if let Ok(nb) = registry::resolve_str(&ctx.base, id) {
                        let nb = nb.without_fragment();
                        if nb != ctx.base {
                            let s = nb.to_string_no_fragment();
                            if ctx.scope.last() != Some(&s) {
                                let mut sc = (*ctx.scope).clone();
                                sc.push(s);
                                ctx.scope = Rc::new(sc);
                            }
                        }
                        ctx.base = nb;
                    }
                }
            }
        }
        let loc = loc_str(&ctx.base, &ctx.ptr);
        let mut node = Node::simple(NodeKind::Obj(vec![]), loc, draft);
        if self.opts.vocab_none {
            return Ok(Rc::new(node));
        }
        let mut kws: Vec<Kw> = Vec::new();
        let mut annotations = Map::new();
        if legacy_ref {
            for (k, v) in obj.iter() {
                if k != "$ref" {
                    annotations.insert(k.clone(), v.clone());
                }
            }
            if let Some(kw) = self.compile_ref(obj.get("$ref").unwrap(), "$ref", &ctx)? {
                kws.push(kw);
            }
            node.annotations = if annotations.is_empty() { None } else { Some(Value::Object(annotations)) };
            node.kind = NodeKind::Obj(kws);
            return Ok(Rc::new(node));
        }
        for (k, v) in obj.iter() {
            if !is_known(k, draft) || !self.vocab_allows(k, draft) {
                annotations.insert(k.clone(), v.clone());
            }
        }
        for &kw in KW_ORDER {
            if !obj.contains_key(kw) || !is_known(kw, draft) || !self.vocab_allows(kw, draft) {
                continue;
            }
            if let Some(k) = self.compile_keyword(kw, obj, &ctx)? {
                kws.push(k);
            }
        }
        // hidden evaluation info
        if obj.contains_key("additionalProperties") && self.vocab_allows("additionalProperties", draft) {
            node.all_props = true;
        }
        if draft >= Draft::D2020 {
            if obj.contains_key("items") {
                node.all_items = true;
            }
        } else if draft >= Draft::D2019 {
            match obj.get("items") {
                Some(Value::Array(_)) => {
                    if obj.contains_key("additionalItems") {
                        node.all_items = true;
                    }
                }
                Some(_) => node.all_items = true,
                None => {}
            }
        }
        if draft >= Draft::D2019 && obj.contains_key("if") && !obj.contains_key("then") && !obj.contains_key("else") {
            node.hidden_if = Some(self.sub(&obj["if"], &ctx, &["if"])?);
        }
        node.annotations = if annotations.is_empty() { None } else { Some(Value::Object(annotations)) };
        node.kind = NodeKind::Obj(kws);
        Ok(Rc::new(node))
    }

    fn vocab_allows(&self, _kw: &str, _draft: Draft) -> bool {
        match &self.opts.vocab {
            None => true,
            Some(list) => {
                let v = vocab_of(_kw, _draft);
                match v {
                    None => true,
                    Some(name) => list.iter().any(|x| x.ends_with(name)),
                }
            }
        }
    }

    fn mk(&self, ctx: &Ctx, name: &str, v: V) -> Option<Kw> {
        Some(Kw { name: name.to_string(), loc: loc_str(&ctx.base, &kw_ptr(&ctx.ptr, name)), v })
    }

    pub fn compile_pattern(&self, p: &str) -> Option<Pattern> {
        let t = ecma::translate(p)?;
        let re = fancy_regex::RegexBuilder::new(&t).backtrack_limit(1_000_000).build().ok()?;
        Some(Pattern { re: Rc::new(re), display: t, raw: p.to_string() })
    }

    fn additional_absorbs(&self, obj: &Map<String, Value>) -> bool {
        match obj.get("additionalProperties") {
            Some(Value::Bool(true)) | None => false,
            Some(_) => true,
        }
    }

    fn compile_keyword(&self, kw: &str, obj: &Map<String, Value>, ctx: &Ctx) -> Result<Option<Kw>, String> {
        let draft = ctx.draft;
        let v = &obj[kw];
        Ok(match kw {
            "type" => {
                let mut types = 0u8;
                let mut multi = false;
                match v {
                    Value::String(s) => types |= type_bit(s).unwrap_or(0),
                    Value::Array(a) => {
                        for x in a {
                            if let Value::String(s) = x {
                                types |= type_bit(s).unwrap_or(0);
                            }
                        }
                        multi = a.len() != 1;
                    }
                    _ => return Ok(None),
                }
                self.mk(ctx, kw, V::Type { types, multi, draft })
            }
            "const" => self.mk(ctx, kw, V::Const(v.clone())),
            "enum" => match v {
                Value::Array(a) => self.mk(ctx, kw, V::Enum(a.clone())),
                _ => None,
            },
            "minimum" | "maximum" => {
                let n = match v {
                    Value::Number(n) => n.clone(),
                    _ => return Ok(None),
                };
                let excl = draft == Draft::D4
                    && obj.get(if kw == "minimum" { "exclusiveMinimum" } else { "exclusiveMaximum" }) == Some(&Value::Bool(true));
                let kind = match (kw, excl) {
                    ("minimum", false) => BoundKind::Min,
                    ("minimum", true) => BoundKind::ExMin,
                    ("maximum", false) => BoundKind::Max,
                    _ => BoundKind::ExMax,
                };
                self.mk(ctx, kw, V::Bound { limit: n, kind })
            }
            "exclusiveMinimum" | "exclusiveMaximum" => {
                if draft == Draft::D4 {
                    return Ok(None);
                }
                let n = match v {
                    Value::Number(n) => n.clone(),
                    _ => return Ok(None),
                };
                let kind = if kw == "exclusiveMinimum" { BoundKind::ExMin } else { BoundKind::ExMax };
                self.mk(ctx, kw, V::Bound { limit: n, kind })
            }
            "multipleOf" => match v {
                Value::Number(n) => self.mk(ctx, kw, V::MultipleOf(n.clone())),
                _ => None,
            },
            "minLength" => as_u64(v).and_then(|n| self.mk(ctx, kw, V::MinLength(n))),
            "maxLength" => as_u64(v).and_then(|n| self.mk(ctx, kw, V::MaxLength(n))),
            "minItems" => as_u64(v).and_then(|n| self.mk(ctx, kw, V::MinItems(n))),
            "maxItems" => as_u64(v).and_then(|n| self.mk(ctx, kw, V::MaxItems(n))),
            "minProperties" => as_u64(v).and_then(|n| self.mk(ctx, kw, V::MinProperties(n))),
            "maxProperties" => as_u64(v).and_then(|n| self.mk(ctx, kw, V::MaxProperties(n))),
            "required" => {
                let names = match v {
                    Value::Array(_) => str_list(v),
                    _ => return Ok(None),
                };
                if names.is_empty() {
                    return Ok(None);
                }
                if names.len() >= 2 && obj.get("properties").map(|p| p.is_object()).unwrap_or(false) && !self.additional_absorbs(obj) {
                    return Ok(None);
                }
                self.mk(ctx, kw, V::Required(names))
            }
            "dependentRequired" => {
                let m = match v {
                    Value::Object(m) => m,
                    _ => return Ok(None),
                };
                let mut deps = vec![];
                for (k, x) in m {
                    if let Value::Array(_) = x {
                        deps.push((k.clone(), str_list(x)));
                    }
                }
                self.mk(ctx, kw, V::DependentRequired(deps))
            }
            "pattern" => {
                let s = match v {
                    Value::String(s) => s,
                    _ => return Ok(None),
                };
                match self.compile_pattern(s) {
                    Some(p) => self.mk(ctx, kw, V::Pattern(p)),
                    None => return Err(format!("{} is not a \"regex\"", jstr(v))),
                }
            }
            "format" => {
                if !self.opts.validate_formats {
                    return Ok(None);
                }
                let s = match v {
                    Value::String(s) => s,
                    _ => return Ok(None),
                };
                match formats::lookup(s, draft) {
                    Some(check) => self.mk(ctx, kw, V::Format { name: s.clone(), check }),
                    None => None,
                }
            }
            "contentMediaType" => {
                let s = match v {
                    Value::String(s) => s,
                    _ => return Ok(None),
                };
                if s != "application/json" {
                    return Ok(None);
                }
                let enc = match obj.get("contentEncoding") {
                    Some(Value::String(e)) if e == "base64" => Some(e.clone()),
                    _ => None,
                };
                self.mk(ctx, kw, V::ContentMediaType { media: s.clone(), encoding: enc })
            }
            "contentEncoding" => {
                let s = match v {
                    Value::String(s) => s,
                    _ => return Ok(None),
                };
                if s != "base64" {
                    return Ok(None);
                }
                if obj.get("contentMediaType") == Some(&Value::String("application/json".into())) {
                    return Ok(None);
                }
                self.mk(ctx, kw, V::ContentEncoding(s.clone()))
            }
            "uniqueItems" => {
                if v == &Value::Bool(true) {
                    self.mk(ctx, kw, V::UniqueItems)
                } else {
                    None
                }
            }
            "properties" => {
                if self.additional_absorbs(obj) {
                    return Ok(None);
                }
                let m = match v {
                    Value::Object(m) => m,
                    _ => return Ok(None),
                };
                let mut props = vec![];
                for (k, x) in m {
                    props.push((k.clone(), self.sub(x, ctx, &["properties", k])?));
                }
                let required = match obj.get("required") {
                    Some(r @ Value::Array(a)) if a.len() >= 2 => Some(str_list(r)),
                    _ => None,
                };
                self.mk(ctx, kw, V::Properties { props, required })
            }
            "patternProperties" => {
                if self.additional_absorbs(obj) {
                    return Ok(None);
                }
                let m = match v {
                    Value::Object(m) => m,
                    _ => return Ok(None),
                };
                let mut pats = vec![];
                for (k, x) in m {
                    let node = self.sub(x, ctx, &["patternProperties", k])?;
                    match self.compile_pattern(k) {
                        Some(p) => pats.push((p, node)),
                        None => return Err(format!("{} is not a \"regex\"", jstr(x))),
                    }
                }
                self.mk(ctx, kw, V::PatternProperties(pats))
            }
            "additionalProperties" => {
                if !self.additional_absorbs(obj) {
                    return Ok(None);
                }
                let schema = self.sub(v, ctx, &["additionalProperties"])?;
                let is_false = v == &Value::Bool(false);
                let mut props = vec![];
                let mut has_props = false;
                if let Some(Value::Object(m)) = obj.get("properties") {
                    has_props = true;
                    for (k, x) in m {
                        props.push((k.clone(), self.sub(x, ctx, &["properties", k])?));
                    }
                }
                let mut patterns = vec![];
                let mut has_patterns = false;
                if let Some(Value::Object(m)) = obj.get("patternProperties") {
                    has_patterns = true;
                    for (k, x) in m {
                        let node = self.sub(x, ctx, &["patternProperties", k])?;
                        match self.compile_pattern(k) {
                            Some(p) => patterns.push((p, node)),
                            None => return Err(format!("{} is not a \"regex\"", jstr(x))),
                        }
                    }
                }
                let props_loc = loc_str(&ctx.base, &kw_ptr(&ctx.ptr, "properties"));
                let pats_loc = loc_str(&ctx.base, &kw_ptr(&ctx.ptr, "patternProperties"));
                self.mk(
                    ctx,
                    kw,
                    V::AdditionalProperties(Box::new(AddProps { props, patterns, schema, is_false, has_props, has_patterns, props_loc, pats_loc })),
                )
            }
            "propertyNames" => {
                if v == &Value::Bool(true) {
                    return Ok(None);
                }
                let node = self.sub(v, ctx, &["propertyNames"])?;
                self.mk(ctx, kw, V::PropertyNames(node))
            }
            "items" => match v {
                Value::Array(a) => {
                    if draft >= Draft::D2020 {
                        return Ok(None);
                    }
                    let mut nodes = vec![];
                    for (i, x) in a.iter().enumerate() {
                        nodes.push(self.sub(x, ctx, &["items", &i.to_string()])?);
                    }
                    self.mk(ctx, kw, V::ItemsArray(nodes))
                }
                Value::Bool(true) => None,
                Value::Object(_) | Value::Bool(false) => {
                    let node = self.sub(v, ctx, &["items"])?;
                    let skip = if draft >= Draft::D2020 {
                        match obj.get("prefixItems") {
                            Some(Value::Array(a)) => a.len(),
                            _ => 0,
                        }
                    } else {
                        0
                    };
                    if skip > 0 {
                        self.mk(ctx, kw, V::ItemsSkip { node, skip })
                    } else {
                        let mut single_type = None;
                        if let Value::Object(m) = v {
                            if m.len() == 1 {
                                if let Some(Value::String(t)) = m.get("type") {
                                    single_type = type_bit(t);
                                }
                            }
                        }
                        self.mk(ctx, kw, V::ItemsAll { node, single_type })
                    }
                }
                _ => None,
            },
            "additionalItems" => {
                if draft >= Draft::D2020 {
                    return Ok(None);
                }
                let skip = match obj.get("items") {
                    Some(Value::Array(a)) => a.len(),
                    _ => return Ok(None),
                };
                if v == &Value::Bool(true) {
                    return Ok(None);
                }
                let node = self.sub(v, ctx, &["additionalItems"])?;
                self.mk(ctx, kw, V::AdditionalItems { node, skip, is_false: v == &Value::Bool(false) })
            }
            "prefixItems" => {
                if draft < Draft::D2020 {
                    return Ok(None);
                }
                let a = match v {
                    Value::Array(a) => a,
                    _ => return Ok(None),
                };
                let mut nodes = vec![];
                for (i, x) in a.iter().enumerate() {
                    nodes.push(self.sub(x, ctx, &["prefixItems", &i.to_string()])?);
                }
                self.mk(ctx, kw, V::PrefixItems(nodes))
            }
            "contains" => {
                let node = self.sub(v, ctx, &["contains"])?;
                let (min, max) = if draft >= Draft::D2019 {
                    (obj.get("minContains").and_then(as_u64), obj.get("maxContains").and_then(as_u64))
                } else {
                    (None, None)
                };
                let minmax = draft >= Draft::D2019 && (obj.contains_key("minContains") || obj.contains_key("maxContains"));
                self.mk(ctx, kw, V::Contains { node, min, max, minmax })
            }
            "dependencies" => {
                let m = match v {
                    Value::Object(m) => m,
                    _ => return Ok(None),
                };
                let mut deps = vec![];
                for (k, x) in m {
                    match x {
                        Value::Array(_) => deps.push((k.clone(), DepKind::Required(str_list(x)))),
                        _ => deps.push((k.clone(), DepKind::Schema(self.sub(x, ctx, &["dependencies", k])?))),
                    }
                }
                self.mk(ctx, kw, V::Dependencies(deps))
            }
            "dependentSchemas" => {
                let m = match v {
                    Value::Object(m) => m,
                    _ => return Ok(None),
                };
                let mut deps = vec![];
                for (k, x) in m {
                    deps.push((k.clone(), self.sub(x, ctx, &["dependentSchemas", k])?));
                }
                self.mk(ctx, kw, V::DependentSchemas(deps))
            }
            "allOf" | "anyOf" | "oneOf" => {
                let a = match v {
                    Value::Array(a) => a,
                    _ => return Ok(None),
                };
                let mut nodes = vec![];
                for (i, x) in a.iter().enumerate() {
                    nodes.push(self.sub(x, ctx, &[kw, &i.to_string()])?);
                }
                let vv = match kw {
                    "allOf" => V::AllOf(nodes),
                    "anyOf" => V::AnyOf(nodes),
                    _ => V::OneOf(nodes),
                };
                self.mk(ctx, kw, vv)
            }
            "not" => {
                let node = self.sub(v, ctx, &["not"])?;
                self.mk(ctx, kw, V::Not(node, v.clone()))
            }
            "if" => {
                let then = obj.get("then");
                let els = obj.get("else");
                if then.is_none() && els.is_none() {
                    return Ok(None);
                }
                let cond = self.sub(v, ctx, &["if"])?;
                let then = match then {
                    Some(t) => Some(self.sub(t, ctx, &["then"])?),
                    None => None,
                };
                let els = match els {
                    Some(t) => Some(self.sub(t, ctx, &["else"])?),
                    None => None,
                };
                self.mk(ctx, kw, V::If { cond, then, els })
            }
            "unevaluatedProperties" => {
                if v == &Value::Bool(true) {
                    return Ok(None);
                }
                let schema = self.sub(v, ctx, &["unevaluatedProperties"])?;
                self.mk(ctx, kw, V::UnevaluatedProperties { schema, is_false: v == &Value::Bool(false) })
            }
            "unevaluatedItems" => {
                if v == &Value::Bool(true) {
                    return Ok(None);
                }
                let schema = self.sub(v, ctx, &["unevaluatedItems"])?;
                self.mk(ctx, kw, V::UnevaluatedItems { schema, is_false: v == &Value::Bool(false) })
            }
            "$ref" | "$dynamicRef" | "$recursiveRef" => {
                if kw == "$recursiveRef" && draft != Draft::D2019 {
                    return Ok(None);
                }
                return self.compile_ref(v, kw, ctx);
            }
            _ => None,
        })
    }

    pub fn compile_ref(&self, v: &Value, kw: &str, ctx: &Ctx) -> Result<Option<Kw>, String> {
        let r = match v {
            Value::String(s) => s,
            _ => return Ok(None),
        };
        let cur_loc = loc_str(&ctx.base, &ctx.ptr);
        let (target, tbase, tptr, key) = if kw == "$recursiveRef" {
            self.resolve_recursive(r, ctx)?
        } else if kw == "$dynamicRef" {
            self.resolve_dynamic(r, ctx)?
        } else {
            self.lookup(&ctx.base, r)?
        };
        if kw != "$recursiveRef" {
            let resolved = registry::resolve_str(&ctx.base, r)?;
            let rk = format!("{}#{}", resolved.to_string_no_fragment(), resolved.fragment.clone().unwrap_or_default());
            if rk == cur_loc {
                return Ok(None);
            }
        }
        let loc = loc_str(&ctx.base, &tptr);
        let tdraft = target.draft;
        let mut nctx = Ctx { base: tbase.clone(), ptr: tptr.clone(), draft: tdraft, ref_stack: ctx.ref_stack.clone(), scope: ctx.scope.clone() };
        let tb = tbase.to_string_no_fragment();
        if nctx.scope.last() != Some(&tb) {
            let mut sc = (*nctx.scope).clone();
            sc.push(tb);
            nctx.scope = Rc::new(sc);
        }
        let rt = if ctx.ref_stack.contains(&key) {
            RefTarget {
                key: key.clone(),
                eager: None,
                lazy: Some(Rc::new(LazyRef { key: key.clone(), comp: self.rc(), ctx: nctx, target, cell: OnceCell::new() })),
            }
        } else {
            let mut st = (*ctx.ref_stack).clone();
            st.push(key.clone());
            nctx.ref_stack = Rc::new(st);
            let tv = self.reg.get(&target).cloned().unwrap_or(Value::Bool(true));
            let node = self.compile_node(&tv, &nctx)?;
            RefTarget { key: key.clone(), eager: Some(node), lazy: None }
        };
        Ok(Some(Kw { name: kw.to_string(), loc, v: V::Ref(rt) }))
    }

    fn resolve_recursive(&self, r: &str, ctx: &Ctx) -> Result<(Loc, Uri, String, String), String> {
        let res = self.lookup(&ctx.base, r)?;
        let tv = self.reg.get(&res.0);
        let anchored = matches!(tv, Some(Value::Object(m)) if m.get("$recursiveAnchor") == Some(&Value::Bool(true)));
        if !anchored {
            return Ok(res);
        }
        for s in ctx.scope.iter() {
            if let Some(l) = self.reg.resources.get(s) {
                if let Some(Value::Object(m)) = self.reg.get(l) {
                    if m.get("$recursiveAnchor") == Some(&Value::Bool(true)) {
                        let mut b = uri::parse(s).unwrap_or_default();
                        uri::normalize(&mut b);
                        let key = format!("{}#", s);
                        return Ok((l.clone(), b, String::new(), key));
                    }
                }
            }
        }
        Ok(res)
    }

    fn resolve_dynamic(&self, r: &str, ctx: &Ctx) -> Result<(Loc, Uri, String, String), String> {
        let res = self.lookup(&ctx.base, r)?;
        let resolved = registry::resolve_str(&ctx.base, r)?;
        let frag = resolved.fragment.clone().unwrap_or_default();
        if frag.is_empty() || frag.starts_with('/') {
            return Ok(res);
        }
        let nf = resolved.to_string_no_fragment();
        let is_dyn = matches!(self.reg.anchors.get(&(nf, frag.clone())), Some((_, true)));
        if !is_dyn {
            return Ok(res);
        }
        for s in ctx.scope.iter() {
            if let Some((l, true)) = self.reg.anchors.get(&(s.clone(), frag.clone())) {
                let mut b = uri::parse(s).unwrap_or_default();
                uri::normalize(&mut b);
                let key = format!("{}#{}", s, frag);
                return Ok((l.clone(), b, String::new(), key));
            }
        }
        Ok(res)
    }
}

pub fn vocab_of(kw: &str, draft: Draft) -> Option<&'static str> {
    if draft < Draft::D2019 {
        return None;
    }
    Some(match kw {
        "$ref" | "$dynamicRef" | "$recursiveRef" | "$id" | "$schema" | "$anchor" | "$dynamicAnchor" | "$defs" | "$recursiveAnchor" => return None,
        "type" | "enum" | "const" | "multipleOf" | "maximum" | "exclusiveMaximum" | "minimum" | "exclusiveMinimum" | "maxLength" | "minLength"
        | "pattern" | "maxItems" | "minItems" | "uniqueItems" | "maxContains" | "minContains" | "maxProperties" | "minProperties" | "required"
        | "dependentRequired" => "/validation",
        "unevaluatedItems" | "unevaluatedProperties" => {
            if draft == Draft::D2020 {
                "/unevaluated"
            } else {
                "/applicator"
            }
        }
        "format" => {
            if draft == Draft::D2020 {
                "/format-annotation"
            } else {
                "/format"
            }
        }
        _ => "/applicator",
    })
}
