cd /workspace && cat > src/validate.rs <<'EOF'
//! Validation: boolean, error iteration and evaluation output.
use crate::engine::*;
use crate::formats;
use crate::num;
use serde_json::Value;
use std::cmp::Ordering;
use std::collections::HashSet;

pub struct St {
    pub active: Vec<(String, String)>,
}

impl St {
    pub fn new() -> St {
        St { active: vec![] }
    }
}

#[derive(Debug, Clone)]
pub struct Unit {
    pub eval_path: String,
    pub schema_loc: String,
    pub inst_loc: String,
    pub valid: bool,
    pub annotations: Option<Value>,
    pub errors: Vec<(String, String)>,
    pub children: Vec<Unit>,
}

impl Unit {
    pub fn new(eval_path: &str, schema_loc: &str, inst_loc: &str) -> Unit {
        Unit {
            eval_path: eval_path.to_string(),
            schema_loc: schema_loc.to_string(),
            inst_loc: inst_loc.to_string(),
            valid: true,
            annotations: None,
            errors: vec![],
            children: vec![],
        }
    }
    fn error(&mut self, kind: &str, msg: String) {
        self.valid = false;
        self.errors.push((kind.to_string(), msg));
    }
    fn add(&mut self, c: Unit) {
        if !c.valid {
            self.valid = false;
        }
        self.children.push(c);
    }
}

pub fn child_path(p: &str, seg: &str) -> String {
    let mut s = String::with_capacity(p.len() + seg.len() + 1);
    s.push_str(p);
    s.push('/');
    s.push_str(&ptr_escape(seg));
    s
}

pub fn child_idx(p: &str, i: usize) -> String {
    format!("{}/{}", p, i)
}

fn plural(n: u64, one: &str, many: &str) -> String {
    if n == 1 {
        one.to_string()
    } else {
        many.to_string()
    }
}

fn str_len(s: &str) -> u64 {
    s.chars().count() as u64
}

fn bound_ok(kind: BoundKind, inst: &serde_json::Number, limit: &serde_json::Number) -> bool {
    let c = num::cmp_instance_limit(inst, limit);
    match kind {
        BoundKind::Min => c != Ordering::Less,
        BoundKind::Max => c != Ordering::Greater,
        BoundKind::ExMin => c == Ordering::Greater,
        BoundKind::ExMax => c == Ordering::Less,
    }
}

fn multiple_ok(inst: &serde_json::Number, m: &serde_json::Number) -> bool {
    let a = num::dec_of(inst);
    let b = num::dec_of(m);
    a.is_multiple_of(&b)
}

fn is_unique(a: &[Value]) -> bool {
    for i in 0..a.len() {
        for j in (i + 1)..a.len() {
            if values_equal(&a[i], &a[j]) {
                return false;
            }
        }
    }
    true
}

fn contains_ok(cnt: u64, min: Option<u64>, max: Option<u64>) -> bool {
    let min = min.unwrap_or(1);
    if cnt < min {
        return false;
    }
    if let Some(m) = max {
        if cnt > m {
            return false;
        }
    }
    true
}

/// 0 = ok, 1 = encoding error, 2 = media type error
fn content_check(s: &str, base64: bool) -> u8 {
    if base64 {
        match formats::base64_decode(s) {
            Some(bytes) => {
                if serde_json::from_slice::<Value>(&bytes).is_ok() {
                    0
                } else {
                    2
                }
            }
            None => 1,
        }
    } else if serde_json::from_str::<Value>(s).is_ok() {
        0
    } else {
        2
    }
}

fn type_names(t: u8) -> Vec<&'static str> {
    TYPE_NAMES.iter().filter(|(b, _)| t & b != 0).map(|(_, n)| *n).collect()
}

fn type_msg(inst: &Value, t: u8, multi: bool) -> String {
    let names = type_names(t);
    if !multi && names.len() == 1 {
        format!("{} is not of type \"{}\"", jstr(inst), names[0])
    } else {
        let q: Vec<String> = names.iter().map(|n| format!("\"{}\"", n)).collect();
        format!("{} is not of types {}", jstr(inst), q.join(", "))
    }
}

fn type_msg_eval(inst: &Value, t: u8, multi: bool) -> String {
    let names = type_names(t);
    if !multi && names.len() == 1 {
        format!("{} is not of type \"{}\"", jstr(inst), names[0])
    } else {
        format!("{} is not of types ({})", jstr(inst), names.join(", "))
    }
}

fn enum_msg(inst: &Value, opts: &[Value]) -> String {
    let s: Vec<String> = opts.iter().map(jstr).collect();
    let list = if s.len() <= 3 {
        if s.len() <= 1 {
            s.join("")
        } else {
            format!("{} or {}", s[..s.len() - 1].join(", "), s[s.len() - 1])
        }
    } else {
        format!("{}, {} or {} other candidates", s[0], s[1], s.len() - 2)
    };
    format!("{} is not one of {}", jstr(inst), list)
}

fn bound_msg(kind: BoundKind, inst: &Value, limit: &serde_json::Number) -> (&'static str, String) {
    match kind {
        BoundKind::Min => ("minimum", format!("{} is less than the minimum of {}", jstr(inst), limit)),
        BoundKind::Max => ("maximum", format!("{} is greater than the maximum of {}", jstr(inst), limit)),
        BoundKind::ExMin => ("exclusiveMinimum", format!("{} is less than or equal to the minimum of {}", jstr(inst), limit)),
        BoundKind::ExMax => ("exclusiveMaximum", format!("{} is greater than or equal to the maximum of {}", jstr(inst), limit)),
    }
}

fn quoted_list(names: &[String]) -> String {
    let q: Vec<String> = names.iter().map(|n| format!("'{}'", n)).collect();
    q.join(", ")
}

fn was_were(n: usize) -> &'static str {
    if n == 1 {
        "was"
    } else {
        "were"
    }
}

fn required_msg(name: &str) -> String {
    format!("{} is a required property", jstr(&Value::String(name.to_string())))
}

fn false_msg(inst: &Value) -> String {
    format!("False schema does not allow {}", jstr(inst))
}

// ---------------------------------------------------------------- simple keyword checks (no subschemas)

/// returns Some(list of (kind, text msg, eval msg)) for simple keywords, None if not simple
fn simple_errors(k: &Kw, inst: &Value) -> Option<Vec<(&'static str, String, String)>> {
    let mut out = vec![];
    match &k.v {
        V::Type { types, multi, draft } => {
            if !matches_type(inst, *types, *draft) {
                out.push(("type", type_msg(inst, *types, *multi), type_msg_eval(inst, *types, *multi)));
            }
        }
        V::Const(c) => {
            if !values_equal(c, inst) {
                let m = format!("{} was expected", jstr(c));
                out.push(("const", m.clone(), m));
            }
        }
        V::Enum(opts) => {
            if !opts.iter().any(|o| values_equal(o, inst)) {
                let m = enum_msg(inst, opts);
                out.push(("enum", m.clone(), m));
            }
        }
        V::Bound { limit, kind } => {
            if let Value::Number(n) = inst {
                if !bound_ok(*kind, n, limit) {
                    let (k, m) = bound_msg(*kind, inst, limit);
                    out.push((k, m.clone(), m));
                }
            }
        }
        V::MultipleOf(m) => {
            if let Value::Number(n) = inst {
                if !multiple_ok(n, m) {
                    let s = format!("{} is not a multiple of {}", jstr(inst), m);
                    out.push(("multipleOf", s.clone(), s));
                }
            }
        }
        V::MinLength(n) => {
            if let Value::String(s) = inst {
                if str_len(s) < *n {
                    let m = format!("{} is shorter than {} {}", jstr(inst), n, plural(*n, "character", "characters"));
                    out.push(("minLength", m.clone(), m));
                }
            }
        }
        V::MaxLength(n) => {
            if let Value::String(s) = inst {
                if str_len(s) > *n {
                    let m = format!("{} is longer than {} {}", jstr(inst), n, plural(*n, "character", "characters"));
                    out.push(("maxLength", m.clone(), m));
                }
            }
        }
        V::MinItems(n) => {
            if let Value::Array(a) = inst {
                if (a.len() as u64) < *n {
                    let m = format!("{} has less than {} {}", jstr(inst), n, plural(*n, "item", "items"));
                    out.push(("minItems", m.clone(), m));
                }
            }
        }
        V::MaxItems(n) => {
            if let Value::Array(a) = inst {
                if (a.len() as u64) > *n {
                    let m = format!("{} has more than {} {}", jstr(inst), n, plural(*n, "item", "items"));
                    out.push(("maxItems", m.clone(), m));
                }
            }
        }
        V::MinProperties(n) => {
            if let Value::Object(o) = inst {
                if (o.len() as u64) < *n {
                    let m = format!("{} has less than {} {}", jstr(inst), n, plural(*n, "property", "properties"));
                    out.push(("minProperties", m.clone(), m));
                }
            }
        }
        V::MaxProperties(n) => {
            if let Value::Object(o) = inst {
                if (o.len() as u64) > *n {
                    let m = format!("{} has more than {} {}", jstr(inst), n, plural(*n, "property", "properties"));
                    out.push(("maxProperties", m.clone(), m));
                }
            }
        }
        V::Required(names) => {
            if let Value::Object(o) = inst {
                for n in names {
                    if !o.contains_key(n) {
                        let m = required_msg(n);
                        out.push(("required", m.clone(), m));
                    }
                }
            }
        }
        V::Pattern(p) => {
            if let Value::String(s) = inst {
                if !p.is_match(s) {
                    let m = format!("{} does not match \"{}\"", jstr(inst), p.display);
                    out.push(("pattern", m.clone(), m));
                }
            }
        }
        V::Format { name, check } => {
            if let Value::String(s) = inst {
                if !formats::check(check, s) {
                    let m = format!("{} is not a \"{}\"", jstr(inst), name);
                    out.push(("format", m.clone(), m));
                }
            }
        }
        V::ContentMediaType { media, encoding } => {
            if let Value::String(s) = inst {
                match content_check(s, encoding.is_some()) {
                    0 => {}
                    1 => {
                        let m = format!("{} is not compliant with \"{}\" content encoding", jstr(inst), encoding.as_deref().unwrap_or(""));
                        out.push(("contentEncoding", m.clone(), m));
                    }
                    _ => {
                        let m = format!("{} is not compliant with \"{}\" media type", jstr(inst), media);
                        out.push(("contentMediaType", m.clone(), m));
                    }
                }
            }
        }
        V::ContentEncoding(enc) => {
            if let Value::String(s) = inst {
                if formats::base64_decode(s).is_none() {
                    let m = format!("{} is not compliant with \"{}\" content encoding", jstr(inst), enc);
                    out.push(("contentEncoding", m.clone(), m));
                }
            }
        }
        V::UniqueItems => {
            if let Value::Array(a) = inst {
                if !is_unique(a) {
                    let m = format!("{} has non-unique elements", jstr(inst));
                    out.push(("uniqueItems", m.clone(), m));
                }
            }
        }
        _ => return None,
    }
    Some(out)
}

// ---------------------------------------------------------------- is_valid

pub fn node_valid(n: &Node, inst: &Value, ip: &str, st: &mut St) -> bool {
    match &n.kind {
        NodeKind::True => true,
        NodeKind::False => false,
        NodeKind::Obj(kws) => kws.iter().all(|k| kw_valid(k, n, inst, ip, st)),
    }
}

fn with_ref<T>(rt: &RefTarget, ip: &str, st: &mut St, cut: T, f: impl FnOnce(&Node, &mut St) -> T) -> T {
    if !rt.is_lazy() {
        let n = rt.node();
        return f(&n, st);
    }
    let key = (rt.key.clone(), ip.to_string());
    if st.active.contains(&key) {
        return cut;
    }
    st.active.push(key);
    let n = rt.node();
    let r = f(&n, st);
    st.active.pop();
    r
}

fn kw_valid(k: &Kw, parent: &Node, inst: &Value, ip: &str, st: &mut St) -> bool {
    if let Some(errs) = simple_errors(k, inst) {
        return errs.is_empty();
    }
    match &k.v {
        V::DependentRequired(deps) => match inst {
            Value::Object(o) => deps.iter().all(|(k, req)| !o.contains_key(k) || req.iter().all(|r| o.contains_key(r))),
            _ => true,
        },
        V::Properties { props, required } => match inst {
            Value::Object(o) => {
                if let Some(req) = required {
                    if !req.iter().all(|r| o.contains_key(r)) {
                        return false;
                    }
                }
                props.iter().all(|(name, node)| match o.get(name) {
                    Some(v) => node_valid(node, v, &child_path(ip, name), st),
                    None => true,
                })
            }
            _ => true,
        },
        V::PatternProperties(pats) => match inst {
            Value::Object(o) => pats.iter().all(|(p, node)| o.iter().all(|(k, v)| !p.is_match(k) || node_valid(node, v, &child_path(ip, k), st))),
            _ => true,
        },
        V::AdditionalProperties(ap) => match inst {
            Value::Object(o) => o.iter().all(|(k, v)| {
                let cp = child_path(ip, k);
                let mut matched = false;
                if let Some((_, n)) = ap.props.iter().find(|(n, _)| n == k) {
                    matched = true;
                    if !node_valid(n, v, &cp, st) {
                        return false;
                    }
                }
                for (p, n) in &ap.patterns {
                    if p.is_match(k) {
                        matched = true;
                        if !node_valid(n, v, &cp, st) {
                            return false;
                        }
                    }
                }
                matched || node_valid(&ap.schema, v, &cp, st)
            }),
            _ => true,
        },
        V::PropertyNames(node) => match inst {
            Value::Object(o) => o.keys().all(|k| node_valid(node, &Value::String(k.clone()), ip, st)),
            _ => true,
        },
        V::ItemsAll { node, .. } => match inst {
            Value::Array(a) => a.iter().enumerate().all(|(i, v)| node_valid(node, v, &child_idx(ip, i), st)),
            _ => true,
        },
        V::ItemsArray(nodes) | V::PrefixItems(nodes) => match inst {
            Value::Array(a) => a.iter().zip(nodes.iter()).enumerate().all(|(i, (v, n))| node_valid(n, v, &child_idx(ip, i), st)),
            _ => true,
        },
        V::ItemsSkip { node, skip } | V::AdditionalItems { node, skip, .. } => match inst {
            Value::Array(a) => a.iter().enumerate().skip(*skip).all(|(i, v)| node_valid(node, v, &child_idx(ip, i), st)),
            _ => true,
        },
        V::Contains { node, min, max, .. } => match inst {
            Value::Array(a) => {
                let mut cnt = 0u64;
                for (i, v) in a.iter().enumerate() {
                    if node_valid(node, v, &child_idx(ip, i), st) {
                        cnt += 1;
                    }
                }
                contains_ok(cnt, *min, *max)
            }
            _ => true,
        },
        V::Dependencies(deps) => match inst {
            Value::Object(o) => deps.iter().all(|(k, d)| {
                if !o.contains_key(k) {
                    return true;
                }
                match d {
                    DepKind::Required(r) => r.iter().all(|x| o.contains_key(x)),
                    DepKind::Schema(n) => node_valid(n, inst, ip, st),
                }
            }),
            _ => true,
        },
        V::DependentSchemas(deps) => match inst {
            Value::Object(o) => deps.iter().all(|(k, n)| !o.contains_key(k) || node_valid(n, inst, ip, st)),
            _ => true,
        },
        V::AllOf(nodes) => nodes.iter().all(|n| node_valid(n, inst, ip, st)),
        V::AnyOf(nodes) => nodes.iter().any(|n| node_valid(n, inst, ip, st)),
        V::OneOf(nodes) => {
            let mut c = 0;
            for n in nodes {
                if node_valid(n, inst, ip, st) {
                    c += 1;
                    if c > 1 {
                        return false;
                    }
                }
            }
            c == 1
        }
        V::Not(n, _) => !node_valid(n, inst, ip, st),
        V::If { cond, then, els } => {
            if node_valid(cond, inst, ip, st) {
                then.as_ref().map(|t| node_valid(t, inst, ip, st)).unwrap_or(true)
            } else {
                els.as_ref().map(|t| node_valid(t, inst, ip, st)).unwrap_or(true)
            }
        }
        V::UnevaluatedProperties { schema, .. } => match inst {
            Value::Object(o) => {
                let ev = evaluated_props(parent, inst, ip, st);
                o.iter().all(|(k, v)| ev.contains(k) || node_valid(schema, v, &child_path(ip, k), st))
            }
            _ => true,
        },
        V::UnevaluatedItems { schema, .. } => match inst {
            Value::Array(a) => {
                let ev = evaluated_items(parent, inst, ip, st);
                a.iter().enumerate().all(|(i, v)| ev[i] || node_valid(schema, v, &child_idx(ip, i), st))
            }
            _ => true,
        },
        V::Ref(rt) => with_ref(rt, ip, st, true, |n, st| node_valid(n, inst, ip, st)),
        _ => true,
    }
}

// ---------------------------------------------------------------- unevaluated helpers

pub fn evaluated_props(node: &Node, inst: &Value, ip: &str, st: &mut St) -> HashSet<String> {
    let mut set = HashSet::new();
    collect_props(node, inst, ip, st, &mut set, true);
    set
}

fn collect_props(node: &Node, inst: &Value, ip: &str, st: &mut St, set: &mut HashSet<String>, top: bool) {
    let o = match inst {
        Value::Object(o) => o,
        _ => return,
    };
    let kws = match &node.kind {
        NodeKind::Obj(k) => k,
        _ => return,
    };
    if node.all_props {
        for k in o.keys() {
            set.insert(k.clone());
        }
        return;
    }
    for k in kws {
        match &k.v {
            V::Properties { props, .. } => {
                for (p, _) in props {
                    if o.contains_key(p) {
                        set.insert(p.clone());
                    }
                }
            }
            V::PatternProperties(pats) => {
                for (p, _) in pats {
                    for key in o.keys() {
                        if p.is_match(key) {
                            set.insert(key.clone());
                        }
                    }
                }
            }
            V::UnevaluatedProperties { .. } => {
                if !top {
                    for key in o.keys() {
                        set.insert(key.clone());
                    }
                }
            }
            V::AllOf(nodes) | V::AnyOf(nodes) | V::OneOf(nodes) => {
                for n in nodes {
                    if node_valid(n, inst, ip, st) {
                        collect_props(n, inst, ip, st, set, false);
                    }
                }
            }
            V::If { cond, then, els } => {
                if node_valid(cond, inst, ip, st) {
                    collect_props(cond, inst, ip, st, set, false);
                    if let Some(t) = then {
                        if node_valid(t, inst, ip, st) {
                            collect_props(t, inst, ip, st, set, false);
                        }
                    }
                } else if let Some(e) = els {
                    if node_valid(e, inst, ip, st) {
                        collect_props(e, inst, ip, st, set, false);
                    }
                }
            }
            V::DependentSchemas(deps) => {
                for (key, n) in deps {
                    if o.contains_key(key) && node_valid(n, inst, ip, st) {
                        collect_props(n, inst, ip, st, set, false);
                    }
                }
            }
            V::Dependencies(deps) => {
                for (key, d) in deps {
                    if let DepKind::Schema(n) = d {
                        if o.contains_key(key) && node_valid(n, inst, ip, st) {
                            collect_props(n, inst, ip, st, set, false);
                        }
                    }
                }
            }
            V::Ref(rt) => {
                let n = rt.node();
                if node_valid(&n, inst, ip, st) {
                    collect_props(&n, inst, ip, st, set, false);
                }
            }
            _ => {}
        }
    }
    if let Some(c) = &node.hidden_if {
        if node_valid(c, inst, ip, st) {
            collect_props(c, inst, ip, st, set, false);
        }
    }
}

pub fn evaluated_items(node: &Node, inst: &Value, ip: &str, st: &mut St) -> Vec<bool> {
    let n = match inst {
        Value::Array(a) => a.len(),
        _ => 0,
    };
    let mut ev = vec![false; n];
    collect_items(node, inst, ip, st, &mut ev, true);
    ev
}

fn collect_items(node: &Node, inst: &Value, ip: &str, st: &mut St, ev: &mut Vec<bool>, top: bool) {
    let a = match inst {
        Value::Array(a) => a,
        _ => return,
    };
    let kws = match &node.kind {
        NodeKind::Obj(k) => k,
        _ => return,
    };
    if node.all_items {
        for e in ev.iter_mut() {
            *e = true;
        }
        return;
    }
    for k in kws {
        match &k.v {
            V::PrefixItems(nodes) | V::ItemsArray(nodes) => {
                for i in 0..nodes.len().min(a.len()) {
                    ev[i] = true;
                }
            }
            V::ItemsAll { .. } | V::ItemsSkip { .. } | V::AdditionalItems { .. } => {
                for e in ev.iter_mut() {
                    *e = true;
                }
            }
            V::Contains { node: c, .. } => {
                if node.draft >= crate::registry::Draft::D2020 {
                    for (i, v) in a.iter().enumerate() {
                        if node_valid(c, v, &child_idx(ip, i), st) {
                            ev[i] = true;
                        }
                    }
                }
            }
            V::UnevaluatedItems { .. } => {
                if !top {
                    for e in ev.iter_mut() {
                        *e = true;
                    }
                }
            }
            V::AllOf(nodes) | V::AnyOf(nodes) | V::OneOf(nodes) => {
                for n in nodes {
                    if node_valid(n, inst, ip, st) {
                        collect_items(n, inst, ip, st, ev, false);
                    }
                }
            }
            V::If { cond, then, els } => {
                if node_valid(cond, inst, ip, st) {
                    collect_items(cond, inst, ip, st, ev, false);
                    if let Some(t) = then {
                        if node_valid(t, inst, ip, st) {
                            collect_items(t, inst, ip, st, ev, false);
                        }
                    }
                } else if let Some(e) = els {
                    if node_valid(e, inst, ip, st) {
                        collect_items(e, inst, ip, st, ev, false);
                    }
                }
            }
            V::DependentSchemas(deps) => {
                if let Value::Object(_) = inst {
                } else {
                    let _ = deps;
                }
            }
            V::Ref(rt) => {
                let n = rt.node();
                if node_valid(&n, inst, ip, st) {
                    collect_items(&n, inst, ip, st, ev, false);
                }
            }
            _ => {}
        }
    }
    if let Some(c) = &node.hidden_if {
        if node_valid(c, inst, ip, st) {
            collect_items(c, inst, ip, st, ev, false);
        }
    }
}

// ---------------------------------------------------------------- iter_errors (text)

pub fn node_errors(n: &Node, inst: &Value, ip: &str, st: &mut St, out: &mut Vec<String>) {
    match &n.kind {
        NodeKind::True => {}
        NodeKind::False => out.push(false_msg(inst)),
        NodeKind::Obj(kws) => {
            for k in kws {
                kw_errors(k, n, inst, ip, st, out);
            }
        }
    }
}

fn kw_errors(k: &Kw, parent: &Node, inst: &Value, ip: &str, st: &mut St, out: &mut Vec<String>) {
    if let Some(errs) = simple_errors(k, inst) {
        for (_, m, _) in errs {
            out.push(m);
        }
        return;
    }
    match &k.v {
        V::DependentRequired(deps) => {
            if let Value::Object(o) = inst {
                for (key, req) in deps {
                    if o.contains_key(key) {
                        for r in req {
                            if !o.contains_key(r) {
                                out.push(required_msg(r));
                            }
                        }
                    }
                }
            }
        }
        V::Properties { props, required } => {
            if let Value::Object(o) = inst {
                if let Some(req) = required {
                    for r in req {
                        if !o.contains_key(r) {
                            out.push(required_msg(r));
                        }
                    }
                }
                for (name, node) in props {
                    if let Some(v) = o.get(name) {
                        node_errors(node, v, &child_path(ip, name), st, out);
                    }
                }
            }
        }
        V::PatternProperties(pats) => {
            if let Value::Object(o) = inst {
                for (p, node) in pats {
                    for (key, v) in o {
                        if p.is_match(key) {
                            node_errors(node, v, &child_path(ip, key), st, out);
                        }
                    }
                }
            }
        }
        V::AdditionalProperties(ap) => {
            if let Value::Object(o) = inst {
                if ap.is_false && !ap.has_props && !ap.has_patterns {
                    if let Some((_, v)) = o.iter().next() {
                        out.push(false_msg(v));
                    }
                    return;
                }
                let mut unexpected = vec![];
                for (key, v) in o {
                    let cp = child_path(ip, key);
                    let mut matched = false;
                    if let Some((_, n)) = ap.props.iter().find(|(n, _)| n == key) {
                        matched = true;
                        node_errors(n, v, &cp, st, out);
                    }
                    for (p, n) in &ap.patterns {
                        if p.is_match(key) {
                            matched = true;
                            node_errors(n, v, &cp, st, out);
                        }
                    }
                    if !matched {
                        if ap.is_false {
                            unexpected.push(key.clone());
                        } else {
                            node_errors(&ap.schema, v, &cp, st, out);
                        }
                    }
                }
                if !unexpected.is_empty() {
                    out.push(format!("Additional properties are not allowed ({} {} unexpected)", quoted_list(&unexpected), was_were(unexpected.len())));
                }
            }
        }
        V::PropertyNames(node) => {
            if let Value::Object(o) = inst {
                for key in o.keys() {
                    node_errors(node, &Value::String(key.clone()), ip, st, out);
                }
            }
        }
        V::ItemsAll { node, .. } => {
            if let Value::Array(a) = inst {
                for (i, v) in a.iter().enumerate() {
                    node_errors(node, v, &child_idx(ip, i), st, out);
                }
            }
        }
        V::ItemsArray(nodes) | V::PrefixItems(nodes) => {
            if let Value::Array(a) = inst {
                for (i, (v, n)) in a.iter().zip(nodes.iter()).enumerate() {
                    node_errors(n, v, &child_idx(ip, i), st, out);
                }
            }
        }
        V::ItemsSkip { node, skip } => {
            if let Value::Array(a) = inst {
                for (i, v) in a.iter().enumerate().skip(*skip) {
                    node_errors(node, v, &child_idx(ip, i), st, out);
                }
            }
        }
        V::AdditionalItems { node, skip, is_false } => {
            if let Value::Array(a) = inst {
                if *is_false {
                    if a.len() > *skip {
                        let items: Vec<String> = a[*skip..].iter().map(jstr).collect();
                        out.push(format!("Additional items are not allowed ({} {} unexpected)", items.join(", "), was_were(items.len())));
                    }
                } else {
                    for (i, v) in a.iter().enumerate().skip(*skip) {
                        node_errors(node, v, &child_idx(ip, i), st, out);
                    }
                }
            }
        }
        V::Contains { .. } => {
            if !kw_valid(k, parent, inst, ip, st) {
                out.push(format!("None of {} are valid under the given schema", jstr(inst)));
            }
        }
        V::Dependencies(deps) => {
            if let Value::Object(o) = inst {
                for (key, d) in deps {
                    if !o.contains_key(key) {
                        continue;
                    }
                    match d {
                        DepKind::Required(r) => {
                            for x in r {
                                if !o.contains_key(x) {
                                    out.push(required_msg(x));
                                }
                            }
                        }
                        DepKind::Schema(n) => node_errors(n, inst, ip, st, out),
                    }
                }
            }
        }
        V::DependentSchemas(deps) => {
            if let Value::Object(o) = inst {
                for (key, n) in deps {
                    if o.contains_key(key) {
                        node_errors(n, inst, ip, st, out);
                    }
                }
            }
        }
        V::AllOf(nodes) => {
            for n in nodes {
                node_errors(n, inst, ip, st, out);
            }
        }
        V::AnyOf(nodes) => {
            if !nodes.iter().any(|n| node_valid(n, inst, ip, st)) {
                out.push(format!("{} is not valid under any of the schemas listed in the 'anyOf' keyword", jstr(inst)));
            }
        }
        V::OneOf(nodes) => {
            let mut c = 0;
            for n in nodes {
                if node_valid(n, inst, ip, st) {
                    c += 1;
                    if c > 1 {
                        break;
                    }
                }
            }
            if c == 0 {
                out.push(format!("{} is not valid under any of the schemas listed in the 'oneOf' keyword", jstr(inst)));
            } else if c > 1 {
                out.push(format!("{} is valid under more than one of the schemas listed in the 'oneOf' keyword", jstr(inst)));
            }
        }
        V::Not(n, raw) => {
            if node_valid(n, inst, ip, st) {
                out.push(format!("{} is not allowed for {}", jstr(raw), jstr(inst)));
            }
        }
        V::If { cond, then, els } => {
            if node_valid(cond, inst, ip, st) {
                if let Some(t) = then {
                    node_errors(t, inst, ip, st, out);
                }
            } else if let Some(e) = els {
                node_errors(e, inst, ip, st, out);
            }
        }
        V::UnevaluatedProperties { schema, .. } => {
            if let Value::Object(o) = inst {
                let ev = evaluated_props(parent, inst, ip, st);
                let mut bad = vec![];
                for (key, v) in o {
                    if !ev.contains(key) && !node_valid(schema, v, &child_path(ip, key), st) {
                        bad.push(key.clone());
                    }
                }
                if !bad.is_empty() {
                    out.push(format!("Unevaluated properties are not allowed ({} {} unexpected)", quoted_list(&bad), was_were(bad.len())));
                }
            }
        }
        V::UnevaluatedItems { schema, .. } => {
            if let Value::Array(a) = inst {
                let ev = evaluated_items(parent, inst, ip, st);
                let mut bad = vec![];
                for (i, v) in a.iter().enumerate() {
                    if !ev[i] && !node_valid(schema, v, &child_idx(ip, i), st) {
                        bad.push(jstr(v));
                    }
                }
                if !bad.is_empty() {
                    out.push(format!("Unevaluated items are not allowed ({} {} unexpected)", quoted_list(&bad), was_were(bad.len())));
                }
            }
        }
        V::Ref(rt) => {
            with_ref(rt, ip, st, (), |n, st| node_errors(n, inst, ip, st, out));
        }
        _ => {}
    }
}

// ---------------------------------------------------------------- apply (evaluation output)

pub fn node_apply(n: &Node, inst: &Value, ip: &str, ep: &str, st: &mut St) -> Unit {
    let mut u = Unit::new(ep, &n.loc, ip);
    match &n.kind {
        NodeKind::True => {}
        NodeKind::False => u.error("falseSchema", false_msg(inst)),
        NodeKind::Obj(kws) => {
            for k in kws {
                let c = kw_apply(k, n, inst, ip, ep, st);
                u.add(c);
            }
            u.annotations = n.annotations.clone();
        }
    }
    u
}

fn kw_apply(k: &Kw, parent: &Node, inst: &Value, ip: &str, ep: &str, st: &mut St) -> Unit {
    let kep = format!("{}/{}", ep, ptr_escape(&k.name));
    let mut u = Unit::new(&kep, &k.loc, ip);
    if let Some(errs) = simple_errors(k, inst) {
        for (kind, _, m) in errs {
            u.error(kind, m);
        }
        return u;
    }
    match &k.v {
        V::DependentRequired(deps) => {
            if let Value::Object(o) = inst {
                for (key, req) in deps {
                    if o.contains_key(key) {
                        let mut su = Unit::new(&kep, &k.loc, ip);
                        if !req.is_empty() {
                            let mut ru = Unit::new(&format!("{}/0", kep), &format!("{}/0", k.loc), ip);
                            for r in req {
                                if !o.contains_key(r) {
                                    ru.error("required", required_msg(r));
                                }
                            }
                            su.add(ru);
                        }
                        u.add(su);
                    }
                }
            }
        }
        V::Properties { props, required } => {
            if let Value::Object(o) = inst {
                if let Some(req) = required {
                    if !req.iter().all(|r| o.contains_key(r)) {
                        u.valid = false;
                        return u;
                    }
                }
                let mut ann = vec![];
                for (name, node) in props {
                    if let Some(v) = o.get(name) {
                        ann.push(Value::String(name.clone()));
                        let c = node_apply(node, v, &child_path(ip, name), &child_path(&kep, name), st);
                        u.add(c);
                    }
                }
                u.annotations = Some(Value::Array(ann));
            }
        }
        V::PatternProperties(pats) => {
            if let Value::Object(o) = inst {
                let mut ann = vec![];
                for (p, node) in pats {
                    for (key, v) in o {
                        if p.is_match(key) {
                            ann.push(Value::String(key.clone()));
                            let c = node_apply(node, v, &child_path(ip, key), &child_path(&kep, &p.raw), st);
                            u.add(c);
                        }
                    }
                }
                u.annotations = Some(Value::Array(ann));
            }
        }
        V::AdditionalProperties(ap) => {
            if let Value::Object(o) = inst {
                if ap.is_false && !ap.has_props && !ap.has_patterns {
                    if let Some((_, v)) = o.iter().next() {
                        u.error("falseSchema", false_msg(v));
                    }
                    return u;
                }
                let mut ann = vec![];
                let mut unexpected = vec![];
                let mut pat_ann = vec![];
                let props_ep = format!("{}/properties", ep);
                let pats_ep = format!("{}/patternProperties", ep);
                for (key, v) in o {
                    let cp = child_path(ip, key);
                    let mut matched = false;
                    if let Some((_, n)) = ap.props.iter().find(|(n, _)| n == key) {
                        matched = true;
                        let mut c = node_apply(n, v, &cp, &child_path(&props_ep, key), st);
                        c.schema_loc = format!("{}/{}", ap.props_loc, ptr_escape(key));
                        u.add(c);
                    }
                    for (p, n) in &ap.patterns {
                        if p.is_match(key) {
                            matched = true;
                            pat_ann.push(Value::String(key.clone()));
                            let c = node_apply(n, v, &cp, &child_path(&pats_ep, &p.raw), st);
                            u.add(c);
                        }
                    }
                    if !matched {
                        if ap.is_false {
                            unexpected.push(key.clone());
                        } else {
                            ann.push(Value::String(key.clone()));
                            let c = node_apply(&ap.schema, v, &cp, &kep, st);
                            u.add(c);
                        }
                    }
                }
                if !unexpected.is_empty() {
                    let msg = format!("Additional properties are not allowed ({} {} unexpected)", quoted_list(&unexpected), was_were(unexpected.len()));
                    u.errors.insert(0, ("additionalProperties".to_string(), msg));
                    u.valid = false;
                }
                if !ap.is_false {
                    u.annotations = Some(Value::Array(ann));
                } else if ap.has_props && !ap.has_patterns && unexpected.is_empty() {
                    // valid false with props: no annotations
                }
                if ap.has_patterns && !ap.has_props {
                    let mut pu = Unit::new(&pats_ep, &ap.pats_loc, ip);
                    pu.annotations = Some(Value::Array(pat_ann));
                    u.children.push(pu);
                }
            }
        }
        V::PropertyNames(node) => {
            if let Value::Object(o) = inst {
                for key in o.keys() {
                    let c = node_apply(node, &Value::String(key.clone()), ip, &kep, st);
                    u.add(c);
                }
            }
        }
        V::ItemsAll { node, single_type } => {
            if let Value::Array(a) = inst {
                if let (Some(t), NodeKind::Obj(_)) = (single_type, &node.kind) {
                    for (i, v) in a.iter().enumerate() {
                        if !matches_type(v, *t, node.draft) {
                            let tn = type_names(*t)[0];
                            u.error("type", format!("{} at index {} is not of type \"{}\"", jstr(v), i, tn));
                        }
                    }
                } else {
                    for (i, v) in a.iter().enumerate() {
                        let c = node_apply(node, v, &child_idx(ip, i), &kep, st);
                        u.add(c);
                    }
                }
                u.annotations = Some(Value::Bool(!a.is_empty()));
            }
        }
        V::ItemsArray(nodes) => {
            if let Value::Array(a) = inst {
                for (i, (v, n)) in a.iter().zip(nodes.iter()).enumerate() {
                    let c = node_apply(n, v, &child_idx(ip, i), &child_idx(&kep, i), st);
                    u.add(c);
                }
            }
        }
        V::PrefixItems(nodes) => {
            if let Value::Array(a) = inst {
                for (i, (v, n)) in a.iter().zip(nodes.iter()).enumerate() {
                    let c = node_apply(n, v, &child_idx(ip, i), &child_idx(&kep, i), st);
                    u.add(c);
                }
                if !a.is_empty() {
                    if a.len() <= nodes.len() {
                        u.annotations = Some(Value::Bool(true));
                    } else {
                        u.annotations = Some(Value::from(nodes.len().saturating_sub(1) as u64));
                    }
                }
            }
        }
        V::ItemsSkip { node, skip } => {
            if let Value::Array(a) = inst {
                for (i, v) in a.iter().enumerate().skip(*skip) {
                    let c = node_apply(node, v, &child_idx(ip, i), &kep, st);
                    u.add(c);
                }
                u.annotations = Some(Value::Bool(a.len() > *skip));
            }
        }
        V::AdditionalItems { node, skip, is_false } => {
            if let Value::Array(a) = inst {
                if *is_false {
                    if a.len() > *skip {
                        let items: Vec<String> = a[*skip..].iter().map(jstr).collect();
                        u.error("additionalItems", format!("Additional items are not allowed ({} {} unexpected)", items.join(", "), was_were(items.len())));
                    }
                } else {
                    for (i, v) in a.iter().enumerate().skip(*skip) {
                        let mut errs = vec![];
                        node_errors_kinds(node, v, &child_idx(ip, i), st, &mut errs);
                        for (kind, m) in errs {
                            u.error(&kind, m);
                        }
                    }
                }
            }
        }
        V::Contains { node, minmax, .. } => {
            if let Value::Array(a) = inst {
                if *minmax {
                    if !kw_valid(k, parent, inst, ip, st) {
                        u.error("contains", format!("None of {} are valid under the given schema", jstr(inst)));
                    }
                } else {
                    let mut idx = vec![];
                    let mut kids = vec![];
                    for (i, v) in a.iter().enumerate() {
                        let cip = child_idx(ip, i);
                        if node_valid(node, v, &cip, st) {
                            idx.push(Value::from(i as u64));
                            kids.push(node_apply(node, v, &cip, &kep, st));
                        }
                    }
                    if idx.is_empty() {
                        u.error("contains", format!("None of {} are valid under the given schema", jstr(inst)));
                    } else {
                        u.children = kids;
                        u.annotations = Some(Value::Array(idx));
                    }
                }
            }
        }
        V::Dependencies(deps) => {
            if let Value::Object(o) = inst {
                for (key, d) in deps {
                    if !o.contains_key(key) {
                        continue;
                    }
                    match d {
                        DepKind::Required(req) => {
                            let mut su = Unit::new(&kep, &k.loc, ip);
                            if !req.is_empty() {
                                let mut ru = Unit::new(&format!("{}/0", kep), &format!("{}/0", k.loc), ip);
                                for r in req {
                                    if !o.contains_key(r) {
                                        ru.error("required", required_msg(r));
                                    }
                                }
                                su.add(ru);
                            }
                            u.add(su);
                        }
                        DepKind::Schema(n) => {
                            let c = node_apply(n, inst, ip, &child_path(&kep, key), st);
                            u.add(c);
                        }
                    }
                }
            }
        }
        V::DependentSchemas(deps) => {
            if let Value::Object(o) = inst {
                for (key, n) in deps {
                    if o.contains_key(key) {
                        let c = node_apply(n, inst, ip, &child_path(&kep, key), st);
                        u.add(c);
                    }
                }
            }
        }
        V::AllOf(nodes) => {
            for (i, n) in nodes.iter().enumerate() {
                let c = node_apply(n, inst, ip, &child_idx(&kep, i), st);
                u.add(c);
            }
        }
        V::AnyOf(nodes) => {
            let first = nodes.iter().position(|n| node_valid(n, inst, ip, st));
            match first {
                Some(i) => {
                    let c = node_apply(&nodes[i], inst, ip, &child_idx(&kep, i), st);
                    u.add(c);
                }
                None => {
                    for (i, n) in nodes.iter().enumerate() {
                        let c = node_apply(n, inst, ip, &child_idx(&kep, i), st);
                        u.add(c);
                    }
                }
            }
        }
        V::OneOf(nodes) => {
            let valid: Vec<usize> = (0..nodes.len()).filter(|&i| node_valid(&nodes[i], inst, ip, st)).collect();
            if valid.is_empty() {
                for (i, n) in nodes.iter().enumerate() {
                    let c = node_apply(n, inst, ip, &child_idx(&kep, i), st);
                    u.add(c);
                }
            } else {
                if valid.len() > 1 {
                    u.error("oneOf", "more than one subschema succeeded".to_string());
                }
                for i in valid {
                    let c = node_apply(&nodes[i], inst, ip, &child_idx(&kep, i), st);
                    u.add(c);
                }
            }
        }
        V::Not(n, raw) => {
            if node_valid(n, inst, ip, st) {
                u.error("not", format!("{} is not allowed for {}", jstr(raw), jstr(inst)));
            }
        }
        V::If { cond, then, els } => {
            if node_valid(cond, inst, ip, st) {
                if let Some(t) = then {
                    let c = node_apply(cond, inst, ip, &kep, st);
                    u.add(c);
                    let c = node_apply(t, inst, ip, &format!("{}/then", ep), st);
                    u.add(c);
                } else {
                    let c = node_apply(cond, inst, ip, &kep, st);
                    u.add(c);
                }
            } else if let Some(e) = els {
                let c = node_apply(e, inst, ip, &format!("{}/else", ep), st);
                u.add(c);
            }
        }
        V::UnevaluatedProperties { schema, is_false } => {
            if let Value::Object(o) = inst {
                let ev = evaluated_props(parent, inst, ip, st);
                let mut bad = vec![];
                let mut kids = vec![];
                for (key, v) in o {
                    if ev.contains(key) {
                        continue;
                    }
                    let cp = child_path(ip, key);
                    if *is_false || !node_valid(schema, v, &cp, st) {
                        bad.push(key.clone());
                        kids.push(node_apply(schema, v, &cp, &kep, st));
                    }
                }
                if !bad.is_empty() {
                    u.error(
                        "unevaluatedProperties",
                        format!("Unevaluated properties are not allowed ({} {} unexpected)", quoted_list(&bad), was_were(bad.len())),
                    );
                    for c in kids {
                        u.add(c);
                    }
                }
            }
        }
        V::UnevaluatedItems { schema, is_false } => {
            if let Value::Array(a) = inst {
                let ev = evaluated_items(parent, inst, ip, st);
                let mut bad = vec![];
                let mut kids = vec![];
                for (i, v) in a.iter().enumerate() {
                    if ev[i] {
                        continue;
                    }
                    let cp = child_idx(ip, i);
                    if *is_false || !node_valid(schema, v, &cp, st) {
                        bad.push(jstr(v));
                        kids.push(node_apply(schema, v, &cp, &kep, st));
                    }
                }
                if !bad.is_empty() {
                    u.error("unevaluatedItems", format!("Unevaluated items are not allowed ({} {} unexpected)", quoted_list(&bad), was_were(bad.len())));
                    for c in kids {
                        u.add(c);
                    }
                }
            }
        }
        V::Ref(rt) => {
            let loc = k.loc.clone();
            let r = with_ref(rt, ip, st, None, |n, st| Some(node_apply(n, inst, ip, &kep, st)));
            match r {
                Some(mut c) => {
                    c.schema_loc = loc;
                    return c;
                }
                None => return u,
            }
        }
        _ => {}
    }
    u
}

/// iter_errors with kinds (used by "default apply" keywords)
fn node_errors_kinds(n: &Node, inst: &Value, ip: &str, st: &mut St, out: &mut Vec<(String, String)>) {
    // Approximation: run text errors and derive kinds via apply units
    let u = node_apply(n, inst, ip, "", st);
    collect_unit_errors(&u, out);
}

fn collect_unit_errors(u: &Unit, out: &mut Vec<(String, String)>) {
    for (k, m) in &u.errors {
        out.push((k.clone(), m.clone()));
    }
    for c in &u.children {
        collect_unit_errors(c, out);
    }
}
