fn digits(b: &[u8]) -> bool {
    !b.is_empty() && b.iter().all(|c| c.is_ascii_digit())
}

fn num(b: &[u8]) -> u32 {
    b.iter().fold(0u32, |a, &c| a * 10 + (c - b'0') as u32)
}

fn is_leap(y: u32) -> bool {
    (y % 4 == 0 && y % 100 != 0) || y % 400 == 0
}

pub fn is_date(s: &str) -> bool {
    let b = s.as_bytes();
    if b.len() != 10 || b[4] != b'-' || b[7] != b'-' {
        return false;
    }
    if !digits(&b[0..4]) || !digits(&b[5..7]) || !digits(&b[8..10]) {
        return false;
    }
    let y = num(&b[0..4]);
    let m = num(&b[5..7]);
    let d = num(&b[8..10]);
    if !(1..=12).contains(&m) || d == 0 {
        return false;
    }
    let max = match m {
        1 | 3 | 5 | 7 | 8 | 10 | 12 => 31,
        4 | 6 | 9 | 11 => 30,
        _ => {
            if is_leap(y) {
                29
            } else {
                28
            }
        }
    };
    d <= max
}

pub fn is_time(s: &str) -> bool {
    let b = s.as_bytes();
    if b.len() < 9 {
        return false;
    }
    if b[2] != b':' || b[5] != b':' || !digits(&b[0..2]) || !digits(&b[3..5]) || !digits(&b[6..8]) {
        return false;
    }
    let h = num(&b[0..2]);
    let m = num(&b[3..5]);
    let sec = num(&b[6..8]);
    if h > 23 || m > 59 || sec > 60 {
        return false;
    }
    let mut i = 8;
    if i < b.len() && b[i] == b'.' {
        i += 1;
        let st = i;
        while i < b.len() && b[i].is_ascii_digit() {
            i += 1;
        }
        if i == st {
            return false;
        }
    }
    if i >= b.len() {
        return false;
    }
    let (oh, om, neg) = match b[i] {
        b'Z' | b'z' => {
            if i + 1 != b.len() {
                return false;
            }
            (0i32, 0i32, false)
        }
        b'+' | b'-' => {
            let r = &b[i + 1..];
            if r.len() != 5 || r[2] != b':' || !digits(&r[0..2]) || !digits(&r[3..5]) {
                return false;
            }
            let oh = num(&r[0..2]) as i32;
            let om = num(&r[3..5]) as i32;
            if oh > 23 || om > 59 {
                return false;
            }
            (oh, om, b[i] == b'-')
        }
        _ => return false,
    };
    if sec == 60 {
        // leap second: must be 23:59:60 UTC
        let mut total = h as i32 * 60 + m as i32;
        let off = oh * 60 + om;
        total = if neg { total + off } else { total - off };
        total = ((total % 1440) + 1440) % 1440;
        if total != 23 * 60 + 59 {
            return false;
        }
    }
    true
}

pub fn is_date_time(s: &str) -> bool {
    let b = s.as_bytes();
    if b.len() < 20 {
        return false;
    }
    if b[10] != b'T' && b[10] != b't' {
        return false;
    }
    is_date(&s[..10]) && is_time(&s[11..])
}

pub fn is_duration(s: &str) -> bool {
    let b = s.as_bytes();
    if b.is_empty() || b[0] != b'P' {
        return false;
    }
    let mut i = 1;
    if i >= b.len() {
        return false;
    }
    // week form
    let rest = &s[1..];
    if rest.ends_with('W') {
        let d = &rest.as_bytes()[..rest.len() - 1];
        return digits(d);
    }
    let order_date = [b'Y', b'M', b'D'];
    let order_time = [b'H', b'M', b'S'];
    let mut pos = 0;
    let mut any = false;
    while i < b.len() && b[i] != b'T' {
        let st = i;
        while i < b.len() && b[i].is_ascii_digit() {
            i += 1;
        }
        if i == st || i >= b.len() {
            return false;
        }
        let u = b[i];
        let idx = match order_date.iter().position(|&c| c == u) {
            Some(x) => x,
            None => return false,
        };
        if idx < pos {
            return false;
        }
        pos = idx + 1;
        any = true;
        i += 1;
    }
    if i < b.len() && b[i] == b'T' {
        i += 1;
        let mut tpos = 0;
        let mut tany = false;
        while i < b.len() {
            let st = i;
            while i < b.len() && b[i].is_ascii_digit() {
                i += 1;
            }
            if i == st || i >= b.len() {
                return false;
            }
            let u = b[i];
            let idx = match order_time.iter().position(|&c| c == u) {
                Some(x) => x,
