//! Translation of ECMA-262 regular expressions to Rust regex syntax.

const WS: &str = " \t\n\r\u{b}\u{c}\u{a0}\u{feff}\u{2003}\u{2029}";

pub fn translate(p: &str) -> Option<String> {
    let chars: Vec<char> = p.chars().collect();
    let mut out = String::new();
    let mut i = 0;
    let mut in_class = false;
    while i < chars.len() {
        let c = chars[i];
        if c == '\\' && i + 1 < chars.len() {
            let n = chars[i + 1];
            let rep: Option<String> = match n {
                'd' => Some(if in_class { "[0-9]".into() } else { "[0-9]".into() }),
                'D' => Some("[^0-9]".into()),
                'w' => Some("[A-Za-z0-9_]".into()),
                'W' => Some("[^A-Za-z0-9_]".into()),
                's' => Some(format!("[{}]", WS)),
                'S' => Some(format!("[^{}]", WS)),
                'c' => {
                    if i + 2 < chars.len() && chars[i + 2].is_ascii_alphabetic() {
                        let ctl = (chars[i + 2] as u32) % 32;
                        let ch = char::from_u32(ctl).unwrap();
                        out.push(ch);
                        i += 3;
                        continue;
                    }
                    None
                }
                _ => None,
            };
            match rep {
                Some(r) => {
                    out.push_str(&r);
                    i += 2;
                }
                None => {
                    out.push(c);
                    out.push(n);
                    i += 2;
                }
            }
            continue;
        }
        if c == '[' && !in_class {
            in_class = true;
            out.push(c);
            i += 1;
            if i < chars.len() && chars[i] == '^' {
                out.push('^');
                i += 1;
            }
            if i < chars.len() && chars[i] == ']' {
                out.push(']');
                i += 1;
            }
            continue;
        }
        if c == ']' && in_class {
            in_class = false;
        }
        out.push(c);
        i += 1;
    }
    Some(out)
}
