actions.command:
cd /workspace && cat > src/main.rs <<'EOF'
mod ecma;
mod engine;
mod formats;
mod num;
mod registry;
mod uri;
mod validate;

use clap::{Arg, ArgAction, Command};
use engine::{Compiler, Ctx, Node, Options};
use registry::{Draft, Registry};
use serde_json::{Map, Value};
use std::cell::OnceCell;
use std::io::Write;
use std::process::exit;
use std::rc::Rc;
use validate::{St, Unit};

const META: &[(&str, &str, Draft)] = &[
    ("http://json-schema.org/draft-04/schema", include_str!("meta/d4.json"), Draft::D4),
    ("http://json-schema.org/draft-06/schema", include_str!("meta/d6.json"), Draft::D6),
    ("http://json-schema.org/draft-07/schema", include_str!("meta/d7.json"), Draft::D7),
    ("https://json-schema.org/draft/2019-09/schema", include_str!("meta/d201909_schema.json"), Draft::D2019),
    ("https://json-schema.org/draft/2019-09/meta/core", include_str!("meta/d201909_core.json"), Draft::D2019),
    ("https://json-schema.org/draft/2019-09/meta/applicator", include_str!("meta/d201909_applicator.json"), Draft::D2019),
    ("https://json-schema.org/draft/2019-09/meta/validation", include_str!("meta/d201909_validation.json"), Draft::D2019),
    ("https://json-schema.org/draft/2019-09/meta/meta-data", include_str!("meta/d201909_meta-data.json"), Draft::D2019),
    ("https://json-schema.org/draft/2019-09/meta/format", include_str!("meta/d201909_format.json"), Draft::D2019),
    ("https://json-schema.org/draft/2019-09/meta/content", include_str!("meta/d201909_content.json"), Draft::D2019),
    ("https://json-schema.org/draft/2020-12/schema", include_str!("meta/d202012_schema.json"), Draft::D2020),
    ("https://json-schema.org/draft/2020-12/meta/core", include_str!("meta/d202012_core.json"), Draft::D2020),
    ("https://json-schema.org/draft/2020-12/meta/applicator", include_str!("meta/d202012_applicator.json"), Draft::D2020),
    ("https://json-schema.org/draft/2020-12/meta/unevaluated", include_str!("meta/d202012_unevaluated.json"), Draft::D2020),
    ("https://json-schema.org/draft/2020-12/meta/validation", include_str!("meta/d202012_validation.json"), Draft::D2020),
    ("https://json-schema.org/draft/2020-12/meta/meta-data", include_str!("meta/d202012_meta-data.json"), Draft::D2020),
    ("https://json-schema.org/draft/2020-12/meta/format-annotation", include_str!("meta/d202012_format-annotation.json"), Draft::D2020),
    ("https://json-schema.org/draft/2020-12/meta/content", include_str!("meta/d202012_content.json"), Draft::D2020),
];

fn meta_root(d: Draft) -> &'static str {
    match d {
        Draft::D4 => "http://json-schema.org/draft-04/schema",
        Draft::D6 => "http://json-schema.org/draft-06/schema",
        Draft::D7 => "http://json-schema.org/draft-07/schema",
        Draft::D2019 => "https://json-schema.org/draft/2019-09/schema",
        Draft::D2020 => "https://json-schema.org/draft/2020-12/schema",
    }
}

fn parse_seconds(s: &str) -> Result<f64, String> {
    match s.parse::<f64>() {
        Ok(v) => {
            if v.is_finite() && v >= 0.0 {
                Ok(v)
            } else {
                Err("must be a non-negative finite number".to_string())
            }
        }
        Err(_) => Err(format!("'{}' is not a valid number", s)),
    }
}

fn build_cli() -> Command {
    Command::new("jsonschema-cli")
        .disable_version_flag(true)
        .arg(
            Arg::new("instances")
                .short('i')
                .long("instance")
                .value_name("INSTANCES")
                .action(ArgAction::Append)
                .help("A path to a JSON instance (i.e. filename.json) to validate (may be specified multiple times)"),
        )
        .arg(Arg::new("schema").value_name("SCHEMA").required_unless_present("version").help("The JSON Schema to validate with (i.e. schema.json)"))
        .arg(
            Arg::new("draft")
                .short('d')
                .long("draft")
                .value_name("DRAFT")
                .value_parser(["4", "6", "7", "2019", "2020"])
                .help("Enforce a specific JSON Schema draft"),
        )
        .arg(
            Arg::new("assert_format")
                .long("assert-format")
                .action(ArgAction::SetTrue)
                .overrides_with("no_assert_format")
                .help("Turn ON format validation"),
        )
        .arg(
            Arg::new("no_assert_format")
                .long("no-assert-format")
                .action(ArgAction::SetTrue)
                .overrides_with("assert_format")
                .help("Turn OFF format validation"),
        )
        .arg(
            Arg::new("output")
                .long("output")
                .value_name("OUTPUT")
                .default_value("text")
                .value_parser(["text", "flag", "list", "hierarchical"])
                .help("Select output style: text (default), flag, list, hierarchical"),
        )
        .arg(Arg::new("version").short('v').long("version").action(ArgAction::SetTrue).help("Show program's version number and exit"))
        .arg(Arg::new("errors_only").long("errors-only").action(ArgAction::SetTrue).help("Only show validation errors"))
        .arg(
            Arg::new("connect_timeout")
                .long("connect-timeout")
                .value_name("SECONDS")
                .value_parser(parse_seconds)
                .help("Timeout for establishing connections (in seconds)"),
        )
        .arg(
            Arg::new("timeout")
                .long("timeout")
                .value_name("SECONDS")
                .value_parser(parse_seconds)
                .help("Total timeout for HTTP requests (in seconds)"),
        )
        .arg(Arg::new("insecure").short('k').long("insecure").action(ArgAction::SetTrue).help("Skip TLS certificate verification (dangerous!)"))
        .arg(Arg::new("cacert").long("cacert").value_name("FILE").help("Path to a custom CA certificate file (PEM format)"))
}

fn read_json(path: &str) -> Result<Value, String> {
    let bytes = std::fs::read(path).map_err(|e| e.to_string())?;
    serde_json::from_slice::<Value>(&bytes).map_err(|e| e.to_string())
}

fn file_base(path: &str) -> String {
    let p = std::fs::canonicalize(path).unwrap_or_else(|_| std::path::PathBuf::from(path));
    uri::file_path_to_uri(&p.to_string_lossy())
}

pub fn retrieve(uri_s: &str) -> Result<Value, String> {
    let u = uri::parse(uri_s).map_err(|e| e.message())?;
    let scheme = u.scheme.clone().unwrap_or_default();
    match scheme.as_str() {
        "file" => {
            let path = uri::percent_decode(&u.path);
            let bytes = std::fs::read(&path).map_err(|e| e.to_string())?;
            serde_json::from_slice::<Value>(&bytes).map_err(|e| e.to_string())
        }
        "http" | "https" => Err(format!("error sending request for url ({})", uri_s)),
        other => Err(format!("Unknown scheme {}", other)),
    }
}

struct Built {
    root: Rc<Node>,
}

fn detect_draft(schema: &Value, forced: Option<Draft>) -> Result<(Draft, Option<Value>), String> {
    if let Some(d) = forced {
        return Ok((d, None));
    }
    match schema {
        Value::Object(o) => match o.get("$schema") {
            Some(Value::String(s)) => {
                if let Some(d) = registry::draft_from_schema_uri(s) {
                    return Ok((d, None));
                }
                // custom metaschema
                match retrieve(s) {
                    Ok(meta) => {
                        let d = match &meta {
                            Value::Object(m) => match m.get("$schema") {
                                Some(Value::String(ms)) => registry::draft_from_schema_uri(ms).unwrap_or(Draft::D2020),
                                _ => Draft::D2020,
                            },
                            _ => Draft::D2020,
                        };
                        Ok((d, Some(meta)))
                    }
                    Err(_) => Err(format!("Unknown meta-schema: '{}'. Custom meta-schemas must be registered in the registry before use", s)),
                }
            }
            _ => Ok((Draft::D2020, None)),
        },
        _ => Ok((Draft::D2020, None)),
    }
}

fn new_registry(draft: Draft) -> Result<(Registry, Vec<(String, uri::Uri, bool)>), String> {
    let mut reg = Registry::new();
    let mut refs = vec![];
    for (u, text, d) in META {
        if *d == draft {
            let v: Value = serde_json::from_str(text).unwrap();
            let mut ignored = vec![];
            reg.add_document(u, v, *d, &mut ignored)?;
        }
    }
    let _ = &mut refs;
    Ok((reg, refs))
}

fn make_compiler(reg: Registry, validate_formats: bool, vocab_none: bool, vocab: Option<Vec<String>>) -> Rc<Compiler> {
    let c = Rc::new(Compiler { reg: Rc::new(reg), opts: Options { validate_formats, vocab_none, vocab }, self_rc: OnceCell::new() });
    let _ = c.self_rc.set(Rc::downgrade(&c));
    c
}

fn root_ctx(base: &str, draft: Draft) -> Ctx {
    let mut b = uri::parse(base).unwrap_or_default();
    uri::normalize(&mut b);
    Ctx { base: b.clone(), ptr: String::new(), draft, ref_stack: Rc::new(vec![]), scope: Rc::new(vec![b.to_string_no_fragment()]) }
}

/// Compile the meta-schema validator for a given draft
fn meta_validator(draft: Draft, custom: Option<(&str, Value)>) -> Result<Rc<Node>, String> {
    let (mut reg, _) = new_registry(draft)?;
    let (uri_s, mut refs) = match custom {
        Some((u, v)) => {
            let mut refs = vec![];
            reg.add_document(u, v, draft, &mut refs)?;
            (u.to_string(), refs)
        }
        None => (meta_root(draft).to_string(), vec![]),
    };
    reg.process_refs(std::mem::take(&mut refs), &retrieve, draft)?;
    let fmt = draft <= Draft::D7;
    let comp = make_compiler(reg, fmt, false, None);
    let loc = comp.reg.resources.get(&uri_s).cloned().unwrap();
    let v = comp.reg.get(&loc).cloned().unwrap();
    // base from $id when present
    let base = match &v {
        Value::Object(o) => match o.get(if draft == Draft::D4 { "id" } else { "$id" }) {
            Some(Value::String(id)) => id.trim_end_matches('#').to_string(),
            _ => uri_s.clone(),
        },
        _ => uri_s.clone(),
    };
    let ctx = root_ctx(&base, draft);
    comp.compile_node(&v, &ctx)
}

fn schema_meta(schema: &Value, forced: Option<Draft>) -> Result<Rc<Node>, String> {
    // Determine meta-schema used for checking the schema itself
    let _ = forced;
    if let Value::Object(o) = schema {
        if let Some(Value::String(s)) = o.get("$schema") {
            if let Some(d) = registry::draft_from_schema_uri(s) {
                return meta_validator(d, None);
            }
            // custom meta-schema: retrieve
            let mv = retrieve(s).map_err(|e| format!("Resource '{}' is not present in a registry and retrieving it failed: {}", s, e))?;
            let d = match &mv {
                Value::Object(m) => match m.get("$schema") {
                    Some(Value::String(ms)) => registry::draft_from_schema_uri(ms).unwrap_or(Draft::D2020),
                    _ => Draft::D2020,
                },
                _ => Draft::D2020,
            };
            return meta_validator(d, Some((s, mv)));
        }
    }
    meta_validator(Draft::D2020, None)
}

fn meta_draft_for_text(schema: &Value, forced: Option<Draft>) -> Option<Draft> {
    if let Some(d) = forced {
        return Some(d);
    }
    if let Value::Object(o) = schema {
        if let Some(Value::String(s)) = o.get("$schema") {
            return registry::draft_from_schema_uri(s);
        }
    }
    Some(Draft::D2020)
}

fn first_error(node: &Node, inst: &Value) -> Option<String> {
    let mut st = St::new();
    if validate::node_valid(node, inst, "", &mut st) {
        return None;
    }
    let mut out = vec![];
    validate::node_errors(node, inst, "", &mut st, &mut out);
    out.into_iter().next().or(Some(String::new()))
}

fn build(schema: &Value, base: &str, forced: Option<Draft>, validate_formats: bool) -> Result<Built, String> {
    let (draft, custom_meta) = detect_draft(schema, forced)?;
    let (mut reg, _) = new_registry(draft)?;
    let mut refs = vec![];
    reg.add_document(base, schema.clone(), draft, &mut refs)?;
    reg.process_refs(refs, &retrieve, draft)?;
    // meta-schema validation
    let meta = match &custom_meta {
        Some(m) => {
            let s = schema.get("$schema").and_then(|v| v.as_str()).unwrap_or("");
            meta_validator(
                match m {
                    Value::Object(mm) => match mm.get("$schema") {
                        Some(Value::String(ms)) => registry::draft_from_schema_uri(ms).unwrap_or(Draft::D2020),
                        _ => Draft::D2020,
                    },
                    _ => Draft::D2020,
                },
                Some((s, m.clone())),
            )?
        }
        None => {
            let md = meta_draft_for_text(schema, forced).unwrap_or(draft);
            meta_validator(md, None)?
        }
    };
    if let Some(e) = first_error(&meta, schema) {
        return Err(e);
    }
    // vocabularies
    let mut vocab_none = false;
    let mut vocab: Option<Vec<String>> = None;
    if draft >= Draft::D2019 {
        if let Value::Object(o) = schema {
            if let Some(Value::String(s)) = o.get("$schema") {
                match registry::draft_from_schema_uri(s) {
                    Some(d) if d < Draft::D2019 => vocab_none = true,
                    Some(_) => {}
                    None => {
                        if let Some(Value::Object(m)) = &custom_meta {
                            if m.contains_key("$id") {
                                if let Some(Value::Object(voc)) = m.get("$vocabulary") {
                                    vocab = Some(voc.keys().cloned().collect());
                                }
                            }
                        }
                    }
                }
            }
        }
    }
    let comp = make_compiler(reg, validate_formats, vocab_none, vocab);
    let ctx = root_ctx(base, draft);
    let root = comp.compile_node(schema, &ctx)?;
    Ok(Built { root })
}

// ---------------------------------------------------------------- output

fn unit_json(u: &Unit, hier: bool) -> Value {
    let mut m = Map::new();
    if let Some(a) = &u.annotations {
        if u.valid {
            m.insert("annotations".into(), a.clone());
        } else {
            m.insert("droppedAnnotations".into(), a.clone());
        }
    }
    if hier && !u.children.is_empty() {
        m.insert("details".into(), Value::Array(u.children.iter().map(|c| unit_json(c, true)).collect()));
    }
    if !u.errors.is_empty() {
        let mut em = Map::new();
        for (k, msg) in &u.errors {
            match em.get_mut(k) {
                None => {
                    em.insert(k.clone(), Value::String(msg.clone()));
                }
                Some(Value::Array(a)) => a.push(Value::String(msg.clone())),
                Some(existing) => {
                    let prev = existing.clone();
                    *existing = Value::Array(vec![prev, Value::String(msg.clone())]);
                }
            }
        }
        m.insert("errors".into(), Value::Object(em));
    }
    m.insert("evaluationPath".into(), Value::String(u.eval_path.clone()));
    m.insert("instanceLocation".into(), Value::String(u.inst_loc.clone()));
    m.insert("schemaLocation".into(), Value::String(u.schema_loc.clone()));
    m.insert("valid".into(), Value::Bool(u.valid));
    Value::Object(m)
}

fn flatten(u: &Unit, out: &mut Vec<Value>) {
    out.push(unit_json(u, false));
    for c in &u.children {
        flatten(c, out);
    }
}

fn payload(u: &Unit, mode: &str) -> Value {
    match mode {
        "flag" => {
            let mut m = Map::new();
            m.insert("valid".into(), Value::Bool(u.valid));
            Value::Object(m)
        }
        "list" => {
            let mut v = vec![];
            flatten(u, &mut v);
            let mut m = Map::new();
            m.insert("details".into(), Value::Array(v));
            m.insert("valid".into(), Value::Bool(u.valid));
            Value::Object(m)
        }
        _ => unit_json(u, true),
    }
}

fn evaluate(node: &Node, inst: &Value) -> Unit {
    let mut st = St::new();
    validate::node_apply(node, inst, "", "", &mut st)
}

fn print_line(s: &str) {
    let stdout = std::io::stdout();
    let mut h = stdout.lock();
    let _ = writeln!(h, "{}", s);
}

fn main() {
    let m = build_cli().get_matches();
    if m.get_flag("version") {
        print_line("Version: 0.41.0");
        exit(0);
    }
    let schema_path = m.get_one::<String>("schema").cloned().unwrap_or_default();
    if let Some(t) = m.get_one::<f64>("connect_timeout") {
        let _ = std::time::Duration::from_secs_f64(*t);
    }
    if let Some(t) = m.get_one::<f64>("timeout") {
        let _ = std::time::Duration::from_secs_f64(*t);
    }
    let instances: Vec<String> = m.get_many::<String>("instances").map(|v| v.cloned().collect()).unwrap_or_default();
    let forced = m.get_one::<String>("draft").map(|d| match d.as_str() {
        "4" => Draft::D4,
        "6" => Draft::D6,
        "7" => Draft::D7,
        "2019" => Draft::D2019,
        _ => Draft::D2020,
    });
    let validate_formats = m.get_flag("assert_format");
    let output = m.get_one::<String>("output").cloned().unwrap_or_else(|| "text".into());
    let errors_only = m.get_flag("errors_only");
    let cacert = m.get_one::<String>("cacert").cloned();

    let schema = match read_json(&schema_path) {
        Ok(v) => v,
        Err(e) => {
            print_line(&format!("Error: {}", e));
            exit(1);
        }
    };
    let base = file_base(&schema_path);
    let read_cacert = || {
        if let Some(c) = &cacert {
            if let Err(e) = std::fs::read(c) {
                print_line(&format!("Error: Failed to read certificate file '{}': {}", c, e));
                exit(1);
            }
        }
    };
    let structured = output != "text";

    let schema_out = |u: &Unit| {
        let mut m = Map::new();
        m.insert("output".into(), Value::String(output.clone()));
        m.insert("payload".into(), payload(u, &output));
        m.insert("schema".into(), Value::String(schema_path.clone()));
        serde_json::to_string(&Value::Object(m)).unwrap()
    };

    if !instances.is_empty() {
        read_cacert();
        if !structured {
            let built = match build(&schema, &base, forced, validate_formats) {
                Ok(b) => b,
                Err(e) => {
                    print_line(&format!("Schema is invalid. Error: {}", e));
                    exit(1);
                }
            };
            let mut ok = true;
            for inst_path in &instances {
                let inst = match read_json(inst_path) {
                    Ok(v) => v,
                    Err(e) => {
                        print_line(&format!("Error: {}", e));
                        exit(1);
                    }
                };
                let mut st = St::new();
                if validate::node_valid(&built.root, &inst, "", &mut st) {
                    if !errors_only {
                        print_line(&format!("{} - VALID", inst_path));
                    }
                } else {
                    ok = false;
                    let mut errs = vec![];
                    validate::node_errors(&built.root, &inst, "", &mut st, &mut errs);
                    let mut s = format!("{} - INVALID. Errors:", inst_path);
                    for (i, e) in errs.iter().enumerate() {
                        s.push_str(&format!("\n{}. {}", i + 1, e));
                    }
                    print_line(&s);
                }
            }
            exit(if ok { 0 } else { 1 });
        } else {
            let meta = match schema_meta(&schema, forced) {
                Ok(m) => m,
                Err(e) => {
                    print_line(&format!("Error: {}", e));
                    exit(1);
                }
            };
            let mu = evaluate(&meta, &schema);
            if !mu.valid {
                print_line(&schema_out(&mu));
                exit(1);
            }
            let built = match build(&schema, &base, forced, validate_formats) {
                Ok(b) => b,
                Err(e) => {
                    print_line(&format!("Error: {}", e));
                    exit(1);
                }
            };
            let mut ok = true;
            for inst_path in &instances {
                let inst = match read_json(inst_path) {
                    Ok(v) => v,
                    Err(e) => {
                        print_line(&format!("Error: {}", e));
                        exit(1);
                    }
                };
                let u = evaluate(&built.root, &inst);
                if !u.valid {
                    ok = false;
                }
                if errors_only && u.valid {
                    continue;
                }
                let mut mm = Map::new();
                mm.insert("instance".into(), Value::String(inst_path.clone()));
                mm.insert("output".into(), Value::String(output.clone()));
                mm.insert("payload".into(), payload(&u, &output));
                mm.insert("schema".into(), Value::String(schema_path.clone()));
                print_line(&serde_json::to_string(&Value::Object(mm)).unwrap());
            }
            exit(if ok { 0 } else { 1 });
        }
    } else if !structured {
        let meta = match schema_meta(&schema, forced) {
            Ok(m) => m,
            Err(e) => {
                print_line(&format!("Schema is invalid. Error: {}", e));
                exit(1);
            }
        };
        if let Some(e) = first_error(&meta, &schema) {
            print_line(&format!("Schema is invalid. Error: {}", e));
            exit(1);
        }
        read_cacert();
        match build(&schema, &base, forced, validate_formats) {
            Ok(_) => {
                if !errors_only {
                    print_line("Schema is valid");
                }
                exit(0);
            }
            Err(e) => {
                print_line(&format!("Schema is invalid. Error: {}", e));
                exit(1);
            }
        }
    } else {
