fn ch_is(re: &'static std::thread::LocalKey<regex::Regex>, c: char) -> bool {
    let mut buf = [0u8; 4];
    let s = c.encode_utf8(&mut buf);
    re.with(|r| r.is_match(s))
}

pub fn punycode_encode(input: &[char]) -> Option<String> {
    const BASE: u32 = 36;
    const TMIN: u32 = 1;
    const TMAX: u32 = 26;
    const SKEW: u32 = 38;
    const DAMP: u32 = 700;
    fn adapt(mut delta: u32, num_points: u32, first: bool) -> u32 {
        delta /= if first { DAMP } else { 2 };
        delta += delta / num_points;
        let mut k = 0;
        while delta > ((BASE - TMIN) * TMAX) / 2 {
            delta /= BASE - TMIN;
            k += BASE;
        }
        k + (((BASE - TMIN + 1) * delta) / (delta + SKEW))
    }
    fn digit(d: u32) -> char {
        if d < 26 {
            (b'a' + d as u8) as char
        } else {
            (b'0' + (d - 26) as u8) as char
        }
    }
    let mut out: String = input.iter().filter(|c| c.is_ascii()).collect();
    let b = out.len() as u32;
    let mut h = b;
    if b > 0 {
        out.push('-');
    }
    let mut n: u32 = 128;
    let mut delta: u32 = 0;
    let mut bias: u32 = 72;
    let total = input.len() as u32;
    while h < total {
        let m = input.iter().map(|&c| c as u32).filter(|&c| c >= n).min()?;
        delta = delta.checked_add((m - n).checked_mul(h + 1)?)?;
        n = m;
        for &c in input {
            let c = c as u32;
            if c < n {
                delta = delta.checked_add(1)?;
            }
            if c == n {
                let mut q = delta;
                let mut k = BASE;
                loop {
                    let t = if k <= bias {
                        TMIN
                    } else if k >= bias + TMAX {
                        TMAX
                    } else {
                        k - bias
                    };
                    if q < t {
                        break;
                    }
                    out.push(digit(t + (q - t) % (BASE - t)));
                    q = (q - t) / (BASE - t);
                    k += BASE;
                }
                out.push(digit(q));
                bias = adapt(delta, h + 1, h == b);
                delta = 0;
                h += 1;
            }
        }
        delta += 1;
        n += 1;
    }
    Some(out)
}

fn idn_label_ok(label: &[char]) -> bool {
    if label.is_empty() {
        return false;
    }
    if label[0] == '-' || label[label.len() - 1] == '-' {
        return false;
    }
    if label.len() >= 4 && label[2] == '-' && label[3] == '-' {
        return false;
    }
    if ch_is(&RE_MARK, label[0]) {
        return false;
    }
    let mut has_arabic = false;
    let mut has_ext_arabic = false;
    for (i, &c) in label.iter().enumerate() {
        let u = c as u32;
        if c.is_ascii() {
            if !(c.is_ascii_alphanumeric() || c == '-') {
                return false;
            }
            continue;
        }
        match u {
            0x0640 | 0x07FA | 0x302E | 0x302F | 0x3031..=0x3035 | 0x303B => return false,
            0xFF00..=0xFFEF => return false,
            0x00B7 => {
                if !(i > 0 && label[i - 1] == 'l' && i + 1 < label.len() && label[i + 1] == 'l') {
                    return false;
                }
                continue;
            }
            0x0375 => {
                if !(i + 1 < label.len() && ch_is(&RE_GREEK, label[i + 1])) {
                    return false;
                }
                continue;
            }
            0x05F3 | 0x05F4 => {
                if !(i > 0 && ch_is(&RE_HEBREW, label[i - 1])) {
                    return false;
                }
                continue;
            }
            0x30FB => {
                if !label.iter().any(|&x| x != '\u{30FB}' && ch_is(&RE_HKH, x)) {
                    return false;
                }
                continue;
            }
            0x200C | 0x200D => {
                if !(i > 0 && VIRAMAS.contains(&(label[i - 1] as u32))) {
                    return false;
                }
                continue;
            }
            0x0660..=0x0669 => has_arabic = true,
            0x06F0..=0x06F9 => has_ext_arabic = true,
            _ => {}
        }
        if !ch_is(&RE_ALLOWED, c) {
            return false;
        }
    }
    if has_arabic && has_ext_arabic {
        return false;
    }
    true
}

pub fn is_idn_hostname(s: &str) -> bool {
    if s.is_empty() || s.ends_with('.') {
        return false;
    }
    let mut total = 0usize;
    let mut nlabels = 0;
    for label in s.split('.') {
        nlabels += 1;
        let chars: Vec<char> = label.chars().collect();
        if chars.is_empty() {
            return false;
        }
        let ascii_len;
        if label.is_ascii() {
            let lower = label.to_ascii_lowercase();
            if lower.starts_with("xn--") {
                if !label.starts_with("xn--") {
                    return false;
                }
                let decoded = match punycode_decode(&label[4..]) {
                    Some(d) if !d.is_empty() => d,
                    _ => return false,
                };
                if !idn_label_ok(&decoded) {
                    return false;
                }
            } else if !idn_label_ok(&chars) {
                return false;
            }
            ascii_len = label.len();
        } else {
            if !idn_label_ok(&chars) {
                return false;
            }
            let lower: Vec<char> = chars.iter().flat_map(|c| c.to_lowercase()).collect();
            match punycode_encode(&lower) {
                Some(p) => ascii_len = p.len() + 4,
                None => return false,
            }
        }
        if ascii_len > 63 {
            return false;
        }
        total += ascii_len;
    }
    total += nlabels - 1;
    total <= 253
}

