    if label[0] == '-' || label[label.len() - 1] == '-' {
        return false;
    }
    if label.len() >= 4 && label[2] == '-' && label[3] == '-' {
        return false;
    }
    if ch_is(&RE_MARK, label[0]) {
        return false;
    }
    let mut has_arabic = false;
    let mut has_ext_arabic = false;
    for (i, &c) in label.iter().enumerate() {
        let u = c as u32;
        if c.is_ascii() {
            if !(c.is_ascii_alphanumeric() || c == '-') {
                return false;
            }
            continue;
        }
        match u {
            0x0640 | 0x07FA | 0x302E | 0x302F | 0x3031..=0x3035 | 0x303B => return false,
            0xFF00..=0xFFEF => return false,
            0x00B7 => {
                if !(i > 0 && label[i - 1] == 'l' && i + 1 < label.len() && label[i + 1] == 'l') {
                    return false;
                }
                continue;
            }
            0x0375 => {
                if !(i + 1 < label.len() && ch_is(&RE_GREEK, label[i + 1])) {
                    return false;
                }
                continue;
            }
            0x05F3 | 0x05F4 => {
                if !(i > 0 && ch_is(&RE_HEBREW, label[i - 1])) {
                    return false;
                }
                continue;
            }
            0x30FB => {
                if !label.iter().any(|&x| x != '\u{30FB}' && ch_is(&RE_HKH, x)) {
