            return false;
        }
    }
    if has_arabic && has_ext_arabic {
        return false;
    }
    true
}

pub fn is_idn_hostname(s: &str) -> bool {
    if s.is_empty() || s.ends_with('.') {
        return false;
    }
    let mut total = 0usize;
    let mut nlabels = 0;
    for label in s.split('.') {
        nlabels += 1;
        let chars: Vec<char> = label.chars().collect();
        if chars.is_empty() {
            return false;
        }
        let ascii_len;
        if label.is_ascii() {
            let lower = label.to_ascii_lowercase();
            if lower.starts_with("xn--") {
                if !label.starts_with("xn--") {
                    return false;
                }
                let decoded = match punycode_decode(&label[4..]) {
                    Some(d) if !d.is_empty() => d,
                    _ => return false,
                };
                if !idn_label_ok(&decoded) {
                    return false;
                }
            } else if !idn_label_ok(&chars) {
                return false;
            }
            ascii_len = label.len();
        } else {
            if !idn_label_ok(&chars) {
                return false;
            }
            let lower: Vec<char> = chars.iter().flat_map(|c| c.to_lowercase()).collect();
            match punycode_encode(&lower) {
                Some(p) => ascii_len = p.len() + 4,
                None => return false,
            }
        }
        if ascii_len > 63 {
            return false;
        }
        total += ascii_len;
    }
    total += nlabels - 1;
    total <= 253
}

