pub fn content_decode(enc: &str, s: &str) -> Option<Vec<u8>> {
    match enc {
        "base64" => decode_padded(s, b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/", 6),
        "base64url" => decode_padded(s, b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_", 6),
        "base32" => decode_padded(s, b"ABCDEFGHIJKLMNOPQRSTUVWXYZ234567", 5),
        "base16" => {
            let b = s.as_bytes();
            if b.len() % 2 != 0 {
                return None;
            }
            let mut out = vec![];
            for ch in b.chunks(2) {
                let h = (ch[0] as char).to_digit(16)?;
                let l = (ch[1] as char).to_digit(16)?;
                out.push((h * 16 + l) as u8);
            }
            Some(out)
        }
        _ => None,
    }
}

pub fn known_encoding(enc: &str) -> bool {
    matches!(enc, "base64" | "base64url" | "base32" | "base16")
}

fn decode_padded(s: &str, alphabet: &[u8], bits: u32) -> Option<Vec<u8>> {
    let b = s.as_bytes();
    let block = if bits == 6 { 4 } else { 8 };
    if b.len() % block != 0 {
        return None;
    }
    let val = |c: u8| alphabet.iter().position(|&a| a == c).map(|p| p as u64);
    let mut out = vec![];
    for chunk in b.chunks(block) {
        let data_len = chunk.iter().position(|&c| c == b'=').unwrap_or(block);
        if chunk[data_len..].iter().any(|&c| c != b'=') {
            return None;
        }
        // valid data lengths
        let ok = if bits == 6 { matches!(data_len, 2 | 3 | 4) } else { matches!(data_len, 2 | 4 | 5 | 7 | 8) };
        if !ok {
            return None;
        }
        let mut acc: u64 = 0;
