        if chunk[data_len..].iter().any(|&c| c != b'=') {
            return None;
        }
        // valid data lengths
        let ok = if bits == 6 { matches!(data_len, 2 | 3 | 4) } else { matches!(data_len, 2 | 4 | 5 | 7 | 8) };
        if !ok {
            return None;
        }
        let mut acc: u64 = 0;
        for &c in &chunk[..data_len] {
            acc = (acc << bits) | val(c)?;
        }
        let total_bits = data_len as u32 * bits;
        let nbytes = total_bits / 8;
        let extra = total_bits - nbytes * 8;
        if acc & ((1u64 << extra) - 1) != 0 {
            return None;
        }
        acc >>= extra;
        for i in (0..nbytes).rev() {
            out.push(((acc >> (8 * i)) & 0xff) as u8);
        }
    }
    Some(out)
}

